# German localization: shared home for translations and future text corrections.
# ---- RE - Sprachauswahl.rb ----
LANGUAGES = [  
  ["German","german.dat"],
  ["English","english.dat"]
]

# ---- RE - Deutsche-Zusatztexte.rb ----
# encoding: UTF-8
# Local German supplement, independent of Reborn/AllGen implementation files.
# Remove this one file to uninstall. No save, network or disk writes at runtime.
module LocalGermanText
  VERSION = '2.0.0'

  def self.key(text)
    return nil unless text.is_a?(String)
    value = text.dup
    value.force_encoding(Encoding::UTF_8) if value.encoding == Encoding::ASCII_8BIT
    return nil unless value.valid_encoding?
    value.gsub(/[ \t\r\n]+/, ' ').strip
  end

