    120 => {
      "\"All about Gorebyss, the South Sea Pokémon\"" => "„Alles über Saganabyss, das Südsee-Pokémon“",
      "\"National Dex Number 368, Gorebyss is a unique species in terms of its evolution." => "Saganabyss trägt die Nummer 368 im Nationalen Pokédex und ist wegen seiner Entwicklung eine besondere Art.",
      "Additionally, whereas Huntail's natural movepool takes on a Dark pseudo-type, Gorebyss' could be said to follow that of a Psycho-type." => "Während Aalabyss’ natürliches Attackenrepertoire eher einen Unlicht-Einschlag hat, könnte man Saganabyss’ Repertoire als Psycho-artig bezeichnen.",
      "Also notable, whereas Discharge is learned by a wide variety of Pokémon, only 21 Pokémon can learn Lava Plume.\"" => "Bemerkenswert ist auch: Obwohl sehr viele Pokémon Ladungsstoß lernen, können nur 21 Pokémon Lavasturm erlernen.",
      "Gorebyss retains different strengths than Huntail however, such as a more special-based movepool to compliment its boosted Sp.Attack stat." => "Saganabyss hat jedoch andere Stärken als Aalabyss. Sein Attackenrepertoire ist stärker auf Spezial-Attacken ausgelegt und passt zu seinem hohen Spezial-Angriff.",
      "Its pre-evolution, Clamperl, may become either Gorebyss or its brother species, Huntail, depending on what item is held when it is traded." => "Seine Vorentwicklung Perlu kann sich beim Tausch je nach getragenem Item entweder zu Saganabyss oder seiner Schwesterart Aalabyss entwickeln.",
      "Regardless, Gorebyss remains a fascinating contrast from a scientific standpoint on the impact of items on evolution.\"" => "Wie dem auch sei: Aus wissenschaftlicher Sicht ist Saganabyss ein faszinierendes Beispiel dafür, welchen Einfluss Items auf die Entwicklung haben.",
    },
    122 => {
      "HP: 326\\nAtk: 306 Def: 207" => "KP: 326\\nAng: 306 Vert: 207",
    },
    123 => {
      "A little bit of spook in the school, huh? $1000 and it's yours." => "Ein bisschen Grusel in der Schule, was? Für 1000 $ gehört sie dir.",
      "Baby-Doll Eyes" => "Kulleraugen",
      "But this book was expensive! I'd like some compensation for my service... $500?" => "Aber das Buch war teuer! Für meine Hilfe hätte ich gern 500 $.",
      "By the way, mate." => "Übrigens, Kumpel:",
      "Cya later." => "Bis dann!",
      "Defense Curl" => "Einigler",
      "Do you want me to teach them to your Pokemon?" => "Soll ich deinem Pokémon diese Attacken beibringen?",
      "Even though I like money, you only gotta pay me once." => "Auch wenn ich Geld liebe: Du musst nur einmal zahlen.",
      "Feint Attack" => "Finte",
      "Fury Cutter" => "Zornklinge",
      "Gladly!" => "Gern!",
      "Here ya go, mate." => "Hier, bitteschön, Kumpel.",
      "Here ya go." => "Bitteschön.",
      "I got them for you, if you got the money." => "Ich hab sie für dich – sofern du das nötige Kleingeld hast.",
      "I was readinig this fascinating book right now. There was a lot of explanations about new moves that were discovered in the Galar region." => "Ich habe gerade dieses faszinierende Buch gelesen. Darin werden viele neue Attacken aus der Galar-Region erklärt.",
      "I'd like to request $500 for this service." => "Für diesen Dienst hätte ich gern 500 $.",
      "Ice 'n' Roll. That'll run you $1000." => "Eis und Action! Kostet dich 1000 $.",
      "Ice Ball" => "Frostbeule",
      "Let them feel your fury. $500 for that." => "Lass sie deinen Zorn spüren! Macht 500 $.",
      "Like a flash - but normal. $500." => "Blitzschnell – aber vom Typ Normal. Kostet 500 $.",
      "No double charge, no worries." => "Du zahlst nicht doppelt, keine Sorge.",
      "No money, no move." => "Kein Geld, keine Attacke.",
      "Not as good as a Sucker Punch, though. $500 for that." => "Nicht so gut wie Tiefschlag, aber kostet nur 500 $.",
      "Oh you don't have much yourself? I'm sorry, I didn't know..." => "Ach, du hast selbst nicht viel? Tut mir leid, das wusste ich nicht …",
      "Oh, h-hello." => "Oh, h-hallo.",
      "Ominous Wind" => "Unheilböen",
      "Paying once, you can go at the move any time." => "Danach kannst du dir die Attacke jederzeit beibringen lassen.",
      "Quick Attack" => "Ruckzuckhieb",
      "Real?" => "Echt?",
      "Rock 'n' Roll. That'll run you $1000." => "Rock ’n’ Roll! Kostet dich 1000 $.",
      "Rollout" => "Walzer",
      "String Shot" => "Fadenschuss",
      "This move increases your own defense!" => "Diese Attacke erhöht deine Verteidigung!",
      "This move reduces the target's Attack! Even with an increased priority!" => "Diese Attacke senkt den Angriff des Ziels – und hat sogar erhöhte Priorität!",
      "This moves reduces the target's speed!" => "Diese Attacke senkt die Initiative des Ziels!",
      "Twist it up, mate. That'll run you $500." => "Dreh richtig auf, Kumpel! Kostet dich 500 $.",
      "Twister" => "Windhose",
      "Wanna get some juicy moves for your mons?" => "Willst du deinen Pokémon ein paar coole Attacken beibringen?",
      "Want to learn some more?" => "Möchtest du noch mehr lernen?",
      "You can 'Bulk Up' your allied Pokemon in a double battle by coaching it!" => "Mit Coaching kannst du dein Partner-Pokémon in einem Doppelkampf stärken!",
      "more" => "Mehr",
    },
    124 => {
      "In fact, it officially learns a striking 18 moves naturally, all of them being at level 1." => "Tatsächlich erlernt es von Natur aus ganze 18 Attacken, und zwar alle auf Level 1.",
      "Regrettably, the natural movepool is not one of Starmie's strengths. Conversly to most stone-evolved Pokémon, its natural moves are widely variable." => "Leider ist Starmies natürliches Attackenrepertoire keine seiner Stärken. Anders als bei den meisten Pokémon, die sich mit einem Stein entwickeln, erlernt es von Natur aus sehr unterschiedliche Attacken.",
      "Scoot." => "Weg da.",
      "These moves include Water Gun, Swift, Rapid Spin, Minimize, Brine, Recover, and many more." => "Dazu gehören Aquaknarre, Sternschauer, Turbodreher, Komprimator, Lake, Genesung und viele mehr.",
      "XXX- HOW MANY POKÉMON CAN LEARN THE ATTACK LAVA PLUME BY LEVEL-UP?" => "XXX- WIE VIELE Pokémon KÖNNEN DEN ANGRIFF Flammensturm NACH LEVEL-UP LERNEN?",
      "XXX- TRUE OR FALSE: FIELD EFFECTS CANNOT BE DESTROYED OR TRANSFORMED BY CERTAIN ATTACKS" => "XXX – WAHR ODER FALSCH: BESTIMMTE ATTACKEN KÖNNEN FELDEFFEKTE WEDER ZERSTÖREN NOCH VERÄNDERN.",
      "XXX- WHAT IS ACCELGOR'S BASE SPEED STAT?" => "XXX – WIE HOCH IST DIE BASIS-INITIATIVE VON SCHALOK?",
      "XXX- WHAT IS GULPIN'S BASE STAT TOTAL?" => "XXX – WIE HOCH IST DIE BASIS-WERTE-SUMME VON SCHLUPPUCK?",
      "XXX- WHAT LEVEL DOES STARMIE LEARN MINIMIZE?" => "XXX – AUF WELCHEM LEVEL ERLERNT STARMIE KOMPRIMATOR?",
      "XXX- WHAT NUMBER IS GOREBYSS IN THE NATIONAL DEX?" => "XXX – WELCHE NUMMER HAT SAGANABYSS IM NATIONALEN POKÉDEX?",
    },
