    293 => {
      "Anyway..." => "Wie auch immer...",
      "At your service." => "Zu Diensten.",
      "I am at your service to tend to your needs." => "Ich stehe dir zu Diensten und kümmere mich gern um deine Wünsche.",
      "Oh dear, another blackout?" => "Oh je, schon wieder ein Stromausfall?",
