    299 => {
      "(Yes, that's possible.)" => "(Ja, das geht wirklich.)",
      "... Wait." => "...Moment.",
      "A token of our friendship!" => "Ein Zeichen unserer Freundschaft!",
      "Actually my favourite!" => "Eigentlich mein Favorit!",
      "Aww, that's a bummer..." => "Och, wie schade...",
      "But I am so lazy..." => "Aber ich bin so faul...",
      "But don't eat the hat." => "Aber iss nicht den Hut.",
      "Can't teach it Body Press though..." => "Body Press kann ich ihm allerdings nicht beibringen...",
      "Choose your style." => "Wähle deinen Stil.",
      "Chu is VERY eager to go on adventures!" => "Chu kann es kaum erwarten, Abenteuer zu erleben!",
      "Come back anytime!" => "Komm jederzeit wieder!",
      "Did you hear that, Chu?" => "Hast du das gehört, Chu?",
      "Don't eat it though." => "Aber iss es nicht.",
      "Fantastic!" => "Fantastisch!",
      "For a measly 2000$ you can make your Pikachu even more fabulous!" => "Für schlappe 2000 $ wird dein Pikachu noch schicker!",
      "Gotta say, the natural look is always a good sight!" => "Der natürliche Look ist einfach immer schön!",
      "Haihai, Sir Elyvilon Nyunyunyu Esq. III. at your service!" => "Haihai, Sir Elyvilon Nyunyunyu, hochwohlgeboren III., zu Diensten!",
      "Hey there! Pika Relearner, at your service!" => "Hallo! Ich bin der Pikachu-Attacken-Erinnerer, zu Diensten!",
      "How about it? Wanna have a go against my Chu's?" => "Na, willst du gegen meine Chus antreten?",
      "How about it? Would you take it with you? Travel the world and that?" => "Na, was meinst du? Nimmst du es mit? Auf Weltreise und so?",
      "I can definitely teach your Pikachu some of their old moves." => "Ich kann deinem Pikachu alte Attacken wieder beibringen.",
      "I had high hopes for our encounter and you nailed it!" => "Ich hatte viel von unserem Treffen erwartet, und du hast es geschafft!",
      "I'd say it suits it all too well!" => "Ich würde sagen, es passt sehr gut!",
      "If you changed your Pikachu's style, I can teach it some of their old moves." => "Wenn du den Stil deines Pikachu geändert hast, kann ich ihm alte Attacken wieder beibringen.",
      "Impressive! That's what i was looking for!" => "Beeindruckend! Genau darauf hatte ich gehofft!",
      "It's been quite a while huh? I heard many heroic stories about you!" => "Lange nicht gesehen, was? Ich habe viele Heldengeschichten über dich gehört!",
      "Just like a japanese idol!" => "Wie ein japanisches Idol!",
      "My little buddy started to get really restless when I told him all about your adventure!" => "Mein kleiner Freund wurde ganz unruhig, als ich ihm von deinen Abenteuern erzählt habe!",
      "NYU: Aww, a bummer." => "NYU: Och, wie schade.",
      "NYU: Hmm, you know?" => "NYU: Hm, weißt du?",
      "NYU: Well then, good luck on your world adventure!" => "NYU: Dann viel Glück auf deiner Weltreise!",
      "Never gonna give you up!" => "Ich lass dich nie im Stich!",
      "Now don't let us down!" => "Enttäusch uns nicht!",
      "Oh, the beauty of old fashion!" => "Ach, die Schönheit des klassischen Stils!",
      "PIKACHU: Chuuuu~" => "Pikachu: Chuuuu~",
      "PKO, out of nowhere!" => "Überraschungs-PKO!",
      "Ph. D." => "Doktor",
      "Pikachu looks at you, full of expectation!" => "Pikachu sieht dich voller Erwartung an!",
      "Pikachu looks impressed by your performance!" => "Pikachu scheint von deiner Leistung beeindruckt!",
      "Pikachu: Pii-Ka!!" => "PIKACHU: Pii-Ka!!",
      "Pikachu: Pii-Ka?" => "PIKACHU: Pii-Ka?",
      "Pop Star" => "Popstar",
      "Right up to the original!" => "Zurück zum Original!",
      "Right! And now I'll give you this!" => "Genau! Und jetzt gebe ich dir das hier!",
      "Rock Star" => "Rockstar",
      "Rock on!" => "Lass es krachen!",
      "Sorry Chu..." => "Tut mir leid, Chu...",
      "Subarashii!" => "Wunderbar!",
      "This is Nyu's Pikachu-Dresser!" => "Das ist Nyus Pikachu-Umkleide!",
      "Ultimate attention, here we go!" => "Volle Aufmerksamkeit, jetzt geht’s los!",
      "Wanna look smart? Get the glasses!" => "Willst du schlau aussehen? Dann nimm die Brille!",
      "Well, I'll be here if you change your mind!" => "Na ja, ich bin hier, falls du es dir anders überlegst!",
      "Which move should I teach?" => "Welche Attacke soll ich lehren?",
      "You know? I'm a little bit of a Trainer myself." => "Weißt du, ich bin selbst auch Trainer.",
      "better not" => "Lieber nicht.",
      "more" => "Mehr",
