      "More like Team Metebore.\\tts[More like Team MetaBore.]" => "Eher wie Team Metebore.\\tts[Eher wie Team Metebore.]",
      "RINGMASTER: I'm afraid not." => "ZIRKUSDIREKTORIN: Ich fürchte, nein.",
      "SAMSON: Sup." => "SAMSON: Na?",
