      "TERRA: With m4h highly adv4nced sup3r 1337 h4ck1ngu sKiLlZ i have discovered something very important!!!\\tts[TERRA: With mah highly advanced super leet hackingu skills i have discovered something very important!!!]" => "TERRA: Mit m4h hochentwickeltem sup3r 1337 h4ck1ngu sKiLlZ habe ich etwas sehr Wichtiges entdeckt!!! \\tts[TERRA: Mit mah hochentwickeltem super leet hackingu sKiLlZ habe ich etwas sehr Wichtiges entdeckt!!! ]",
      "TERRA: Y0 DID I OR DID I NaWT TELL U 2 CALM YO TITS BITCH\\tts[TERRA: YO DID I OR DID I nawt TELL U TO CALM YO TITS BITCH]" => "TERRA: YO HABE ICH ODER HABE ICH DU NACH GESAGT, 2 RUHIGE TITTEN, SCHLAMPE\\tts[TERRA: YO HABE ICH ODER HABE ICH DU NACH GESAGT, 2 RUHIG DEINE TITTEN SCHLAMPE zu BERUHIGEN]",
      "TERRA: aawwwwh yih." => "TERRA: ooooh jaaaa.",
      "TERRA: lmao i never lose, i only titawin\\tts[TERRA: lmao i never lose, i only TitaWin]" => "TERRA: Lmao, ich verliere nie, ich gewinne nur\\tts[TERRA: Lmao, ich verliere nie, ich gewinne nur]",
      "UNDO THE KALAMITY THAT IS YO MAMMARIES!\\tts[UNDO THE CALAMITY THAT IS YO MAMMARIES!]" => "Machen Sie die Katastrophe rückgängig, die Ihre Brustdrüsen verursacht!\\tts[Machen Sie die Katastrophe rückgängig, die Ihre Brustdrüsen verursacht!]",
