      "Greetings! I'm assisting Stephanie in her research." => "Sei gegrüßt! Ich helfe Stephanie bei ihrer Forschung.",
      "I can teach it to you Pokemon for $2000! What do you say?" => "Für 2000 $ bringe ich die Attacke deinem Pokémon bei! Was meinst du?",
