    764 => {
      "A Grookey Egg, fantastic." => "Ein Chimpep-Ei. Fantastisch.",
      "A Scorbunny Egg?" => "Ein Hopplo-Ei?",
      "And be wise to not answer that question." => "Und sei so schlau, darauf nicht zu antworten.",
      "As much as I want it, we already have a Sprigatito Egg." => "So gern ich es auch hätte: Wir haben schon ein Felori-Ei.",
      "Damn it, another Quaxly Egg?" => "Verdammt, noch ein Kwaks-Ei?",
      "Do I look like I like monkeys? Get that Grookey Egg the fuck outta here!" => "Sehe ich so aus, als würde ich Affen mögen? Schaff dieses verdammte Chimpep-Ei hier raus!",
      "Do you hear my enthusiasm? Well, at least that one's done now." => "Hörst du meine Begeisterung? Na ja, wenigstens ist das jetzt erledigt.",
      "Finally, a Sprigatito Egg." => "Endlich ein Felori-Ei.",
      "Fuecoco" => "Krokel",
      "Fuecoco // TURNED IN" => "Krokel // ABGEGEBEN",
      "Get this out of my sight, we still need a bunch of other Eggs." => "Schaff das aus meinen Augen. Uns fehlen noch jede Menge andere Eier.",
      "Get your ass out there and bring a different Egg!" => "Beweg deinen Arsch und bring ein anderes Ei!",
      "Grookey" => "Chimpep",
