      "BUT GO 0n, GO 0N, TH3RE's MORE BATTLES Y3T T0 FIGHT!\\tts[BUT GO on, GO ON, THERE's MORE BATTLES YET TO FIGHT!]" => "ABER GO 0n, GO 0N, ES GIBT MEHR SCHLACHTEN Y3T BIS KÄMPFEN!\\tts[ABER GO 0n, GO 0N, ES GIBT MEHR SCHLACHTEN Y3T BIS KÄMPFEN!]",
      "Because n0t only do you n3v3r say anyth1ng :)\\tts[Because not only do you never say anything :)]" => "Denn nicht nur du sagst nichts :)\\tts[Denn nicht nur du sagst nichts :)]",
      "But y0u won 4nd let me shut h3r up :)\\tts[But you won and let me shut her up :)]" => "Aber du hast den 4. Platz gewonnen, lass mich die Klappe halten :)\\tts[Aber du hast den 4. Platz gewonnen, lass mich die Klappe halten :)]",
