      "EITHER K1SS OR GET ON WITH 1T ALREADY.\\tts[EITHER KISS OR GET ON WITH it ALREADY.]" => "ENTWEDER K1SS ODER BEREITS MIT 1T FORTFAHREN.\\tts[ENTWEDER K1SS ODER BEREITS MIT 1T FORTFAHREN.]",
      "F1GHTS,\\tts[FIGHTS,]" => "KÄMPF3,\\tts[KÄMPFE,]",
      "F1NE.\\tts[FINE.]" => "NA GUT.\\tts[NA GUT.]",
      "H1S ACCENT MAY BE FAKE, BUT HIS STUPID1TY IS NOT--\\tts[HIS ACCENT MAY BE FAKE, BUT HIS STUPIDITY is NOT--]" => "Der H1S-Akzent mag falsch sein, aber seine Dummheit ist es nicht …\\tts[Der H1S-Akzent mag falsch sein, aber seine Dummheit ist es nicht …]",
      "HE FACES 0FF AGA1NST\\tts[HE FACES OFF AGAINST]" => "ER STEHT 0FF GEGENÜBER\\tts[ER STEHT 0FF GEGENÜBER]",
      "I FELL 4SLEEP 14 TIMES JUST IN TH0SE THREE LINES AL0NE.\\tts[I FELL ASLEEP 14 TIMES JUST IN THOSE THREE LINES ALONE.]" => "Ich bin allein in diesen drei Zeilen 14 Mal eingeschlafen.\\tts[Ich bin allein in diesen drei Zeilen 14 Mal eingeschlafen.]",
      "I'M W4TCHIN' YA.\\tts[I'M WATCHIN' YA.]" => "Ich bin W4TCHIN' YA.\\tts[Ich bin W4TCHIN' YA.]",
      "IN THE F1RST BRACK3T,\\tts[IN THE FIRST BRACKET,]" => "IN DER ERSTEN KLASSE3T,\\tts[IN DER ERSTEN KLASSE3T,]",
