      "N0W HOLD ON JUST SEXOND!!!\\tts[NOW HOLD ON JUST SEXOND!!!]" => "JETZT WARTEN SIE NUR SEXOND!!!\\tts[JETZT WARTEN SIE NUR SEXOND!!!]",
