      "T3RR4: 0KAY NOW GIT 2 IT.\\tts[TERRA: OKAY NOW GIT to it.]" => "T3RR4: 0KAY JETZT GIT 2 IT.\\tts[T3RR4: 0KAY JETZT GIT 2 IT.]",
