      "T3RR4: AAAAND THAT'S A RAP!\\tts[TERRA: AAAAND THAT'S A RAP!]" => "T3RR4: AAAUND DAS IST EIN RAP!\\tts[T3RR4: AAAUND DAS IST EIN RAP!]",
