      "T3RR4: THE FLAMING FIST OF CHILD ABUSE,\\tts[TERRA: THE FLAMING FIST OF CHILD ABUSE,]" => "T3RR4: Die brennende Faust des Kindesmissbrauchs,\\tts[T3RR4: Die brennende Faust des Kindesmissbrauchs,]",
      "T3RR4: YEA BUT THEY ST1LL D0N'T SAY SHIT TH0.\\tts[TERRA: YEA BUT THEY STILL DON'T SAY SHIT THO.]" => "T3RR4: Ja, aber sie sagen immer noch nichts.\\tts[T3RR4: Ja, aber sie sagen immer noch nichts.]",
      "T3RR4: dayummm gurl you c0ckier than a r00ster in h3at.\\tts[TERRA: dayummm gurl you cockier than a rooster in heat.]" => "T3RR4: dayummm gurl du bist frech als ein R00ster in h3at.\\tts[T3RR4: dayummm gurl du bist frech als ein R00ster in h3at.]",
      "T3RR4: l4dy playin' me like a chess p1ece ;~;\\tts[TERRA: lady playin' me like a chess piece ;~;]" => "T3RR4: Ich spiel' mich wie eine Schachfigur ;~;\\tts[T3RR4: Ich spiel' mich wie eine Schachfigur ;~;]",
