      "THIS P0NY IS SO ONE TR1CK YOU COULD CALL HIM B1G MAC,\\tts[THIS PONY IS SO ONE TRICK YOU COULD CALL HIM BIG MAC,]" => "DIESER P0NY IST SO EIN TR1CK, DEN MAN IHN B1G MAC NENNEN KÖNNTE,\\tts[DIESER P0NY IST SO EIN TR1CK, DEN MAN IHN B1G MAC NENNEN KÖNNTE,]",
      "TIRED FROM A LONG and HARD ;) DAY OF WORK BUSTING A NUT UP 0N TEAM MEATIER,\\tts[TIRED FROM A LONG and HARD ;) DAY OF WORK BUSTING A NUT UP ON TEAM MEATIER,]" => "MÜDE VON EINEM LANGEN und HARTEN ;) ARBEITSTAG, DER DEM TEAM FLEISCHER,\\tts[MÜDE VON EINEM LANGEN und HARTEN ;) ARBEITSTAG, DER DEM TEAM FLEISCHER,]",
      "V3RY WELL, 1F Y0U INS1ST, TH3N 1'LL USE MY SP3C1AL M0VE!!!\\tts[VERY WELL, IF YOU INSIST, THEN I'LL USE MY SPECIAL MOVE!!!]" => "V3RY Naja, 1F Y0U INS1ST, TH3N 1'LL VERWENDEN MEINEN SP3C1AL M0VE!!!\\tts[V3RY Naja, 1F Y0U INS1ST, TH3N 1'LL VERWENDEN MEINEN SP3C1AL M0VE!!!]",
      "WE'd LIKE T0 REMIND TONIGHT's AUD1ENCE THAT THIS TOURNAMENT IS BR0UGHT TO YOU BY DEV0N CORPORATION AND THE LETTER 3.\\tts[WE'd LIKE To REMIND TONIGHT's AUDIENCE THAT THIS TOURNAMENT IS BROUGHT TO YOU BY DEVON CORPORATION AND THE LETTER 3.]" => "Wir möchten die Zuschauer von heute Abend daran erinnern, dass Ihnen dieses Turnier von der DEV0N CORPORATION und dem Buchstaben 3 angeboten wird.\\tts[Wir möchten die Zuschauer von heute Abend daran erinnern, dass Ihnen dieses Turnier von der DEV0N CORPORATION und dem Buchstaben 3 angeboten wird.]",
      "WEWCOME TO THE THIWD W0UND AND SEMIFINAWS OF THE WABWADOWWA GWAND T0UWNAMENT OF dat ass.\\tts[WEWCOME TO THE THIWD WOUND AND SEMIFINAWS OF THE WABWADOWWA GWAND TOUWNAMENT OF dat ass.]" => "WILLKOMMEN ZU DEN THIWD W0UND UND SEMIFINAWS DES WABWADOWWA GWAND T0UWNAMENT OF dat ass.\\tts[WILLKOMMEN ZU DEN THIWD W0UND UND SEMIFINAWS DES WABWADOWWA GWAND T0UWNAMENT OF dat ass.]",
      "WH4TEVER, F1GHT!!!!\\tts[WHATEVER, FIGHT!!!!]" => "Wie auch immer, F1GHT!!!!\\tts[Wie auch immer, F1GHT!!!!]",
