      "Y0U 4re my f4vor1te pers0n right n0w. :)\\tts[YOU are my favorite person right now. :)]" => "Du bist jetzt meine Lieblingsperson. :) :)\\tts[Du bist jetzt meine Lieblingsperson. :) :)]",
      "Y3S, TH3RE'S A W4Y TO S4VE Y0UR PREC1OUS L1TTLE L0SERS.\\tts[YES, THERE'S A WAY TO SAVE YOUR PRECIOUS LITTLE LOSERS.]" => "Y3S, ES GIBT EINE W4Y, IHRE KOSTBAREN KLEINEN VERLIERER ZU S4VE.\\tts[Y3S, ES GIBT EINE W4Y, IHRE KOSTBAREN KLEINEN VERLIERER ZU S4VE.]",
      "YOUUU JUST DO THE S1NGING, I'LL T4KE CARE 0F THE HARD PART.\\tts[YOUUU JUST DO THE SINGING, I'LL TAKE CARE OF THE HARD PART.]" => "Übernimm einfach das Singen, ich kümmere mich um den schwierigen Teil.\\tts[Übernimm einfach das Singen, ich kümmere mich um den schwierigen Teil.]",
