      "aite, p1cture this...\\tts[aite, picture this...]" => "Aite, stell dir das vor...\\tts[Aite, stell dir das vor...]",
      "an' just wh44444t u think's gonna happen to your s1ster if y0u do that?\\tts[an' just whaaaaat u think's gonna happen to your sister if you do that?]" => "Und was glaubst du, was deiner Schwester passieren wird, wenn du das tust?\\tts[Und was glaubst du, was deiner Schwester passieren wird, wenn du das tust?]",
      "and Ch1cken Invad3rs 4: cluck 0f the dark s1de.\\tts[and Chicken Invaders 4: cluck of the dark side.]" => "und Ch1cken Invad3rs 4: cluck 0f the Unlicht s1de.\\tts[und Ch1cken Invad3rs 4: cluck 0f the Unlicht s1de.]",
      "but whaddya w4nt from me, eff0rt?\\tts[but whaddya want from me, effort?]" => "Aber was wolltest du nicht von mir, Anstrengung?\\tts[Aber was wolltest du nicht von mir, Anstrengung?]",
      "ca5hmoney, that gucci p00n,\\tts[CashMoney, that gucci poon,]" => "ca5hmoney, dieser Gucci p00n,\\tts[ca5hmoney, dieser Gucci p00n,]",
      "cuz i said s0.\\tts[cuz i said so.]" => "Weil ich s0 gesagt habe.\\tts[Weil ich s0 gesagt habe.]",
      "don't talk back to me b1111tch, i r4ised u better than that.\\tts[don't talk back to me biiiitch, i raised u better than that.]" => "Sprich nicht mit mir zurück, b1111tch, ich habe dich besser bewertet.\\tts[Sprich nicht mit mir zurück, b1111tch, ich habe dich besser bewertet.]",
      "l4dy stop.\\tts[lady stop.]" => "l4dy hör auf.\\tts[l4dy hör auf.]",
      "m44444y be nothing can happen to them anym0re, but that doesn't mean n0thing can be done about it.\\tts[maaaaay be nothing can happen to them anymore, but that doesn't mean nothing can be done about it.]" => "Es kann sein, dass ihnen nichts mehr passieren kann, aber das heißt nicht, dass man nichts dagegen tun kann.\\tts[Es kann sein, dass ihnen nichts mehr passieren kann, aber das heißt nicht, dass man nichts dagegen tun kann.]",
      "na0 go take a time 0ut.\\tts[nao go take a time out.]" => "Na0 geh, nimm dir eine Zeit 0ut.\\tts[Na0 geh, nimm dir eine Zeit 0ut.]",
      "nunadat.\\tts[NunnaDat.]" => "nixda.\\tts[Nix da.]",
