      "th4t's the way y0u like it, uh huh, uh huh.\\tts[that's the way you like it, uh huh, uh huh.]" => "So gefällt es dir, äh, äh.\\tts[So gefällt es dir, äh, äh.]",
      "there's 4444lways m0re battles left to f1ght.\\tts[there's aaaalways more battles left to fight.]" => "Es gibt immer noch mehr Schlachten zu schlagen.\\tts[Es gibt immer noch mehr Schlachten zu schlagen.]",
