      "N0W TH4T I KN0W THAT PR0GRAM EX1STS, I CAN JUST FIND IT MYSELF.\\tts[NOW THAT I KNOW THAT PROGRAM EXISTS, I CAN JUST FIND it MYSELF.]" => "NACHDEM ICH WEISS, DASS DAS PROGRAMM EXISTIERT, KANN ICH ES EINFACH SELBST FINDEN. \\tts[JETZT, DA ICH WEISS, DASS DAS PROGRAMM EXISTIERT, KANN ICH ES EINFACH SELBST FINDEN. ]",
      "OI, B0RING 4SS B1TCH,\\tts[Oi, BORING ASS BITCH,]" => "OI, DU L4NGWE1L1GE SCHLAMPE,\\tts[Oi, du langweilige Schlampe,]",
      "Oh! That is the TREASSUREBADGE!\\tts[Oh! That is the TREASURE BADGE!]" => "Oh! Das ist das SCHATZABZEICHEN!\\tts[Oh! Das ist das SCHATZABZEICHEN!]",
