      "T3RR4: I W1LL N0T.\\tts[TERRA: I WILL NOT.]" => "T3RR4: ICH WILL NICHT. \\tts[TERRA: ICH WILL NICHT. ]",
      "T3RR4: IT W0ULD APP3AR Y0UR <b>MOM</b> WAS UNCOMPREHENS1VE.\\tts[TERRA: It WOULD APPEAR YOUR MOM WAS UNCOMPREHENSIVE.]" => "T3RR4: Es schien, als ob deine Mutter nichts verstanden hätte. \\tts[TERRA: es schien, als ob deine Mutter nichts verstanden hätte. ]",
      "T3RR4: KN0W1NG Y0U I BET Y0U PUT IT IN THE MOST BORING PLACE P0SSIBLE.\\tts[TERRA: KNOWING YOU I BET YOU PUT it IN THE MOST BORING PLACE POSSIBLE.]" => "T3RR4: KN0W1NG Y0U, ich wette, du hast es an der langweiligsten Stelle platziert, die es gibt. \\tts[TERRA: Ich kenne dich, ich wette, du hast es an der langweiligsten Stelle, die möglich ist, platziert. ]",
      "T3RR4: OK, SO Y0U F1GURED 0UT THE G1MMICK, BUT H0W D0ES THAT LET Y0U GET AR0UND 1T, HUH, PUNK?!!!\\tts[TERRA: OK, SO YOU FIGURED OUT THE GIMMICK, BUT HOW DOES THAT LET YOU GET AROUND it, HUH, PUNK?!!!]" => "T3RR4: OK, Ihr habt also den G1MMICK ausgenutzt, aber wie kommt Ihr damit um die Ecke, HUH, PUNK?!!!\\tts[T3RR4: OK, Ihr habt also den G1MMICK ausgenutzt, aber wie kommt Ihr damit um die Ecke, HUH, PUNK?!!!]",
      "T3RR4: OSH1T, I'M A R34L G1RL N0W.\\tts[TERRA: OShit, I'M A REAL GIRL NOW.]" => "T3RR4: OSH1T, ich bin ein R34L G1RL N0W. \\tts[TERRA: OSHIT, ich bin JETZT EIN ECHTES MÄDCHEN. ]",
      "T3RR4: \\nS0N0F4M0TH3RFUCK1NGB1D00F'SBUTTH0LE.\\tts[TERRA: SonOfAMotherFuckingBidoof'sButthole.]" => "T3RR4: \\nS0N0F4M0TH3RFUCK1NGB1D00F'SBUTTH0LE. \\tts[TERRA: \\nSONOFAMOTHERFUCKINGBIDOOF'SBUTTHOLE. ]",
