      "WELP, t1ME f0R A CLASS1C NONSEQU1TOR BATTLE TR4NSIT1ON.\\tts[WELP, TIME FOR A CLASSIC NONSEQUITOR BATTLE TRANSITION.]" => "WELP, ZEIT FÜR EINEN NONSEQUITOR-KAMPFÜBERGANG DER KLASSE 1C. \\tts[WELP, Zeit für EINEN KLASSISCHEN NONSEQUITOR-KAMPFÜBERGANG. ]",
      "You can pass here only if you have the TREASSUREBADGE.\\tts[You can pass here only if you have the TREASURE BADGE.]" => "Sie können hier nur bestehen, wenn Sie das SCHATZABZEICHEN haben.\\tts[Sie können hier nur bestehen, wenn Sie das SCHATZABZEICHEN haben.]",
