      "ANyw4Y she trieD TO HACK THIS PLACe AND T0TALLY BOMBED IT\\tts[Anyway she tried TO HACK THIS PLACE AND TOTALLY BOMBED it]" => "Jedenfalls hat sie versucht, diesen Ort zu hacken und ihn völlig bombardiert\\tts[jedenfalls hat sie versucht, diesen Ort zu hacken und ihn völlig bombardiert]",
      "C, the reason L1ttle M1ss R0bl0x couldn't hakk it, izzat alladis?\\tts[C, the reason Little Miss Roblox couldn't hakk it, iz zat all adis?]" => "C, der Grund, warum L1ttle M1ss R0bl0x es nicht hakken konnte, izzat alladis? \\tts[C, der Grund, warum Little Miss Roblox es nicht hakken konnte, izzat alladis? ]",
      "DUH." => "NA KLAR.",
