      "TH4T's EN0ugh 0UT OF Y0U BUSTER\\tts[THAT'S ENOUGH OUT OF YOU BUSTER]" => "TH4T ist GENUG VON DIR, BUSTER\\tts[DAS IST GENUG VON DIR, BUSTER]",
      "THIS TRAIN HAS ONLY 0NE STOP, AND IT'S AT REGRETVILLE STATI0N\\tts[THIS TRAIN HAS ONLY ONE STOP, AND it's AT REGRETVILLE STATION]" => "DIESER ZUG HAT NUR EINE HALTESTELLE UND BEFINDET SICH AM BAHNHOF REGRETVILLE.\\tts[DIESER ZUG HAT NUR EINE HALTESTELLE UND BEFINDET SICH AM BAHNHOF REGRETVILLE.]",
      "WA1T\\tts[WAIT]" => "W4RT3N\\tts[WARTEN]",
      "and ynowhatimsayin'.\\tts[and YnoWhatImSayin'.]" => "und ynowhatimsayin'.\\tts[und ynowhatimsayin'.]",
