    906 => {
      "\"This Meltan is kept for scientific purposes.\"" => "„Dieses Meltan wird zu Forschungszwecken aufbewahrt.“",
      "*Open gate*" => "*Tor öffnen*",
      "Caution is advised." => "Vorsicht ist geboten.",
      "Cell terminal online." => "Zellenterminal aktiviert.",
      "Gate terminal online." => "Torterminal aktiviert.",
      "Melmetal has been defeated!" => "Melmetal wurde besiegt!",
      "Open cells?" => "Zellen öffnen?",
      "Proceed?" => "Fortfahren?",
