    },
    907 => {
      "...Yoink." => "...Mitnehmen.",
      "...Yoink?" => "...Mitnehmen?",
      "Better not." => "Lieber nicht.",
      "Do you want to take it with you?" => "Möchten Sie es mitnehmen?",
      "EEP!!" => "Iih!!",
      "Fezandipiti looks completely petrified." => "Fezandipiti ist völlig versteinert.",
      "Hnng?!" => "Hng?!",
      "Munkidori seems unconsious." => "Munkidori scheint bewusstlos zu sein.",
      "Ogerpon must have run back to the Mask maker..." => "Ogerpon muss zum Maskenmacher zurückgelaufen sein...",
      "Pecharunt gave Ogerpon the stolen masks!" => "Pecharunt gab Ogerpon die gestohlenen Masken zurück!",
      "Pecharunt threw a toxic mochi at Ogerpon!" => "Pecharunt warf ein giftiges Mochi nach Ogerpon!",
      "Pecharunt was utterly defeated." => "Pecharunt wurde vernichtend geschlagen.",
    },
    908 => {
      "... and they got them." => "...und sie haben sie bekommen.",
      "...hmmm, \\PN? Yes, yes I've heard of your achievements around this area." => "...hmm, \\PN? Ja, ja, von deinen Erfolgen hier habe ich gehört.",
      "...no matter." => "...wie dem auch sei.",
      "...oh goodness." => "...ach du meine Güte.",
      "...the same that seem to have been responsible for her Trainer's fatality." => "...dieselben, die wohl für den Tod des Trainers verantwortlich waren.",
      "1 Premier Ball." => "1 Premierball.",
      "5 Star Pieces." => "5 Sternenstücke.",
      "5 Stardust." => "5 Sternenstäube.",
      "5 bags of Stardust, perfect." => "5 Beutel Sternenstaub, perfekt.",
      "???: Phew..." => "???: Puh...",
      "???: Relax Ogerpon, I am alright... they surprisingly let me unharmed." => "???: Keine Sorge, Ogerpon, mir geht es gut... Sie haben mir überraschenderweise nichts getan.",
      "???: You are alright, good. I wasn't expecting them to follow us even up here." => "???: Du bist wohlauf, gut. Ich hätte nicht gedacht, dass sie uns bis hierher folgen würden.",
      "Alas, these thiefs followed us even to our secluded cave, here in Reborn..." => "Leider folgten uns diese Diebe sogar bis in unsere abgelegene Höhle hier in Reborn...",
      "Alright." => "Gut.",
      "An expedition team called \"Area Zero Survey\", investigated an area in the center of Paldea with the same name." => "Ein Expeditionsteam namens „Area-Zero-Erkundung“ untersuchte das Gebiet Area Zero im Zentrum von Paldea.",
      "And 1 Comet Shard." => "Und 1 Kometstück.",
      "Anyways, the work on the mask is still ongoing. You will have to wait a bit longer." => "Die Maske ist noch in Arbeit. Du musst dich noch etwas gedulden.",
      "Considering their current state the battle must have been very fierce." => "Bei ihrem Zustand muss der Kampf sehr heftig gewesen sein.",
      "Even Ogerpon was at some point affected by such crystallization phenomenon, although it only affected the masks, strangely enough." => "Auch Ogerpon war einst von diesem Kristallisationsphänomen betroffen. Seltsamerweise betraf es aber nur seine Masken.",
      "Finished! Thank you for your patience." => "Fertig! Danke für deine Geduld.",
      "First of all, let me remove these question marks. Call me Goro." => "Zuerst nehme ich dir diese Fragezeichen ab. Nenn mich Goro.",
      "For now, let me put it here - meanwhile I'll tell you the history behind it." => "Ich lege es erst einmal hierhin und erzähle dir inzwischen seine Geschichte.",
      "GORO: Alright." => "GORO: Gut.",
      "GORO: Always such a troublemaker..." => "GORO: Immer dieser Unruhestifter...",
      "GORO: Hello \\PN! Good for you to pay me a visit." => "GORO: Hallo, \\PN! Schön, dass du mich besuchst.",
      "GORO: Hello \\PN. Nice of you to pay me a visit." => "GORO: Hallo, \\PN. Schön, dass du mich besuchst.",
      "GORO: Hrm, you don't have them? Maybe you missed them during your encounter against the thieves?" => "GORO: Hm, du hast sie nicht dabei? Vielleicht hast du sie beim Kampf gegen die Diebe übersehen?",
      "GORO: I am a mask maker from a far away land named Kitakami." => "GORO: Ich bin Maskenmacher aus einem weit entfernten Land namens Kitakami.",
      "GORO: If you miss any of them, try and look around at the meteor crashing site." => "GORO: Falls dir etwas fehlt, such bei der Absturzstelle des Meteoriten.",
      "GORO: In my home land of Kitakami, Ogerpon has been, and still is, a very cheery, welcomed Pokemon - and friend - among our people." => "GORO: In meiner Heimat Kitakami war und ist Ogerpon bei unserem Volk ein fröhliches und gern gesehenes Pokémon – und ein Freund.",
      "GORO: Knowing their leader they probably settled in a deserted area, ideally a wasteland." => "GORO: Ihr Anführer hat sich sicher in einer verlassenen Einöde niedergelassen.",
      "GORO: Meanwhile..." => "GORO: In der Zwischenzeit...",
      "GORO: Oh, and don't forget Ogerpon's favourite mask! It's the only one that's not damaged." => "GORO: Und vergiss Ogerpons Lieblingsmaske nicht! Nur sie ist unbeschädigt.",
      "GORO: Ohh, \\PN! You are back." => "GORO: Oh, \\PN! Du bist zurück.",
      "GORO: There you are \\PN!" => "GORO: Da bist du ja, \\PN!",
      "GORO: Try and interact with Terapagos, I assure there will be a reaction." => "GORO: Sprich Terapagos an. Ich bin sicher, es wird reagieren.",
      "GORO: Well well, now you already got two partners out of this home!" => "GORO: Na, na! Jetzt hast du schon zwei Begleiter aus diesem Haus mitgenommen!",
      "GORO: Wonderful, it worked!" => "GORO: Wunderbar, es hat funktioniert!",
      "Go on little one, a new adventure awaits!" => "Na los, Kleines. Ein neues Abenteuer wartet auf dich!",
      "Have you heard of terastalization?" => "Hast du schon einmal von der Terakristallisierung gehört?",
      "Here are the materials I will need:" => "Diese Materialien brauche ich:",
      "Here you go. Try and show it to Terapagos." => "Bitte sehr. Zeig es einmal Terapagos.",
      "However, this brew even more rumours about these two." => "Das brachte nur noch mehr Gerüchte über die beiden hervor.",
      "Hrm!" => "Hm!",
      "I accompanied her, and now we are here." => "Ich begleitete es, und nun sind wir hier.",
      "I am in no position to ask you of such... but would you help Ogerpon retrieving our precious masks?" => "Es steht mir nicht zu, dich um so etwas zu bitten ... aber hilfst du Ogerpon, unsere kostbaren Masken zurückzuholen?",
      "I found her near my reclusive lodge inside a cave." => "Ich fand Ogerpon nahe meiner abgelegenen Hütte in einer Höhle.",
      "I heard you retrieved the Pokémon from the crashing site, yes?" => "Du hast das Pokémon von der Absturzstelle geholt, ja?",
      "I hope Ogerpon is doing well?" => "Ich hoffe, es geht Ogerpon gut?",
      "I hope those masks will serve you both well." => "Ich hoffe, die Masken werden euch beiden gute Dienste leisten.",
      "I hope you will treat it, and Ogerpon of course, with affection and warmth." => "Ich hoffe, du behandelst es und natürlich auch Ogerpon liebevoll und herzlich.",
      "I recall an area that has been locked down for years?" => "Ich erinnere mich an einen Ort, der seit Jahren abgeriegelt ist.",
      "I still got it in those old bones!" => "In den alten Knochen steckt noch Kraft!",
      "I suggest you make haste, \\PN." => "Am besten beeilst du dich, \\PN.",
      "I wasn't aware of many rumours but was certain there wasn't any truth behind them." => "Ich kannte zwar nur wenige Gerüchte, war mir aber sicher, dass nichts davon stimmte.",
      "I will be needing quite unique materials on that matter." => "Dafür brauche ich einige ganz besondere Materialien.",
      "I will work on the last one right away." => "Ich repariere gleich die letzte.",
      "I will work on the next one right away." => "Ich kümmere mich gleich um die nächste.",
      "I wish you luck and await your next visit, \\PN!" => "Viel Glück! Ich freue mich auf deinen nächsten Besuch, \\PN!",
      "If I am able to reproduce such orb, maybe we can help Terapagos wake up of its unconsciousness." => "Wenn ich so eine Kugel nachbauen kann, können wir Terapagos vielleicht aus seiner Bewusstlosigkeit wecken.",
      "If you miss any of them, try and look around at the meteor crashing site." => "Falls dir etwas fehlt, such bei der Absturzstelle des Meteoriten.",
      "In a furious rage, Ogerpon started a heated battle against them." => "Ogerpon kämpfte wutentbrannt gegen sie.",
      "Incredible! You got the Comet Shard." => "Unglaublich! Du hast das Kometstück.",
      "It is very likely you will find clues of their whereabouts there." => "Dort findest du wahrscheinlich Hinweise darauf, wo sie sich aufhalten.",
      "It seems pretty healthy even though it crashed into Iolia Valley like a meteor." => "Es scheint gesund zu sein, obwohl es wie ein Meteorit ins Iolia-Tal gestürzt ist.",
      "It was he who most likely first encountered Terapagos, at least he called a strange entity of that name." => "Wahrscheinlich begegnete er dort als Erster Terapagos. Jedenfalls gab er einem seltsamen Wesen diesen Namen.",
      "It will definitely help clearing your mind off of everything that's been happening over the last weeks." => "Das hilft dir bestimmt, den Kopf von allem freizubekommen, was in den letzten Wochen passiert ist.",
      "It will take some time for me to prepare the repair work with my small tool collection I currently possess..." => "Mit meiner kleinen Werkzeugsammlung brauche ich eine Weile, um sie zu reparieren...",
      "It's a phenomenon that has been first discovered in my home Region, Paldea, far far away from here." => "Dieses Phänomen wurde zuerst in meiner weit entfernten Heimat Paldea entdeckt.",
      "Knowing their leader, they will prefer areas that are rarely populated, ideally total wastelands even." => "Ihr Anführer wird sich wohl an Orten aufhalten, an denen kaum jemand lebt, am besten in einer völlig verlassenen Einöde.",
      "Let me quickly gather all of them, speak to me in a moment..." => "Ich suche sie schnell zusammen. Sprich gleich noch einmal mit mir...",
      "Many rumours emerged, thus Ogerpon tried to avoid crowded places." => "Es kamen viele Gerüchte auf, deshalb mied Ogerpon belebte Orte.",
      "Maybe a bit of storytelling might be appropriate now." => "Jetzt wäre wohl eine kleine Geschichte angebracht.",
      "Maybe talk with the residents there. They might help you in your search." => "Vielleicht kannst du mit den Bewohnern dort sprechen. Sie helfen dir womöglich bei der Suche.",
      "Now the crucial information we need to help this little one: In one of Heath's books he mentioned a specific orb that could hold crystallized energy." => "Für unsere Hilfe brauchen wir nun eine entscheidende Information: In einem seiner Bücher erwähnte Heath eine besondere Kugel, die kristallisierte Energie speichern kann.",
      "Now, do you have them with you?" => "Hast du sie jetzt dabei?",
      "Ogerpon tried to explain me your whole encounter with the Loyal Three and their leader." => "Ogerpon hat mir von deiner Begegnung mit den drei Gefürchteten und ihrem Anführer erzählt.",
      "Ogerpon, how about you accompany \\PN until then?" => "Ogerpon, möchtest du bis dahin \\PN begleiten?",
      "Oh, you got the Ball? Very good." => "Oh, du hast den Ball? Sehr gut.",
      "Relax, relax. It's gonna be alright." => "Ruhig, ruhig. Alles wird gut.",
      "Rumours began to manifest, and Ogerpon eventually had to leave the land." => "wurden die Gerüchte wahr, und Ogerpon musste das Land schließlich verlassen.",
      "She arrived there with her precious Trainer, which is... sadly not among us anymore." => "Es kam mit seinem geliebten Trainer zu uns, der leider nicht mehr unter uns weilt.",
      "So, I began working on exclusive masks that may help Ogerpon walk among our people again." => "Also begann ich, besondere Masken anzufertigen, damit Ogerpon wieder unter unserem Volk leben konnte.",
      "Such an outstanding Trainer you are!" => "Was für ein herausragender Trainer du bist!",
      "Surprisingly enough it worked brilliantly, if not for long though..." => "Es funktionierte überraschend gut, wenn auch nicht lange...",
      "Terapagos still seems unconscious." => "Terapagos scheint noch immer bewusstlos zu sein.",
      "Thank you for helping us against these mask-thieves!" => "Danke, dass du uns gegen diese Maskendiebe geholfen hast!",
      "That will be all." => "Das wäre alles.",
      "The historian Heath was one of its members, and was able to record considerable amounts of data within Area Zero." => "Der Historiker Heath gehörte zum Team und konnte in Area Zero zahlreiche Daten sammeln.",
      "The rest you know already..." => "Den Rest kennst du ja bereits...",
      "These Pokemon are not easy to be dealt with... and they got a leader that literally pulls their strings." => "Mit diesen Pokémon ist nicht leicht fertigzuwerden ... und sie haben einen Anführer, der sie buchstäblich an den Fäden zieht.",
      "These are all of the materials." => "Das sind alle Materialien.",
      "They got all masks - except for this one." => "Sie haben alle Masken bis auf diese hier.",
      "They were the reason we fled from our home village and decided to live a deserted life up here." => "Wegen ihnen flohen wir aus unserem Heimatdorf und beschlossen, hier oben zurückgezogen zu leben.",
      "This crystallization was affecting certain Pokémon that gave them a gem-like appearance, and even altering its type." => "Dabei kristallisieren manche Pokémon, erhalten ein edelsteinartiges Aussehen und können sogar ihren Typ ändern.",
      "Three malicious thiefs caught eye on our masks." => "Drei böswillige Diebe bekamen es auf unsere Masken abgesehen.",
      "Unfortunately during a festival with many many people..." => "Doch bei einem Fest mit sehr vielen Menschen...",
      "Usually I'd love to chew off your ear about our past, but I figure there is no time for that." => "Normalerweise würde ich dir liebend gern die Ohren über unsere Vergangenheit abkauen, aber dafür ist wohl keine Zeit.",
      "We would be incredibly thankful if you could help us!" => "Wir wären dir unendlich dankbar, wenn du uns helfen könntest!",
      "You already got the Star Pieces! Good." => "Du hast die Sternenstücke schon! Sehr gut.",
      "You came at the right time! I finished repairing one of the masks!" => "Du kommst genau richtig! Ich habe eine der Masken fertig repariert!",
      "You came at the right time! I finished repairing the last mask!" => "Du kommst genau richtig! Auch die letzte Maske ist fertig repariert!",
      "You can use it right away. Ogerpon will be delighted." => "Du kannst sie gleich benutzen. Ogerpon wird sich freuen.",
      "You can visit me and check for my progress anytime." => "Du kannst jederzeit vorbeikommen und nach dem Fortschritt fragen.",
      "You point the orb towards Terapagos." => "Du hältst die Kugel auf Terapagos.",
      "You there, young one." => "Du da, junger Mensch.",
      "You've seen these Pokemon that invaded our small home? They were targeting Ogerpon's treasured masks." => "Du hast die Pokémon gesehen, die in unser kleines Zuhause eingedrungen sind? Sie hatten es auf Ogerpons wertvolle Masken abgesehen.",
      "Young one. I assume you are a Trainer?" => "Junger Mensch, du bist doch Trainer, oder?",
      "\\PN hands over the damaged masks." => "\\PN gibt die beschädigten Masken ab.",
    },
    909 => {
      "All Paradox Pokémon were defeated!" => "Alle Paradox-Pokémon wurden besiegt!",
      "Claim victory over Koraidon and Miraidon?" => "Den Sieg über Koraidon und Miraidon beanspruchen?",
      "IRONVALIANT: ...R-riuuuu!" => "EISENKRIEGER: ...R-riuuuu!",
      "KORAIDON & MIRAIDON: doooon..." => "KORAIDON UND MIRAIDON: doooon...",
      "Koraidon and Miraidon look devastated." => "Koraidon und Miraidon wirken am Boden zerstört.",
      "ROARINGMOON: ...Roooooa!" => "BRÜLLENDER MOND: ...Roooooa!",
      "The head leaders attack!" => "Die Anführer greifen an!",
    },
    910 => {
      "Roaring Moon fled?!" => "Brüllender Mond ist geflohen?!",
      "The Salamence attacks!" => "Das Brutalanda greift an!",
      "This is a... Salamence?" => "Das ist ein ... Brutalanda?",
    },
    911 => {
      "Iron Valiant disappeared!" => "Eisenkrieger ist verschwunden!",
      "Is this... a Gallade?" => "Ist das ... ein Galagladi?",
      "The Pokemon attacks!" => "Das Pokémon greift an!",
    },
    912 => {
      "\"--I plead for retaliation against those who accompany the evil deed--\"" => "„–Ich flehe um Vergeltung an denen, die an diesem bösen Werk beteiligt sind–“",
      "\"--My existence is fading--\"" => "„–Meine Existenz schwindet–“",
      "\"--Recklessly sacrificing anything to achieve their selfish goals--\"" => "„–Rücksichtslos alles opfernd, um die eigenen Ziele zu erreichen–“",
      "\"--Without any concerns of what might happen to others--\"" => "„–Ohne Rücksicht darauf, was anderen zustoßen könnte–“",
      "\"Trainer...\"" => "„Trainer...“",
      "GARDEVOIR: Yuuhhh..." => "GUARDEVOIR: Yuuhhh...",
    },
    913 => {
      "...Was that convincing?" => "... War das überzeugend?",
      "...but nothing happened." => "... Aber nichts ist passiert.",
      "A gang leader in the city of some sort should suffice." => "Eine Art Leader-Gang in der Stadt sollte ausreichen.",
      "After all, a normal Hypnosis only lasts so many turns, no?" => "Schließlich dauert eine Normal-Hypnose nur so viele Runden, oder?",
      "All you need to do is read between the lines--" => "Alles, was Sie tun müssen, ist zwischen den Zeilen zu lesen:",
      "And sometimes up may be the only way down." => "Und manchmal ist oben der einzige Weg nach unten.",
      "Are you still in possession of the Crystal Keys?" => "Hast du die Kristallschlüssel noch bei dir?",
      "As we said before, not all is black and white, or dark and light." => "Wie wir bereits sagten, ist nicht alles Schwarz und Weiß oder Unlicht und Licht.",
      "As you must have heard, they have captured Luna." => "Wie Sie sicher gehört haben, haben sie Luna gefangen genommen.",
      "Choose the right hat for the right job?" => "Den richtigen Hut für den richtigen Job wählen?",
      "Come, \\PN. Let us proceed." => "Komm, \\PN. Gehen wir weiter.",
      "Didn't I say before--" => "Habe ich nicht schon einmal gesagt...",
      "Do you know anyone like that?" => "Kennst du so jemanden?",
      "For reasons of my own, I must make myself scarce at present." => "Aus meinen eigenen Gründen muss ich mich derzeit rar machen.",
      "Hold it right there!" => "Halten Sie es genau dort!",
      "I am in doubt the meteor impact created this." => "Ich bezweifle, dass der Meteoriteneinschlag diese Höhle erschaffen hat.",
      "I ask you go in my stead." => "Ich bitte Sie, an meiner Stelle zu gehen.",
      "I find these crystals surprisingly familiar..." => "Diese Kristalle kommen mir seltsam vertraut vor...",
      "I heard a story once about these 'keys' being purchased from a traveling merchant." => "Ich habe einmal eine Geschichte darüber gehört, dass diese „Schlüssel“ von einem reisenden Händler gekauft wurden.",
      "I suspect she will be somewhere around 7th Street in Reborn City." => "Ich vermute, dass sie irgendwo in der Nähe der 7th Street in Reborn City sein wird.",
      "I wasn't expecting such a splendid crystal cave right behind my gym." => "Ich hätte nicht mit einer so prächtigen Kristallhöhle direkt hinter meinem Fitnessstudio gerechnet.",
      "I wonder who that might have been?" => "Ich frage mich, wer das gewesen sein könnte?",
      "If you can't find that place, I suggest you contact someone who's a bit more familiar with the city's back-alley dealings." => "Wenn Sie diesen Ort nicht finden können, empfehle ich Ihnen, sich an jemanden zu wenden, der sich mit den Hinterhöfen der Stadt etwas besser auskennt.",
      "In is often out." => "Rein ist oft raus.",
      "It almost makes me look suspicious." => "Es lässt mich fast misstrauisch aussehen.",
      "It would take a fierce power to play beyond those means, and we may only hope that no such things exist." => "Es bräuchte große Kraft, über diese Mittel hinaus zu spielen, und wir können nur hoffen, dass so etwas nicht existiert.",
      "LUNA: A part of the crimson wall became brittle..." => "LUNA: Ein Teil der karmesinroten Wand ist brüchig geworden...",
      "LUNA: Hmm, touching the red crystal energized others in the cave." => "LUNA: Hm, als du den roten Kristall berührt hast, wurden auch die anderen Kristalle in der Höhle aktiviert.",
      "LUNA: It seems we can directly reach the deepest part of the impact." => "LUNA: Offenbar können wir jetzt direkt zum tiefsten Teil der Einschlagstelle gelangen.",
      "LUNA: Oh my." => "LUNA: Oh!",
      "LUNA: So, fortunately the Crystals still resonate with the keys even after the meteor impact." => "LUNA: Zum Glück reagieren die Kristalle selbst nach dem Meteoriteneinschlag noch auf die Schlüssel.",
      "LUNA: The entire wall raptured after you got enough red crystals it seems." => "LUNA: Offenbar ist die ganze Wand zerbrochen, nachdem du genug rote Kristalle gesammelt hast.",
      "LUNA: The wall cracked each time you interacted with a certain amount of crystals..." => "LUNA: Die Wand bekam jedes Mal einen Riss, wenn du genügend Kristalle berührt hattest...",
      "LUNA: The walls have the same crimson glow here..." => "LUNA: Auch hier leuchten die Wände karmesinrot...",
      "LUNA: There has to be more inside this cave that meets the eye." => "LUNA: In dieser Höhle muss noch mehr verborgen sein.",
      "LUNA: They feel... warm?" => "LUNA: Fühlen sie sich ... warm an?",
      "LUNA: This wall began to glow after you touched the crystal again." => "LUNA: Nachdem du den Kristall erneut berührt hast, begann diese Wand zu leuchten.",
      "LUNA: \\PN! It worked!" => "LUNA: \\PN! Es hat funktioniert!",
      "LUNA: \\PN, come here!" => "LUNA: \\PN, komm her!",
      "Let us look for anything infomative, there must be something leading us closer to the impact area." => "Suchen wir nach Hinweisen. Vielleicht führt uns etwas näher an die Einschlagstelle.",
      "Maybe you have to activate more of the crystals to continue." => "Vielleicht musst du weitere Kristalle aktivieren, um weiterzukommen.",
      "Maybe you need to interact with the main crystal again?" => "Vielleicht musst du den Hauptkristall noch einmal berühren?",
      "More importantly, it would appear my gambit with Elias has not paid off." => "Noch wichtiger ist, dass sich mein Schachzug mit Elias anscheinend nicht ausgezahlt hat.",
      "Now quickly, follow me." => "Jetzt schnell, folgt mir.",
      "Of course, one might wonder just how I had such an outfit as this in the first place." => "Natürlich könnte man sich fragen, wie ich überhaupt zu so einem Outfit gekommen bin.",
      "On another note, I'll beseech you allow me to keep this Amethyst Pendant a bit longer." => "Außerdem möchte ich Sie bitten, mir zu erlauben, diesen Amethyst-Anhänger noch etwas länger aufzubewahren.",
      "Or rather, walk between them." => "Oder besser gesagt, gehen Sie zwischen ihnen hindurch.",
      "RADOMUS: I cannot stay long, but allow me to leave you with some clarity." => "Radomus: Ich kann nicht lange bleiben, aber erlauben Sie mir, Sie mit etwas Klarheit zu verlassen.",
      "RADOMUS: Regardless, it seems to have been enough to fool them." => "Radomus: Wie dem auch sei, es scheint ausgereicht zu haben, um sie zu täuschen.",
      "See if there are any reactions within this cave." => "Sieh nach, ob sie in dieser Höhle etwas bewirken.",
      "Still, I can predict his next move." => "Dennoch kann ich seinen nächsten Schritt vorhersagen.",
      "Such... beauty!" => "So... wunderschön!",
      "The Crystal radiates red energy!" => "Der Kristall strahlt rote Energie aus!",
      "The Key reacted to the Crystal!" => "Der Schlüssel reagierte auf den Kristall!",
      "This must be the way further down to the crash site." => "Das muss der Weg hinunter zur Absturzstelle sein.",
      "Though if I could..." => "Aber wenn ich könnte...",
      "Try to get as many as possible." => "Versuche, so viele wie möglich zu sammeln.",
      "Unfortunately, I lacked the foresight to teach Luna to Teleport as well." => "Leider fehlte mir die Weitsicht, Luna auch das Teleportieren beizubringen.",
      "Until we meet again, adieu." => "Bis wir uns wiedersehen, adieu.",
      "What will await us there, I wonder?" => "Was uns dort wohl erwartet?",
      "What will happen if you interact with even more, I wonder?" => "Was wohl passiert, wenn du noch mehr davon berührst?",
      "Wrong is sometimes right." => "Falsch ist manchmal richtig.",
      "Yet, it appears the logical conclusion has left him unmoved." => "Dennoch scheint es, dass ihn die logische Schlussfolgerung nicht berührt hat.",
    },
    914 => {
      "A Pokémon lies in the deepest spot of the impact, seemingly unconscious." => "Ein Pokémon liegt tief in der Einschlagstelle und scheint bewusstlos zu sein.",
      "A Pokémon?" => "Ein Pokémon?",
      "And unconscious at that..." => "Und auch noch bewusstlos...",
      "Did you find anything?" => "Hast du etwas gefunden?",
      "I believe it would be best to treat it and find someone who might hold knowledge about this mysterious Pokémon." => "Am besten versorgen wir es und suchen jemanden, der etwas über dieses geheimnisvolle Pokémon weiß.",
      "I heard loud noises from the front cave!" => "Ich habe laute Geräusche aus der vorderen Höhle gehört!",
      "I will be awaiting your return in the Nightclub." => "Ich erwarte dich im Nachtclub.",
      "LUNA: Incredible..." => "LUNA: Unglaublich...",
      "LUNA: There must be a way down. Maybe the Keys will do the trick again?" => "LUNA: Es muss einen Weg nach unten geben. Vielleicht helfen die Schlüssel wieder?",
      "Let us meet there and see what happened." => "Treffen wir uns dort und sehen nach, was passiert ist.",
      "Take the Pokémon with you?" => "Das Pokémon mitnehmen?",
      "The Key reacted to the Crystal!" => "Der Schlüssel reagierte auf den Kristall!",
      "The impact area must be right beneath us." => "Die Einschlagstelle muss direkt unter uns sein.",
      "There must be a way down." => "Es muss einen Weg nach unten geben.",
      "You carefully picked up the Pokémon." => "Du hebst das Pokémon vorsichtig auf.",
    },
    915 => {
      "The Key reacted to the Crystal!" => "Der Schlüssel reagierte auf den Kristall!",
    },
