    "Kingsbury Street" => ["Kingsbury-Straße", "Kingsbury-Strasse", "Kingsbury Straße", "Kingsbury Strasse"],
    "Lilycove Street" => ["Lilycove-Straße", "Lilycove-Strasse", "Lilycove Straße", "Lilycove Strasse", "Seegrasulb-Straße", "Seegrasulb-Strasse", "Seegrasulb Straße", "Seegrasulb Strasse"],
    "Lumiose Street" => ["Lumiose-Straße", "Lumiose-Strasse", "Lumiose Straße", "Lumiose Strasse", "Illumina-Straße", "Illumina-Strasse", "Illumina Straße", "Illumina Strasse"],
    "Main Street" => ["Main-Straße", "Main-Strasse", "Main Straße", "Main Strasse", "Hauptstraße", "Hauptstrasse"],
    "Mosswater Street" => ["Mosswater-Straße", "Mosswater-Strasse", "Mosswater Straße", "Mosswater Strasse"],
    "Platinum Street" => ["Platinum-Straße", "Platinum-Strasse", "Platinum Straße", "Platinum Strasse", "Platin-Straße", "Platin-Strasse", "Platin Straße", "Platin Strasse"],
    "Poe Street" => ["Poe-Straße", "Poe-Strasse", "Poe Straße", "Poe Strasse"],
    "Saffron Street" => ["Saffron-Straße", "Saffron-Strasse", "Saffron Straße", "Saffron Strasse", "Saffronia-Straße", "Saffronia-Strasse", "Saffronia Straße", "Saffronia Strasse"],
    "Shantyport Street" => ["Shantyport-Straße", "Shantyport-Strasse", "Shantyport Straße", "Shantyport Strasse"],
    "Spitrail Street" => ["Spitrail-Straße", "Spitrail-Strasse", "Spitrail Straße", "Spitrail Strasse"],
    "Union Street" => ["Union-Straße", "Union-Strasse", "Union Straße", "Union Strasse"],
    "Yellow Street" => ["Yellow-Straße", "Yellow-Strasse", "Yellow Straße", "Yellow Strasse", "Gelbe Straße", "Gelbe Strasse", "Gelben Straße", "Gelben Strasse"],
  }.freeze

  def self.preserve_street_names(source, value)
    source = key(source)
    return value unless source && source.include?('Street') && value.is_a?(String)
    result = value.dup
    result.force_encoding(Encoding::UTF_8) if result.encoding == Encoding::ASCII_8BIT
    return value unless result.valid_encoding?
    source.scan(/(?<!\w)(\d+)(st|nd|rd|th) Street\b/).each do |number, ordinal|
      result.gsub!(/(?<!\w)#{Regexp.escape(number)}\.?\s*(?:Straße|Strasse)(?!\w)/i, number + ordinal + ' Street')
    end
    STREET_ALIASES.each do |english, aliases|
      next unless source.match?(/(?<!\w)#{Regexp.escape(english)}(?!\w)/)
      aliases.each { |name| result.gsub!(/(?<!\w)#{Regexp.escape(name)}(?!\w)/i, english) }
    end
    result == value ? value : result
  end

  module StreetNames
    def getFromHash(type, text)
      value = super
      @local_german_enabled ? LocalGermanText.preserve_street_names(text, value) : value
    end

    def getFromMapHash(type, text)
      value = super
      @local_german_enabled ? LocalGermanText.preserve_street_names(text, value) : value
    end
  end
end
if defined?(Messages) && Messages.ancestors.include?(LocalGermanText::Lookup)
  Messages.prepend(LocalGermanText::StreetNames) unless Messages.ancestors.include?(LocalGermanText::StreetNames)
end
# END ORIGINAL STREET NAMES

