    "Would you like to battle with {1}?",
    "Illegal Pokémon have been detected in {1}'s party. The trade will now exit.",
  ].freeze

  TEMPLATES = TEMPLATE_KEYS.map do |template|
    numbers = []
    pattern = template.split(/(\{\d+\})/).map do |part|
      if part =~ /\A\{(\d+)\}\z/
        numbers << $1.to_i
        '(.+?)'
      else
        Regexp.escape(part)
      end
    end.join
    [Regexp.new('\\A' + pattern + '\\z', Regexp::MULTILINE), template, numbers]
  end.freeze

