    "6. The 'Middling' Purity gem's Luster is less than the Luster of the 'Medium' gem." => "6. Der Edelstein mit Reinheit \"Mittelmäßig\" hat einen schwächeren Glanz als der Edelstein mit Größe \"Mittel\".",
    "7. The Foliation of the 'Pearly' gem is less than the Foliation of the 'Vitreous' gem, which is less than the Foliation of the 'Silky' gem." => "7. Die Spaltbarkeit des Edelsteins mit Glanz \"Perlmuttartig\" ist niedriger als die des Edelsteins mit Glanz \"Glasartig\", die wiederum niedriger ist als die des Edelsteins mit Glanz \"Seidig\".",
    "8. The Habit of the 'Silky' gem is less than the Habit of the most pure gem." => "8. Der Habitus des Edelsteins mit Glanz \"Seidig\" ist niedriger eingestuft als der des Edelsteins mit dem höchsten Reinheitsgrad.",
    "9. The Size of the 'Impure' gem is less than the Size of the 'Perfect' Foliation gem, which is less than the Size of the Sapphire." => "9. Der Edelstein mit Reinheit \"Unrein\" ist kleiner als der Edelstein mit Spaltbarkeit \"Perfekt\", der wiederum kleiner ist als der Saphir.",
    "10. The Foliation of Amethyst is less than the Foliation of the second hardest gem, which is less than the Foliation of the Sapphire." => "10. Die Spaltbarkeit des Amethysts ist niedriger als die des zweithärtesten Edelsteins, die wiederum niedriger ist als die des Saphirs.",
    "2. The Purity of the 'Coxcomb' gem is less than the Purity of the 'Miniscule' gem, which is less than the Purity of the 'Vitreous' gem." => "2. Der Edelstein mit Habitus \"Hahnenkamm\" hat einen niedrigeren Reinheitsgrad als der mit Größe \"Winzig\", der wiederum einen niedrigeren Reinheitsgrad hat als der Edelstein mit Glanz \"Glasartig\".",
    "3. The Hardness of the 'Eminent' gem is less than the Hardness of the 'Perfect' gem, which is less than the Hardness of the 'Cubic' gem." => "3. Der Edelstein mit Spaltbarkeit \"Ausgeprägt\" hat einen niedrigeren Härtegrad als der mit Spaltbarkeit \"Perfekt\", der wiederum einen niedrigeren Härtegrad hat als der Edelstein mit Habitus \"Kubisch\".",
    "4. The Purity of the gem with a Hardness of 5 is less than the Purity of the gem with 'Perfect' Foliation, which is less than the Purity of the 'Pearly' gem." => "4. Der Edelstein mit Härtegrad 5 hat einen niedrigeren Reinheitsgrad als der Edelstein mit Spaltbarkeit \"Perfekt\", der wiederum einen niedrigeren Reinheitsgrad hat als der Edelstein mit Glanz \"Perlmuttartig\".",
    "5. The Luster of the 'Tabular' gem is less than the Luster of the 'Cubic' gem, which is less than the Luster of the gem with 'Indistinct' Foliation." => "5. Der Edelstein mit Habitus \"Tafelförmig\" hat einen schwächeren Glanz als der mit Habitus \"Kubisch\", dessen Glanz wiederum schwächer ist als der des Edelsteins mit Spaltbarkeit \"Undeutlich\".",
    "6. The Size of the 'Coxcomb' gem is less than the Size of the 'Indistinct' gem, which is less than the Size of the gem with a Hardness of 8." => "6. Der Edelstein mit Habitus \"Hahnenkamm\" ist kleiner als der mit Spaltbarkeit \"Undeutlich\", der wiederum kleiner ist als der Edelstein mit Härtegrad 8.",
    "7. The Foliation of the 'Hexagonal' gem is less than the Foliation of the 'Large' gem, which is less than the Foliation of the gem with a Hardness of 7." => "7. Die Spaltbarkeit des Edelsteins mit Habitus \"Sechseckig\" ist niedriger als die des großen Edelsteins, die wiederum niedriger ist als die des Edelsteins mit Härtegrad 7.",
    "8. The Habit of the 'Flawless' gem is less than the Habit of the 'Pearly' gem, which is less than the Habit of the 'Silky' gem." => "8. Der Habitus des Edelsteins mit Reinheit \"Einwandfrei\" ist niedriger eingestuft als der des Edelsteins mit Glanz \"Perlmuttartig\", dessen Habitus wiederum niedriger eingestuft ist als der des Edelsteins mit Glanz \"Seidig\".",
  }.freeze

  def self.victory_groups(lines)
    groups = []
    lines.each do |line|
      if groups.empty? || line.match?(/\A\s*\d+\./)
        groups << [line]
      else
        groups.last << line
      end
    end
    groups
  end

  def self.victory_lines(lines, bitmap, width)
    victory_groups(lines).flat_map do |original|
      source = LocalGermanText.key(original.map(&:strip).join(' '))
      translated = VICTORY_CLUES[source]
      next original unless translated
      wrapped = []
      line = ''
      translated.split.each do |word|
        candidate = line.empty? ? word : line + ' ' + word
        if !line.empty? && bitmap.text_size(candidate).width > width
          wrapped << line
          line = '   ' + word
        else
          line = candidate
        end
      end
      wrapped << line unless line.empty?
      wrapped
    end
  end

  module VictoryPuzzle
    def pbVictoryRoadPuzzle(number)
      return super unless LocalGermanVisible.enabled?
      LocalGermanVisible.with_layout_context(:local_german_victory_clues) { super }
    end

    def pbListWindow(commands, width = 256)
      window = super
      if LocalGermanVisible.enabled? && Thread.current[:local_german_victory_clues] &&
         commands.is_a?(Array) && commands.all? { |line| line.is_a?(String) }
        window.commands = LocalGermanVisible.victory_lines(commands, window.contents, window.contents.width - 32)
      end
      window
    end
  end

  WEEKDAYS = {'Sun' => 'So', 'Mon' => 'Mo', 'Tue' => 'Di', 'Wed' => 'Mi', 'Thu' => 'Do', 'Fri' => 'Fr', 'Sat' => 'Sa'}.freeze
  MONTHS = {'Jan' => 'Jan', 'Feb' => 'Feb', 'Mar' => 'Mär', 'Apr' => 'Apr', 'May' => 'Mai', 'Jun' => 'Jun', 'Jul' => 'Jul', 'Aug' => 'Aug', 'Sep' => 'Sep', 'Oct' => 'Okt', 'Nov' => 'Nov', 'Dec' => 'Dez'}.freeze
  DAY_PERIODS = {'Day' => 'Tag', 'Night' => 'Nacht', 'Evening' => 'Abend', 'Morning' => 'Morgen'}.freeze

  def self.weather_date(value)
    return value unless value.is_a?(String)
    match = /\A(Sun|Mon|Tue|Wed|Thu|Fri|Sat) +(\d{1,2}) +(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) +- +(Day|Night|Evening|Morning)\z/.match(value)
    return value unless match
    "#{WEEKDAYS[match[1]]}, #{match[2].to_i}. #{MONTHS[match[3]]} - #{DAY_PERIODS[match[4]]}"
  end

  # Keep upstream time/calendar calculations and every update unchanged. Only
  # its exact date-display row is localized while this method draws the panel.
  module WeatherDate
    def pbTimeText
      return super unless LocalGermanVisible.enabled?
      previous = Thread.current[:local_german_weather_date]
      begin
        Thread.current[:local_german_weather_date] = true
        super
      ensure
        Thread.current[:local_german_weather_date] = previous
      end
    end
  end

  # Designed artwork is always loaded unchanged by the upstream cache.
end

if defined?(Messages) && defined?(LocalGermanText::Lookup)
  Messages.prepend(LocalGermanVisible::Lookup) unless Messages.ancestors.include?(LocalGermanVisible::Lookup)
end
if Kernel.respond_to?(:pbMessage) && Kernel.respond_to?(:pbMessageDisplay) && Kernel.respond_to?(:pbShowCommands)
  Kernel.singleton_class.prepend(LocalGermanVisible::Messages) unless Kernel.singleton_class.ancestors.include?(LocalGermanVisible::Messages)
end
if Object.private_method_defined?(:pbDrawTextPositions) || Object.method_defined?(:pbDrawTextPositions)
  Object.prepend(LocalGermanVisible::Drawing) unless Object.ancestors.include?(LocalGermanVisible::Drawing)
end

if defined?(Scene_TimeWeather) && Scene_TimeWeather.method_defined?(:pbTimeText)
  Scene_TimeWeather.prepend(LocalGermanVisible::WeatherDate) unless Scene_TimeWeather.ancestors.include?(LocalGermanVisible::WeatherDate)
end

if defined?(PokemonPokedexScene)
  PokemonPokedexScene.prepend(LocalGermanVisible::PokedexLayout) unless PokemonPokedexScene.ancestors.include?(LocalGermanVisible::PokedexLayout)
end
if defined?(PokemonScreen_Scene) && PokemonScreen_Scene.method_defined?(:pbSetHelpText)
  PokemonScreen_Scene.prepend(LocalGermanVisible::PartyPrompt) unless PokemonScreen_Scene.ancestors.include?(LocalGermanVisible::PartyPrompt)
end
if defined?(PokegearButton)
  PokegearButton.prepend(LocalGermanVisible::PokegearLayout) unless PokegearButton.ancestors.include?(LocalGermanVisible::PokegearLayout)
end
if [:pbVictoryRoadPuzzle, :pbListWindow].all? { |name| Object.private_method_defined?(name) || Object.method_defined?(name) }
  Object.prepend(LocalGermanVisible::VictoryPuzzle) unless Object.ancestors.include?(LocalGermanVisible::VictoryPuzzle)
end

if defined?(MonData)
  MonData.prepend(LocalGermanVisible::CustomEeveeDisplay) unless MonData.ancestors.include?(LocalGermanVisible::CustomEeveeDisplay)
end

