      'GARDEVOIR: I think someone\'s gone a little Looney-tone~' => ['GARDEVOIR: Ich glaube, da ist jemand ein bisschen verrückt geworden', 'GUARDEVOIR: Ich glaube, da ist jemand ein bisschen verrückt geworden'],
      'GARDEVOIR: Ah, ah, ah~ You finally figured it out!' => ['GARDEVOIR: Ah, ah, ah~ Du hast es endlich herausgefunden!', 'GUARDEVOIR: Ah, ah, ah~ Du hast es endlich herausgefunden!'],
