    82 => {
      'If you have a Pokémon that\'s truly happy with you, I\'d like to see it. I won\'t believe a thing until then.' => ['Wenn Sie einen Pokémon haben, mit dem Sie wirklich zufrieden sind, würde ich ihn gerne sehen. Bis dahin werde ich nichts glauben.', 'Wenn Sie ein Pokémon haben, das bei Ihnen wirklich glücklich ist, würde ich es gerne sehen. Vorher glaube ich Ihnen kein Wort.'],
      'I\'ve got a Pokémon that\'ll really kick off our image.' => ['Ich habe einen Pokémon, der unserem Image einen echten Kick geben wird.', 'Ich habe ein Pokémon, das unserem Image einen echten Kick geben wird.'],
    },
    97 => {
      'GARDEVOIR: You\'re gonna try and fix your Gym?' => ['GARDEVOIR: Versuchen Sie, Ihren Gym zu reparieren?', 'GUARDEVOIR: Versuchen Sie, Ihren Gym zu reparieren?'],
      'GARDEVOIR: Good luck fixing the whole city~' => ['GARDEVOIR: Viel Glück beim Reparieren der ganzen Stadt~', 'GUARDEVOIR: Viel Glück beim Reparieren der ganzen Stadt~'],
      'GARDEVOIR: Yup! And this\'ll make a niiiice juicy news story, too~' => ['GARDEVOIR: Ja! Und das wird auch eine nette, saftige Nachricht sein~', 'GUARDEVOIR: Ja! Und das wird auch eine nette, saftige Nachricht sein~'],
      'GARDEVOIR: Ooooh. Well, if that\'s how it is~' => ['GARDEVOIR: Ooooh. Na ja, wenn das so ist~', 'GUARDEVOIR: Ooooh. Na ja, wenn das so ist~'],
