      'GARDEVOIR: Hm? Haven\'t you met a Pokémon that can communicate before?' => ['GARDEVOIR: HM? Haben Sie noch nie einen Pokémon getroffen, der kommunizieren kann?', 'GUARDEVOIR: Hm? Haben Sie noch nie ein Pokémon getroffen, das sprechen kann?'],
      'GARDEVOIR: Oh, don\'t look so surprised that Master knows who you are already~' => ['GARDEVOIR: Oh, schauen Sie nicht so überrascht, dass der Meister bereits weiß, wer Sie sind~', 'GUARDEVOIR: Oh, schauen Sie nicht so überrascht, dass der Meister bereits weiß, wer Sie sind~'],
