      'Specifically, a Pokémon that can travel through time, but not space.' => ['Konkret handelt es sich um einen Pokémon, der durch die Zeit, aber nicht durch den Weltraum reisen kann.', 'Genauer gesagt: ein Pokémon, das durch die Zeit reisen kann, aber nicht durch den Raum.'],
    },
    817 => {
      'Usually I have to scramble to send out a Pokémon to catch me before I plummet to my death.' => ['Normalerweise muss ich mich abmühen, um einen Pokémon loszuschicken, der mich auffängt, bevor ich in den Tod stürzte.', 'Normalerweise muss ich schnell ein Pokémon rausschicken, das mich auffängt, bevor ich in den Tod stürze.'],
      'The uh, \'funky onion\', is a Pokémon that can sort of... travel through time.' => ['Die „Funky Onion“ ist ein Pokémon, der irgendwie... durch die Zeit reisen kann.', 'Die, äh, „Funky Onion“ ist ein Pokémon, das irgendwie ... durch die Zeit reisen kann.'],
    },
    825 => {
      'REGISTEEL: Krrrrchzznvt--' => ['REGISTRIER: Krrrrchzznvt--', 'REGISTEEL: Krrrrchzznvt--'],
    },
    827 => {
      'Is it weird to call a Pokémon "mate"?' => ['Ist es seltsam, einen Pokémon „Kumpel“ zu nennen?', 'Ist es seltsam, ein Pokémon „Kumpel“ zu nennen?'],
      'You know how there\'s supposed to be some Pokémon out there that there\'s only one of in the world?' => ['Wissen Sie, dass es da draußen einen Pokémon geben soll, von dem es nur einen auf der Welt gibt?', 'Wissen Sie, dass es Pokémon geben soll, von denen jeweils nur ein einziges auf der Welt existiert?'],
      'ZERO: \\PN.' => ['NULL: \\PN.', 'ZERO: \\PN.'],
      'ZERO: Need a reminder?' => ['NULL: Brauchen Sie eine Erinnerung?', 'ZERO: Brauchen Sie eine Erinnerung?'],
      'ZERO: Great.' => ['NULL: Großartig.', 'ZERO: Großartig.'],
      'ZERO: Adrienn has asked to meet you at Grandview Station.' => ['NULL: Adrienn hat Sie um ein Treffen an der Grandview Station gebeten.', 'ZERO: Adrienn hat Sie um ein Treffen an der Grandview Station gebeten.'],
      'ZERO: There are reports about power issues coming from the LCCC.' => ['NULL: Es gibt Berichte über Stromversorgungsprobleme vom LCCC.', 'ZERO: Es gibt Berichte über Stromversorgungsprobleme vom LCCC.'],
      'ZERO: Unfortunately, there\'s still nothing on our radars.' => ['NULL: Leider ist immer noch nichts auf unserem Radar.', 'ZERO: Leider ist immer noch nichts auf unserem Radar.'],
      'ZERO: ...Y\'know, \\PN...' => ['NULL: ... Weißt du, \\PN...', 'ZERO: ... Weißt du, \\PN...'],
      'Bring me a Pokémon, and I\'ll memorize its moves as they are.' => ['Bring mir einen Pokémon und ich werde mir seine Attacken so merken, wie sie sind.', 'Bring mir ein Pokémon, und ich merke mir seine aktuellen Attacken.'],
    },
    840 => {
