    847 => {
      'you\'re thinking you can get around this by just releasing one Pokémon at a time until you hit whatever the minimum arbitrary number i\'ll be satisfied with is.' => ['Sie denken, Sie können dies umgehen, indem Sie jeweils einen Pokémon freigeben, bis Sie die minimale willkürliche Anzahl erreicht haben, mit der ich zufrieden bin.', 'du denkst, du kannst das umgehen, indem du immer ein Pokémon nach dem anderen freilässt, bis du die willkürliche Mindestanzahl erreicht hast, mit der ich zufrieden bin.'],
      'you should report this message as a bug if you happen to get it because that means you negative released a Pokémon???? how even??what did you DO?' => ['Sie sollten diese Nachricht als Käfer melden, wenn Sie sie erhalten, denn das bedeutet, dass Sie negativ einen Pokémon veröffentlicht haben???? Wie überhaupt??Was hast du gemacht?', 'meld diese Nachricht bitte als Bug, falls du sie siehst, denn das heißt, du hast eine negative Anzahl Pokémon freigelassen???? wie geht das überhaupt??was hast du GEMACHT?'],
    },
    849 => {
