    901 => {
      'AUTUMN: Oh, hi there! Welcome to the Dev Room! This is uhh.. I guess where we all just kinda relax and chill?' => ['HERBST: Oh, hallo! Willkommen im Dev Room! Das ist, äh... ich schätze, wo wir uns alle einfach nur entspannen und entspannen?', 'AUTUMN: Oh, hi! Willkommen im Dev Room! Hier, äh ... entspannen wir uns einfach und chillen ein bisschen, schätze ich?'],
      'AUTUMN: Okay fine! Here, I was saving these for another Explosion TM from Sinnoh that I\'ve heard lowers the opposing Pokémon\'s defense...' => ['HERBST: Okay, gut! Hier habe ich diese für eine weitere Explosion TM von Sinnoh aufgehoben, von der ich gehört habe, dass sie die Verteidigung des gegnerischen Pokémon schwächt ...', 'AUTUMN: Okay, gut! Hier habe ich diese für eine weitere Explosion TM von Sinnoh aufgehoben, von der ich gehört habe, dass sie die Verteidigung des gegnerischen Pokémon schwächt ...'],
      'AUTUMN: Oh, okay! Enjoy the rest of the dev room, then!' => ['HERBST: Oh, okay! Dann genießen Sie den Erholung des Entwicklungsraums!', 'AUTUMN: Oh, okay! Dann viel Spaß im Rest des Dev Rooms!'],
      'AUTUMN: Oh,\\| right,\\| yeah,\\| sure,\\| of course.\\| Hey, before you go, what\'s your favorite Pokémon?' => ['HERBST: Oh,\\| richtig,\\| ja,\\| sicher,\\| Natürlich. \\| Hey, bevor du gehst, was ist dein Lieblings-Pokémon?', 'AUTUMN: Oh,\\| richtig,\\| ja,\\| sicher,\\| Natürlich. \\| Hey, bevor du gehst, was ist dein Lieblings-Pokémon?'],
      'AUTUMN: 3...\\| 2...\\| 1...\\| Andddd...\\.\\.\\. Bang.\\|' => ['HERBST: 3... \\| 2... \\| 1... \\| Undddd... \\. \\. \\. Knall. \\|', 'AUTUMN: 3... \\| 2... \\| 1... \\| Undddd... \\. \\. \\. Knall. \\|'],
    },
