  BOSS_TEXTS = {
    'Hey! I thought I\'d come down here, see if there was anything new to see. It\'s pretty neat!' => 'Hey! Ich dachte, ich schau mal runter, ob es hier was Neues gibt. Ist echt cool hier!',
    'Eh, wasn\'t my best showing, but it was fun.' => 'Tja, das war nicht meine beste Leistung, aber Spaß hat\'s gemacht.',
    'Huh... maybe this is the beginning of my new path?' => 'Huch... vielleicht beginnt hier ja mein neuer Weg?',
    'IF AH WIN, CAN HAVE HUG?' => 'WENN ICH GEWINN, KRIEG ICH UMARMUNG?',
    'NO HUG FOR BIGGLES...' => 'KEINE UMARMUNG FÜR BIGGLES...',
    'BIGGLES WIN! HUG NOW?' => 'BIGGLES GEWINNT! JETZT UMARMUNG?',
    'LET\'S HAVE A FUCKIN\' BAD-ASS BATTLE!' => 'LASS UNS EIN VERDAMMT GEILES BATTLE LIEFERN!',
    'What the fuck? That\'s fucking bullshit, man!' => 'Was zur Hölle? Das ist doch totaler Scheiß, Mann!',
    'Did I fucking win? That\'s fucking awesome!' => 'Hab ich echt gewonnen? Das ist ja verdammt geil!',
    'Oh hey, if it isn\'t my favorite gofer!' => 'Oh hey, wenn das nicht mein Lieblingslaufbursche ist!',
    'Of course you won, when you had the advantage. Next time try battling without being able to see, and then we\'ll see who\'s the better Trainer.' => 'Natürlich hast du gewonnen, du hattest ja den Vorteil. Kämpf nächstes Mal, ohne sehen zu können, dann sehen wir, wer von uns besser ist.',
    'Wow! Beaten by a girl who can\'t see, hm? I bet that\'s going to give your ego a bruising. Well, good! Hee hee.' => 'Wow! Von einem blinden Mädchen besiegt, hm? Das gibt deinem Ego bestimmt einen ordentlichen Dämpfer. Tja, gut so! Hehe.',
    'I haven\'t had a challenger for a while, this oughtta be fun!' => 'Mich hat schon länger niemand mehr herausgefordert. Das wird bestimmt lustig!',
    'All right, all right, you\'ve put me back on solid ground now.' => 'Schon gut, schon gut. Du hast mich wieder auf den Boden der Tatsachen geholt.',
    'See what happens when you love the planet? It loves you back!' => 'Siehst du, was passiert, wenn man den Planeten liebt? Er liebt dich zurück!',
    'Been a while, huh, boss? Let\'s make it a great battle, for old times\' sake. And for her.' => 'Ist lange her, Boss. Machen wir einen großartigen Kampf draus – wie früher. Und für sie.',
    'Well fought. Thank you.' => 'Gut gekämpft. Danke.',
    'Maybe... I\'m finally growing. Thank you.' => 'Vielleicht... wachse ich endlich über mich hinaus. Danke.',
    'It\'s so much nicer to battle now that the city\'s so beautiful again.' => 'Es ist so viel schöner, wieder zu kämpfen, jetzt, wo die Stadt so wunderschön ist.',
    'Had a feeling this was how it\'d go.' => 'Ich hatte so eine Ahnung, dass es so laufen würde.',
    'You\'ve come a long way since we met, but this is the end of the line for today.' => 'Seit unserem Treffen bist du weit gekommen, aber für heute ist Schluss.',
    'Madame Meganium stares at you levelly.' => 'Madame Meganium starrt dich mit unbewegter Miene an.',
    'Madame Meganium gives you a long, level look, and then gives a small nod of approval.' => 'Madame Meganium mustert dich lange und nickt dann anerkennend.',
    'Madame Meganium tosses her head proudly.' => 'Madame Meganium wirft stolz den Kopf zurück.',
    'BREEEEEEEEE-' => 'BREEEEEEEEE-',
    '-LOOOOOOOOM! Error! Error!' => '-LOOOOOOOOM! Fehler! Fehler!',
    '-LOOM. Beep beep!' => '-LOOM. Piep piep!',
    'Finally, our destined reunion!' => 'Endlich! Unser vorherbestimmtes Wiedersehen!',
    'And once more, I face my defeat...' => 'Und wieder muss ich mich meiner Niederlage stellen...',
    'The light of victory shines upon me...' => 'Das Licht des Sieges scheint auf mich...',
    'Are YOU ready to take on Agate Circus\' best clown?' => 'Bist DU bereit, dich dem besten Clown des Agate-Zirkus zu stellen?',
    'Aaaaaand we have a winner! The fabulous Champion!' => 'Uuuund wir haben einen Sieger! Den fabelhaften Champ!',
    'Aaaand once more the dashing clown Indra reigns victorious!' => 'Uuuund wieder triumphiert der charmante Clown Indra!',
    'Aqua Gang may be gone, but I\'m going to make a splash here!' => 'Die Aqua-Gang gibt\'s vielleicht nicht mehr, aber hier sorge ich trotzdem für Furore!',
    'Ah, well. It was entertaining enough.' => 'Na ja. Es war immerhin unterhaltsam.',
    'What\'s the matter? Would you say you\'re a little washed up?' => 'Was ist los? Bist du etwa ein bisschen abgesoffen?',
    'I may have disbanded the Magma Gang, but you bet you\'re gonna see I\'m still hot stuff!' => 'Ich habe die Magma-Gang zwar aufgelöst, aber du wirst schon sehen, dass ich immer noch heiß bin!',
    'Guess I didn\'t do so hot.' => 'Das war wohl nicht gerade der Burner.',
    'FOR GLORY, BABY!' => 'FÜR DEN RUHM, BABY!',
    'Let\'s put on a great show, maybe drum up some publicity for the Circus!' => 'Bieten wir eine großartige Show und machen ein bisschen Werbung für den Zirkus!',
    'Pretty much what I figured, but it was fun!' => 'So ungefähr hatte ich\'s erwartet, aber Spaß hat\'s gemacht!',
    'Hey, that was great! I wonder if anyone recorded it? Maybe we could use it as a promo video...' => 'Hey, das war großartig! Ob das jemand aufgenommen hat? Vielleicht könnten wir\'s als Werbevideo nehmen...',
    'I\'ll send you packing, you MISERABLE SLIME!' => 'Ich mach dich fertig, du ELENDER SCHLEIMHAUFEN!',
    'How DARE YOU? You came here just to HUMILIATE a KIND OLD WOMAN! I\'ll sue you! I\'LL SUE THIS WHOLE CLUB!' => 'Wie kannst DU es wagen? Du bist nur hergekommen, um eine LIEBE ALTE DAME zu DEMÜTIGEN! Ich verklag dich! ICH VERKLAG DEN GANZEN CLUB!',
    'See? SEE? I\'VE STILL GOT IT!' => 'Siehst du? SIEHST DU? ICH HAB\'S IMMER NOCH DRAUF!',
    'Oh, hiya~ Here to show me your Pikachu?' => 'Oh, hallöchen~ Zeigst du mir dein Pikachu?',
    'No fair! I didn\'t get to play with your Pikachu!' => 'Unfair! Ich durfte gar nicht mit deinem Pikachu spielen!',
    'I guess my Pikachu were stronger. All Pikachu are good though.' => 'Tja, meine Pikachu waren wohl stärker. Aber alle Pikachu sind toll.',
    'Smeargle holds up a sign that says \'human not win this battle\'.' => 'Farbeagle hält ein Schild hoch: „Mensch gewinnt diesen Kampf nicht.“',
    'Smeargle holds out a notepad and hastily scribbles, \'guess human did win. good battle.\'' => 'Farbeagle hält einen Notizblock hin und kritzelt hastig: „mensch hat wohl doch gewonnen. guter kampf.“',
    'Smeargle holds out a notepad and flips a page to where he\'s written \'smeargle best trainer. human good battler too though.' => 'Farbeagle hält einen Notizblock hin und blättert zu einer Seite: „farbeagle bester trainer. mensch aber auch guter kämpfer.“',
    '...Hey. Well, let\'s get to it, shall we?' => '...Hey. Na dann, legen wir los, ja?',
    'Just like always.' => 'Wie immer.',
    '...Huh. I won. How about that?' => '...Huch. Ich hab gewonnen. Na sowas.',
    'hi. i\'m cass. let\'s FITE.' => 'hi. ich bin cass. lass uns FIGHTEN.',
    'is this done yet? good.' => 'ist das jetzt vorbei? gut.',
    'oh hey. that was kind of fun.' => 'oh hey. das hat irgendwie spaß gemacht.',
    'Hmph. I wish they would stop sending incompetents out to face me.' => 'Hmpf. Ich wünschte, sie würden mir keine unfähigen Leute mehr vorsetzen.',
    'Hmph. I suppose you weren\'t completely incompetent for a change.' => 'Hmpf. Du warst ausnahmsweise nicht völlig unfähig.',
    'Hmph. I\'ve seen Magikarp with more skill at battling and more intellect.' => 'Hmpf. Ich habe schon Karpador gesehen, die besser kämpfen und mehr Grips haben.',
    'All right, let\'s jazz this place up.' => 'Na los, bringen wir hier etwas Schwung rein.',
    'A smooth victory.' => 'Ein souveräner Sieg.',
    'I guess you can\'t compete with a true master, in battle or in music.' => 'Mit einem wahren Meister kannst du wohl weder im Kampf noch in der Musik mithalten.',
    'Hello! Fancy a lemonade?' => 'Hallo! Lust auf eine Limonade?',
    'Well, that wasn\'t very nice!' => 'Na, das war aber nicht nett!',
    'My Pokemon did great. Such good boys. And girls.' => 'Meine Pokémon waren toll. So liebe Jungs und Mädels.',
    'All right. The faster we get this fight done, the faster I can get back to work.' => 'Machen wir\'s kurz, dann kann ich schneller wieder an die Arbeit.',
    'Well, back to work.' => 'Na gut, zurück an die Arbeit.',
    'I won. Woohoo. Okay, back to work.' => 'Ich hab gewonnen. Juhu. Okay, zurück an die Arbeit.',
    'Oh, h\'llo. Fancy a friendly match?' => 'Oh, hallo. Lust auf einen Freundschaftskampf?',
    'Didn\'t win, but that was a right good battle.' => 'Nicht gewonnen, aber das war ein verdammt guter Kampf.',
    'And that there\'s a lesson to ya.' => 'Und daraus kannste was lernen.',
    'I don\'t need my crystal ball to see your loss here.' => 'Ich brauche keine Kristallkugel, um deine Niederlage vorauszusehen.',
    'B-but- How could I have been wrong?' => 'A-aber... Wie konnte ich mich irren?',
    'It\'s as I told you. My prophecies are never wrong.' => 'Wie ich sagte: Meine Prophezeiungen sind immer richtig.',
    '...Hi. Good to see you again.' => '...Hi. Schön, dich wiederzusehen.',
    'Even with my defeat, it was pleasant to battle with you once more.' => 'Trotz meiner Niederlage war es schön, wieder einmal mit dir zu kämpfen.',
    'Man. No hard feelings, but I have to admit, it was nice to win against you for a change.' => 'Mann. Nichts für ungut, aber es war schön, dich ausnahmsweise mal zu besiegen.',
    'Heya, partner! Well-- \'course we\'re not partners right now, but-- Let\'s just have fun, \'kay?' => 'Hey, Kumpel! Na ja – gerade sind wir keine Partner, aber lass uns einfach Spaß haben, ja?',
    'Eh. I always told ya I wasn\'t much of a battler.' => 'Na ja. Ich hab dir immer gesagt, dass ich kein großer Kämpfer bin.',
    'I won? Really truly?' => 'Ich hab gewonnen? Echt jetzt?',
    'Now how\'s about I show you how we battle over in Train Town?' => 'Wie wär\'s, wenn ich dir zeige, wie man in Train Town kämpft?',
    'Guess you didn\'t need to learn after all.' => 'Du musst wohl doch nichts mehr lernen.',
    'And that\'s how ya battle in Train Town!' => 'So kämpft man in Train Town!',
    'Get ready for a stormy battle!' => 'Mach dich auf einen stürmischen Kampf gefasst!',
    'Guess the winds of fate weren\'t blowing for me.' => 'Tja, die Winde des Schicksals waren wohl nicht auf meiner Seite.',
    'Sometimes one good move\'s all it takes to turn the tide.' => 'Manchmal reicht ein guter Zug, um das Blatt zu wenden.',
    'Hey. We\'ve got a clean slate now; let\'s just have a good battle.' => 'Hey. Wir fangen ganz unbelastet an. Lass uns einfach einen guten Kampf haben.',
    'I did my best, okay? Good luck.' => 'Ich hab mein Bestes gegeben, okay? Viel Glück.',
    '...That was a good battle. Thank you.' => '...Das war ein guter Kampf. Danke.',
    'We are no longer enemies, but do not make the mistake of underestimating me.' => 'Wir sind keine Feinde mehr. Unterschätze mich trotzdem nicht.',
    'And yet it appears I was the one who underestimated you. My apologies.' => 'Und doch war offenbar ich es, der dich unterschätzt hat. Verzeihung.',
    'Excellent... This is a step forward.' => 'Ausgezeichnet... Das ist ein Schritt nach vorn.',
    'Nice to get a break from official duty!' => 'Schön, mal eine Pause vom Dienst zu haben!',
    'Heh... you pulled off some arrestingly good moves there.' => 'Heh... das waren verblüffend gute Züge.',
    'Nice. Now the boys owe me dinner!' => 'Gut. Jetzt schulden mir die Jungs ein Abendessen!',
    '\'Ello. Told you I might stop by!' => 'Hallo. Hab doch gesagt, dass ich vielleicht vorbeischau!',
    'I suppose I shouldn\'t have expected to win against the Champion on my first try.' => 'Ich hätte wohl nicht erwarten sollen, den Champ gleich beim ersten Versuch zu schlagen.',
    'Hm. Guess it was a good thing after all, coming here.' => 'Hm. Es war wohl doch eine gute Idee, herzukommen.',
    'Tu...' => 'Tu...',
    '...' => '...',
    '...!' => '...!',
    'Oh hey! I\'m Crim! I\'m so excited to be here, let\'s have some fun!' => 'Oh hey! Ich bin Crim! Ich freu mich riesig, hier zu sein. Lass uns Spaß haben!',
    'That was awesome! You\'re really something, you know that?' => 'Das war großartig! Du hast echt was drauf, weißt du das?',
    'I\'ll see you in the back alley!' => 'Wir sehen uns in der Hintergasse!',
  }.freeze
  FACILITY_TEXTS = {
    ['Kirk', 'YOUNGSTER', 'introSpeech', 'Battling... battling\'s my game!'] => 'Beim Kämpfen fühl ich mich ganz in meinem Element!',
    ['Kirk', 'YOUNGSTER', 'winSpeech', 'I\'m strong, right?'] => 'Ich bin stark, oder?',
    ['Kirk', 'YOUNGSTER', 'loseSpeech', 'How could this happen!?'] => 'Wie konnte das nur passieren!?',
    ['Nico', 'YOUNGSTER', 'introSpeech', 'Nobody here can beat me!'] => 'Hier kann mich doch keiner schlagen!',
    ['Nico', 'YOUNGSTER', 'winSpeech', 'See? I told you nobody could beat me!'] => 'Na, hab ich\'s nicht gesagt? Keiner kann mich besiegen!',
    ['Nico', 'YOUNGSTER', 'loseSpeech', 'I guess I was wrong...'] => 'Da lag ich wohl falsch...',
    ['Clayton', 'YOUNGSTER', 'introSpeech', 'Hey, check out my awesome team!'] => 'Hey, schau dir mein starkes Team an!',
    ['Clayton', 'YOUNGSTER', 'winSpeech', 'We did it!'] => 'Wir haben\'s geschafft!',
    ['Clayton', 'YOUNGSTER', 'loseSpeech', 'My Pokemon still did a good job!'] => 'Meine Pokémon haben sich trotzdem gut geschlagen!',
    ['Candy', 'COOLTRAINER_Female', 'introSpeech', 'Time for a sweet battle!'] => 'Zeit für einen zuckersüßen Kampf!',
    ['Candy', 'COOLTRAINER_Female', 'winSpeech', 'Yay! I\'m a sugar star!'] => 'Juhu! Ich bin ein Zuckerstern!',
    ['Candy', 'COOLTRAINER_Female', 'loseSpeech', 'Now I\'m bitter...'] => 'Jetzt bin ich ganz verbittert...',
    ['Evevee', 'COOLTRAINER_Female', 'introSpeech', 'This should be fun!'] => 'Das wird bestimmt lustig!',
    ['Evevee', 'COOLTRAINER_Female', 'winSpeech', 'Victory is mine!'] => 'Der Sieg gehört mir!',
    ['Evevee', 'COOLTRAINER_Female', 'loseSpeech', 'I was getting bored anyway...'] => 'Mir war sowieso schon langweilig...',
    ['Nelisie', 'COOLTRAINER_Female', 'introSpeech', 'Get ready to lose!'] => 'Mach dich auf deine Niederlage gefasst!',
    ['Nelisie', 'COOLTRAINER_Female', 'winSpeech', 'We destroyed you!'] => 'Wir haben dich fertiggemacht!',
    ['Nelisie', 'COOLTRAINER_Female', 'loseSpeech', 'Why\'d you have to be so mean?'] => 'Warum musstest du so gemein sein?',
    ['Obligus', 'Cultist', 'introSpeech', 'I don\'t just study, you know!'] => 'Ich lerne nicht nur, weißt du!',
    ['Obligus', 'Cultist', 'winSpeech', 'You should study more.'] => 'Du solltest mehr lernen.',
    ['Obligus', 'Cultist', 'loseSpeech', 'I guess I need to study more...'] => 'Ich sollte wohl mehr lernen...',
    ['Ijenske', 'Cultist', 'introSpeech', 'Let\'s see who has the better moves!'] => 'Mal sehen, wer die besseren Moves draufhat!',
    ['Ijenske', 'Cultist', 'winSpeech', 'You were hopelessly outmatched.'] => 'Du hattest nicht den Hauch einer Chance.',
    ['Ijenske', 'Cultist', 'loseSpeech', 'You outplayed us...'] => 'Du hast uns ganz schön ausgespielt...',
    ['Hawkins', 'Cultist', 'introSpeech', 'I seek to be a master of the battling arts.'] => 'Ich will ein Meister der Kampfkunst werden.',
    ['Hawkins', 'Cultist', 'winSpeech', 'You have a long way to go!'] => 'Du hast noch einen weiten Weg vor dir!',
    ['Hawkins', 'Cultist', 'loseSpeech', 'Perhaps you will be the master...'] => 'Vielleicht wirst du ja der Meister...',
    ['Maura', 'PSYCHIC_Female', 'introSpeech', 'I will never give up until I win!'] => 'Ich gebe niemals auf, bis ich gewinne!',
    ['Maura', 'PSYCHIC_Female', 'winSpeech', 'This was the only way it could have gone!'] => 'Es konnte gar nicht anders ausgehen!',
    ['Maura', 'PSYCHIC_Female', 'loseSpeech', 'I still will not give up...'] => 'Ich gebe trotzdem nicht auf...',
    ['Elise', 'PSYCHIC_Female', 'introSpeech', 'I\'ve learned all I know from my mother!'] => 'Alles, was ich weiß, hab ich von meiner Mutter gelernt!',
    ['Elise', 'PSYCHIC_Female', 'winSpeech', 'My mother taught me well!'] => 'Meine Mutter hat mich gut unterrichtet!',
    ['Elise', 'PSYCHIC_Female', 'loseSpeech', 'Mother? '] => 'Mama?',
    ['Zoey', 'PSYCHIC_Female', 'introSpeech', 'Show me your true intentions with this battle!'] => 'Zeig mir in diesem Kampf, was du wirklich vorhast!',
    ['Zoey', 'PSYCHIC_Female', 'winSpeech', 'You showed me your intent, but mine was stronger!'] => 'Du hast mir deine Absichten gezeigt, aber meine waren stärker!',
    ['Zoey', 'PSYCHIC_Female', 'loseSpeech', 'I understand now.'] => 'Jetzt verstehe ich.',
    ['Funk', 'GENTLEMAN', 'introSpeech', 'Don\'t look at me like that! I\'m hip too!'] => 'Schau mich nicht so an! Ich bin auch voll hip!',
    ['Funk', 'GENTLEMAN', 'winSpeech', 'Hahaha! I\'m lolling!'] => 'Hahaha! Ich lach mich schlapp!',
    ['Funk', 'GENTLEMAN', 'loseSpeech', 'Ah, forget it. '] => 'Ach, vergiss es.',
    ['Shiro', 'GENTLEMAN', 'introSpeech', 'I shall show you the power of my dear partners!'] => 'Ich zeige dir die Kraft meiner liebsten Partner!',
    ['Shiro', 'GENTLEMAN', 'winSpeech', 'Did I not tell you? They\'re simply wonderful!'] => 'Hab ich\'s dir nicht gesagt? Sie sind einfach wunderbar!',
    ['Shiro', 'GENTLEMAN', 'loseSpeech', 'That was unkind!'] => 'Das war aber nicht nett!',
    ['Randy', 'GENTLEMAN', 'introSpeech', 'Age before beauty!'] => 'Alter vor Schönheit!',
    ['Randy', 'GENTLEMAN', 'winSpeech', 'My battling skills have aged like a fine wine!'] => 'Meine Kampfkünste sind wie guter Wein gereift!',
    ['Randy', 'GENTLEMAN', 'loseSpeech', 'You should learn to respect your elders!'] => 'Du solltest lernen, deine Älteren zu respektieren!',
    ['Tina', 'LADY', 'introSpeech', 'If I win, you can have a Sweet Kiss!'] => 'Wenn ich gewinne, kriegst du einen Bitterkuss!',
    ['Tina', 'LADY', 'winSpeech', 'Here you are! A Sweet Kiss from my Jynx- Wait, where are you going!?'] => 'Hier, ein Bitterkuss von meinem Rossana—Moment, wo willst du hin!?',
    ['Tina', 'LADY', 'loseSpeech', 'You want a swift Jump Kick instead!?'] => 'Willst du stattdessen einen schnellen Sprungkick kassieren!?',
    ['Karen', 'LADY', 'introSpeech', 'I need a battle, and I need it now!'] => 'Ich brauche einen Kampf, und zwar sofort!',
    ['Karen', 'LADY', 'winSpeech', 'Next, I\'ll pick up the dry cleaning...'] => 'Als Nächstes muss ich die Sachen aus der Reinigung abholen...',
    ['Karen', 'LADY', 'loseSpeech', 'What? I demand to speak with a manager!'] => 'Wie bitte? Ich will sofort mit der Geschäftsleitung sprechen!',
    ['ZOE', 'LADY', 'introSpeech', 'Isn\'t this facility just fabulous?'] => 'Ist diese Anlage nicht einfach fabelhaft?',
    ['ZOE', 'LADY', 'winSpeech', 'This atmosphere is to die for!'] => 'Diese Atmosphäre ist einfach zum Sterben schön!',
    ['ZOE', 'LADY', 'loseSpeech', 'I-I was distracted by the lighting!'] => 'I-Ich war vom Licht abgelenkt!',
    ['Clintz', 'COOLTRAINER_Male', 'introSpeech', 'You\'ve got nothing on me!'] => 'Du hast mir nichts entgegenzusetzen!',
    ['Clintz', 'COOLTRAINER_Male', 'winSpeech', 'This is what real skill looks like!'] => 'So sieht wahres Können aus!',
    ['Clintz', 'COOLTRAINER_Male', 'loseSpeech', 'Apparently I\'ve got nothing on you...'] => 'Anscheinend kann ich dir doch nichts entgegensetzen...',
    ['Henrique', 'COOLTRAINER_Male', 'introSpeech', 'You look pretty weak.'] => 'Du wirkst ziemlich schwach.',
    ['Henrique', 'COOLTRAINER_Male', 'winSpeech', 'Don\'t worry, you\'ll toughen up eventually.'] => 'Keine Sorge, irgendwann wirst du schon härter.',
    ['Henrique', 'COOLTRAINER_Male', 'loseSpeech', 'I was wrong! I was wrong!'] => 'Ich lag falsch! Ich lag falsch!',
    ['Arthur', 'COOLTRAINER_Male', 'introSpeech', 'I\'m destined to defeat you!'] => 'Es ist mein Schicksal, dich zu besiegen!',
    ['Arthur', 'COOLTRAINER_Male', 'winSpeech', 'No one can defeat the king!'] => 'Niemand kann den König besiegen!',
    ['Arthur', 'COOLTRAINER_Male', 'loseSpeech', 'Could the stars have been wrong?'] => 'Könnten die Sterne sich geirrt haben?',
    ['Anne', 'RANGERF', 'introSpeech', 'I\'m so glad I live in a world where there are battles!'] => 'Ich bin so froh, in einer Welt voller Pokémonkämpfe zu leben!',
    ['Anne', 'RANGERF', 'winSpeech', 'It\'s delightful when your imaginations come true, isn\'t it?'] => 'Es ist herrlich, wenn deine Vorstellungen wahr werden, findest du nicht?',
    ['Anne', 'RANGERF', 'loseSpeech', 'My life is a perfect graveyard of buried hopes!'] => 'Mein Leben ist ein perfekter Friedhof begrabener Hoffnungen!',
    ['Alize', 'RANGERF', 'introSpeech', 'Don\'t ever take Pokemon for granted!'] => 'Nimm Pokémon niemals für selbstverständlich!',
    ['Alize', 'RANGERF', 'winSpeech', 'My team knows how much I care for them!'] => 'Mein Team weiß, wie sehr ich es lieb habe!',
    ['Alize', 'RANGERF', 'loseSpeech', 'I can see you respect your Pokemon!'] => 'Ich sehe, du respektierst deine Pokémon!',
    ['Lauren', 'RANGERF', 'introSpeech', 'I\'m always in high spirits!'] => 'Ich bin immer bester Laune!',
    ['Lauren', 'RANGERF', 'winSpeech', 'I\'m on Cloud 9!'] => 'Ich schwebe auf Wolke sieben!',
    ['Lauren', 'RANGERF', 'loseSpeech', 'You brought me back down to earth...'] => 'Du hast mich auf den Boden der Tatsachen zurückgeholt...',
    ['Lukan', 'SWIMMERBOI', 'introSpeech', 'Surf\'s up!'] => 'Die Wellen rufen!',
    ['Lukan', 'SWIMMERBOI', 'winSpeech', 'Watch out for the big waves!'] => 'Pass auf die großen Wellen auf!',
    ['Lukan', 'SWIMMERBOI', 'loseSpeech', 'Wiped out...'] => 'Abgesoffen...',
    ['Jason', 'SWIMMERBOI', 'introSpeech', 'Me and my Pokemon have been training hard!'] => 'Meine Pokémon und ich haben hart trainiert!',
    ['Jason', 'SWIMMERBOI', 'winSpeech', 'Our strategy was the best!'] => 'Unsere Strategie war die beste!',
    ['Jason', 'SWIMMERBOI', 'loseSpeech', 'I guess we didn\'t train hard enough...'] => 'Wir haben wohl nicht hart genug trainiert...',
    ['John', 'SWIMMERBOI', 'introSpeech', 'Wait, a battle?'] => 'Moment, ein Kampf?',
    ['John', 'SWIMMERBOI', 'winSpeech', 'Hey, I won!'] => 'Hey, ich hab gewonnen!',
    ['John', 'SWIMMERBOI', 'loseSpeech', 'I thought this was the water park!'] => 'Ich dachte, das hier wäre der Wasserpark!',
    ['Colette', 'SWIMMERGRIL', 'introSpeech', 'Isn\'t it fun, battling like this?'] => 'Macht Kämpfen nicht Spaß?',
    ['Colette', 'SWIMMERGRIL', 'winSpeech', 'Win or lose, battles are fun... But especially when I win!'] => 'Ob Sieg oder Niederlage, Kämpfe machen Spaß... aber besonders, wenn ich gewinne!',
    ['Colette', 'SWIMMERGRIL', 'loseSpeech', 'M-My Pokemon will bite you!'] => 'M-meine Pokémon beißen dich!',
    ['Bellona', 'Punk', 'introSpeech', 'I\'m warning you, I won\'t lose!'] => 'Ich warne dich: Ich verliere nicht!',
    ['Bellona', 'Punk', 'winSpeech', 'This is paradise!'] => 'Das ist das Paradies!',
    ['Bellona', 'Punk', 'loseSpeech', 'You\'re so toxic!'] => 'Du bist ja so toxisch!',
    ['Cara', 'SWIMMERGRIL', 'introSpeech', 'Let\'s relax with a nice battle.'] => 'Lass uns bei einem netten Kampf entspannen.',
    ['Cara', 'SWIMMERGRIL', 'winSpeech', 'Wasn\'t that relaxing? '] => 'War doch entspannend, oder? ',
    ['Cara', 'SWIMMERGRIL', 'loseSpeech', 'Hey, you splashed me!'] => 'Hey, du hast mich nass gespritzt!',
    ['Gregory', 'EXPERT_Male', 'introSpeech', 'What makes you think you\'re so special?'] => 'Was lässt dich glauben, du wärst so besonders?',
    ['Gregory', 'EXPERT_Male', 'winSpeech', 'If you think you\'re special, you\'d better be prepared to back it up!'] => 'Wenn du glaubst, etwas Besonderes zu sein, musst du es auch beweisen können!',
    ['Gregory', 'EXPERT_Male', 'loseSpeech', 'I see.'] => 'Verstehe.',
    ['Ayden', 'SWIMMERBOI', 'introSpeech', 'Let\'s have a Water Gun fight!'] => 'Lass uns eine Aquaknarre-Schlacht machen!',
    ['Ayden', 'SWIMMERBOI', 'winSpeech', 'Gotcha!'] => 'Erwischt!',
    ['Ayden', 'SWIMMERBOI', 'loseSpeech', 'Aah! That water was too cold!'] => 'Aah! Das Wasser war viel zu kalt!',
    ['Marco', 'SWIMMERBOI', 'introSpeech', 'I love surfing!'] => 'Ich liebe Surfen!',
    ['Marco', 'SWIMMERBOI', 'winSpeech', 'You wiped out!'] => 'Du bist voll abgetaucht!',
    ['Marco', 'SWIMMERBOI', 'loseSpeech', 'I\'ll beat up my surfboard!'] => 'Ich verprügle gleich mein Surfbrett!',
    ['Cierra', 'SWIMMERGRIL', 'introSpeech', 'My Pokemon and I are perfectly synchronized!'] => 'Meine Pokémon und ich sind perfekt aufeinander eingespielt!',
    ['Cierra', 'SWIMMERGRIL', 'winSpeech', 'A flawless performance!'] => 'Eine makellose Vorstellung!',
    ['Cierra', 'SWIMMERGRIL', 'loseSpeech', 'I messed up...'] => 'Das hab ich vermasselt...',
    ['Marcy', 'SWIMMERGRIL', 'introSpeech', 'Don\'t get caught in the undertow!'] => 'Lass dich nicht von der Strömung mitreißen!',
    ['Marcy', 'SWIMMERGRIL', 'winSpeech', 'You need to study the seas more!'] => 'Du solltest dich mehr mit dem Meer beschäftigen!',
    ['Marcy', 'SWIMMERGRIL', 'loseSpeech', 'I got swept away!'] => 'Mich hat\'s mitgerissen!',
    ['Kathy', 'SWIMMERGRIL', 'introSpeech', 'I\'ve won every match I\'ve been in today!'] => 'Ich hab heute jeden Kampf gewonnen!',
    ['Kathy', 'SWIMMERGRIL', 'winSpeech', 'Another victory for me!'] => 'Schon wieder ein Sieg für mich!',
    ['Kathy', 'SWIMMERGRIL', 'loseSpeech', 'My first loss of the day...'] => 'Meine erste Niederlage heute...',
    ['Peyton', 'Cultist', 'introSpeech', 'Meet my wonderful Pokemon!'] => 'Lern meine wundervollen Pokémon kennen!',
    ['Peyton', 'Cultist', 'winSpeech', 'Aren\'t they amazing?'] => 'Sind sie nicht fantastisch?',
    ['Peyton', 'Cultist', 'loseSpeech', 'My Pokemon are still the light of my life!'] => 'Meine Pokémon sind trotzdem mein Ein und Alles!',
    ['Julian', 'Cultist', 'introSpeech', 'Are you a rising star, or will you crash and burn?'] => 'Bist du ein aufgehender Stern oder wirst du abstürzen und verbrennen?',
    ['Julian', 'Cultist', 'winSpeech', 'This was the battle of my dreams!'] => 'Das war der Kampf meiner Träume!',
    ['Julian', 'Cultist', 'loseSpeech', 'You\'re one of a kind!'] => 'Du bist wirklich einzigartig!',
    ['Georg', 'Cultist', 'introSpeech', 'My Pokemon and I are the dream team!'] => 'Meine Pokémon und ich sind das Dreamteam!',
    ['Georg', 'Cultist', 'winSpeech', 'We made our dreams real!'] => 'Wir haben unsere Träume wahr gemacht!',
    ['Georg', 'Cultist', 'loseSpeech', 'This is a terrible nightmare!'] => 'Das ist ein furchtbarer Albtraum!',
    ['Haylee', 'Punk', 'introSpeech', 'I don\'t know how to feel about this...'] => 'Ich weiß nicht, was ich davon halten soll...',
    ['Haylee', 'Punk', 'winSpeech', 'This! This feels wonderful!'] => 'Das! Das fühlt sich wunderbar an!',
    ['Haylee', 'Punk', 'loseSpeech', 'Terrible. I feel terrible.'] => 'Furchtbar. Ich fühle mich furchtbar.',
    ['Amanda', 'POACHERF', 'introSpeech', 'Hah, you don\'t stand a chance.'] => 'Ha, du hast keine Chance.',
    ['Amanda', 'POACHERF', 'winSpeech', 'Crushed it.'] => 'Absolut vernichtend.',
    ['Amanda', 'POACHERF', 'loseSpeech', 'This was a bad idea anyway.'] => 'Das war sowieso eine schlechte Idee.',
    ['Stacy', 'AceTrainerF', 'introSpeech', 'Every Pokemon is precious!'] => 'Jedes Pokémon ist kostbar!',
    ['Stacy', 'AceTrainerF', 'winSpeech', 'Look how much fun they all had!'] => 'Sieh nur, wie viel Spaß sie alle hatten!',
    ['Stacy', 'AceTrainerF', 'loseSpeech', 'Oh, your Pokemon are so adorable!'] => 'Oh, deine Pokémon sind so niedlich!',
    ['Rafael', 'Clown', 'introSpeech', 'I just graduated from Clown College, you know!'] => 'Ich hab gerade mein Clown-College abgeschlossen, weißt du!',
    ['Rafael', 'Clown', 'winSpeech', 'Did I do well?'] => 'War ich gut?',
    ['Rafael', 'Clown', 'loseSpeech', 'My nose itches...'] => 'Meine Nase juckt...',
    ['Oliver', 'Clown', 'introSpeech', 'I\'m an artistic genius!'] => 'Ich bin ein künstlerisches Genie!',
    ['Oliver', 'Clown', 'winSpeech', 'Behold, my vision!'] => 'Betrachte meine Vision!',
    ['Oliver', 'Clown', 'loseSpeech', 'You\'re the true artist!'] => 'Du verstehst wirklich was von Kunst!',
    ['Park', 'Clown', 'introSpeech', 'Prepare to be entertained!'] => 'Mach dich auf Unterhaltung gefasst!',
    ['Park', 'Clown', 'winSpeech', 'Wasn\'t that amazing?'] => 'War das nicht unglaublich?',
    ['Park', 'Clown', 'loseSpeech', 'Hey! You\'re not supposed to laugh now!'] => 'Hey! Jetzt sollst du doch nicht lachen!',
    ['Pamela', 'Doxy', 'introSpeech', 'Pokemon love kind Trainers.'] => 'Pokémon lieben freundliche Trainer.',
    ['Pamela', 'Doxy', 'winSpeech', 'My Pokemon know I love them, and that\'s why they\'re so strong!'] => 'Meine Pokémon wissen, dass ich sie lieb habe, und deshalb sind sie so stark!',
    ['Pamela', 'Doxy', 'loseSpeech', 'You seem strong as well as kind!'] => 'Du wirkst stark und freundlich!',
    ['Eliza', 'Doxy', 'introSpeech', 'Let the dance begin!'] => 'Der Tanz kann beginnen!',
    ['Eliza', 'Doxy', 'winSpeech', 'I could have kept battling all day!'] => 'Ich hätte den ganzen Tag weiterkämpfen können!',
    ['Eliza', 'Doxy', 'loseSpeech', 'I could do little to stop you!'] => 'Ich konnte kaum etwas gegen dich ausrichten!',
    ['Marisa', 'Doxy', 'introSpeech', 'Let us both truly give our all!'] => 'Geben wir beide wirklich alles!',
    ['Marisa', 'Doxy', 'winSpeech', 'You must try harder next time!'] => 'Nächstes Mal musst du dich mehr anstrengen!',
    ['Marisa', 'Doxy', 'loseSpeech', 'We must battle agan sometime!'] => 'Wir müssen unbedingt mal wieder kämpfen!',
    ['Lewis', 'StreetRat', 'introSpeech', 'Look! Bugs!'] => 'Schau mal! Käfer!',
    ['Lewis', 'StreetRat', 'winSpeech', 'Bugs are only scary if they\'re your opponents!'] => 'Käfer sind nur gruselig, wenn sie deine Gegner sind!',
    ['Lewis', 'StreetRat', 'loseSpeech', 'I guess bugs don\'t scare you...'] => 'Käfer machen dir wohl keine Angst...',
    ['Yarrow', 'StreetRat', 'introSpeech', 'I try and learn a lesson from every battle!'] => 'Ich versuche, aus jedem Kampf etwas zu lernen!',
    ['Yarrow', 'StreetRat', 'winSpeech', 'Today I learned I\'m stronger than you!'] => 'Heute hab ich gelernt, dass ich stärker bin als du!',
    ['Yarrow', 'StreetRat', 'loseSpeech', 'I think I learned something!'] => 'Ich glaube, ich hab was gelernt!',
    ['Destin', 'StreetRat', 'introSpeech', 'Why is it so hot in here?'] => 'Warum ist es hier so heiß?',
    ['Destin', 'StreetRat', 'winSpeech', 'The heat drove me to victory!'] => 'Die Hitze hat mich zum Sieg getrieben!',
    ['Destin', 'StreetRat', 'loseSpeech', 'Anyone have any water?'] => 'Hat jemand Wasser?',
    ['Keon', 'BLACKBELT', 'introSpeech', 'Prepare for the battle of the century!'] => 'Mach dich bereit für den Kampf des Jahrhunderts!',
    ['Keon', 'BLACKBELT', 'winSpeech', 'This is a victory I won\'t soon forget!'] => 'Diesen Sieg werde ich so schnell nicht vergessen!',
    ['Keon', 'BLACKBELT', 'loseSpeech', 'Well, that\'s a loss to remember...'] => 'Na, das ist mal eine Niederlage, an die man sich erinnert...',
    ['Stuart', 'BLACKBELT', 'introSpeech', 'Come on, let\'s spar a little!'] => 'Komm schon, lass uns ein bisschen trainieren!',
    ['Stuart', 'BLACKBELT', 'winSpeech', 'Beating me was a tall order, and you couldn\'t measure up!'] => 'Mich zu besiegen war eine große Aufgabe, und du bist ihr nicht gewachsen!',
    ['Stuart', 'BLACKBELT', 'loseSpeech', 'Your fighting spirit is no small thing!'] => 'Dein Kampfgeist ist nicht zu unterschätzen!',
    ['Nestor', 'BLACKBELT', 'introSpeech', 'In battling, as in all things, discipline is important. '] => 'Beim Kämpfen ist Disziplin wichtig, wie in allen Dingen. ',
    ['Nestor', 'BLACKBELT', 'winSpeech', 'You and your Pokemon must work on control.'] => 'Du und deine Pokémon müsst an eurer Kontrolle arbeiten.',
    ['Nestor', 'BLACKBELT', 'loseSpeech', 'Excellent.'] => 'Ausgezeichnet.',
    ['Derrick', 'StreetRat', 'introSpeech', 'I\'ve just finished my daily meditation. Care for a battle?'] => 'Ich bin gerade mit meiner täglichen Meditation fertig. Lust auf einen Kampf?',
    ['Derrick', 'StreetRat', 'winSpeech', 'I guess my win was pre-meditated!'] => 'Mein Sieg war wohl vor-meditiert!',
    ['Derrick', 'StreetRat', 'loseSpeech', 'Looks like I may need to meditate some more.'] => 'Sieht aus, als müsste ich noch etwas mehr meditieren.',
    ['Bryson', 'StreetRat', 'introSpeech', 'Okay. I can do this.'] => 'Okay. Ich schaff das.',
    ['Bryson', 'StreetRat', 'winSpeech', '...I did it! '] => '...Ich hab\'s geschafft! ',
    ['Bryson', 'StreetRat', 'loseSpeech', 'Well, it was kinda fun anyway!'] => 'Na ja, irgendwie hat\'s trotzdem Spaß gemacht!',
    ['Clayton', 'StreetRat', 'introSpeech', 'I\'ve been hunting for a good opponent for weeks now!'] => 'Seit Wochen suche ich nach einem guten Gegner!',
    ['Clayton', 'StreetRat', 'winSpeech', 'You put up a good fight. I appreciate it.'] => 'Du hast gut gekämpft. Das weiß ich zu schätzen.',
    ['Clayton', 'StreetRat', 'loseSpeech', 'Hey, that was great!'] => 'Hey, das war großartig!',
    ['Trenton', 'FISHERMAN', 'introSpeech', 'I\'d rather be fishing...'] => 'Ich wär lieber angeln...',
    ['Trenton', 'FISHERMAN', 'winSpeech', 'I guess a break now and then is a good thing!'] => 'Eine Pause ab und zu tut wohl ganz gut!',
    ['Trenton', 'FISHERMAN', 'loseSpeech', 'I shouldn\'t have taken time out.'] => 'Ich hätte mir keine Auszeit nehmen sollen.',
    ['Jenson', 'FISHERMAN', 'introSpeech', 'My Pokemon will show you a true challenge!'] => 'Meine Pokémon werden dir eine echte Herausforderung zeigen!',
    ['Jenson', 'FISHERMAN', 'winSpeech', 'You flopped!'] => 'Du bist abgesoffen!',
    ['Jenson', 'FISHERMAN', 'loseSpeech', 'You rose to the challenge!'] => 'Du bist der Herausforderung gewachsen!',
    ['Westley', 'FISHERMAN', 'introSpeech', 'You seem a decent Trainer. I hate to destroy you.'] => 'Du scheinst ein anständiger Trainer zu sein. Ich hasse es, dich zu vernichten.',
    ['Westley', 'FISHERMAN', 'winSpeech', 'You Emboar-faced buffoon!'] => 'Du Flambirex-gesichtiger Trottel!',
    ['Westley', 'FISHERMAN', 'loseSpeech', 'You are a decent Trainer! I still hate to lose. '] => 'Du bist ein anständiger Trainer! Verlieren tu ich trotzdem ungern. ',
    ['Franka', 'KNIGHT', 'introSpeech', 'Have you heard of me?'] => 'Hast du schon von mir gehört?',
    ['Franka', 'KNIGHT', 'winSpeech', 'It is I, the great knight Franka!'] => 'Ich bin\'s, die große Ritterin Franka!',
    ['Franka', 'KNIGHT', 'loseSpeech', 'I\'m the great knight Franka! How could I lose?'] => 'Ich bin die große Ritterin Franka! Wie konnte ich verlieren?',
    ['Lawson', 'KNIGHT', 'introSpeech', 'It\'s my duty to defeat you!'] => 'Es ist meine Pflicht, dich zu besiegen!',
    ['Lawson', 'KNIGHT', 'winSpeech', 'I\'ll fulfill my duty no matter what!'] => 'Ich erfülle meine Pflicht, koste es, was es wolle!',
    ['Lawson', 'KNIGHT', 'loseSpeech', 'Actually, I\'m not sure battling is part of my duties...'] => 'Eigentlich bin ich mir nicht sicher, ob Kämpfen zu meinen Pflichten gehört...',
    ['Sammy', 'KNIGHT', 'introSpeech', 'My party is ready to roll!'] => 'Meine Truppe ist bereit loszulegen!',
    ['Sammy', 'KNIGHT', 'winSpeech', 'Your party is pretty rockin\' too!'] => 'Deine Truppe rockt auch ganz schön!',
    ['Sammy', 'KNIGHT', 'loseSpeech', 'That battle was rockin\'!'] => 'Der Kampf hat gerockt!',
    ['Arnie', 'MAGMA1', 'introSpeech', 'No one in the Magma Gang\'s ever been able to defeat me!'] => 'In der Magma-Bande konnte mich noch nie jemand besiegen!',
    ['Arnie', 'MAGMA1', 'winSpeech', 'No one outside can defeat me either, it seems!'] => 'Anscheinend kann mich auch außerhalb niemand besiegen!',
    ['Arnie', 'MAGMA1', 'loseSpeech', 'Hey, you should think about joining up sometime.'] => 'Hey, du solltest vielleicht mal bei uns mitmachen.',
    ['Adrian', 'MAGMA1', 'introSpeech', 'Hey, you! Battle me!'] => 'Hey, du! Kämpf gegen mich!',
    ['Adrian', 'MAGMA1', 'winSpeech', 'Heh heh. '] => 'Hehe. ',
    ['Adrian', 'MAGMA1', 'loseSpeech', 'You weren\'t supposed to win!'] => 'Du solltest doch gar nicht gewinnen!',
    ['Chxxo', 'MAGMA1', 'introSpeech', 'I am a single melancholy flame...'] => 'Ich bin eine einzelne, melancholische Flamme...',
    ['Chxxo', 'MAGMA1', 'winSpeech', 'My sorrow blazes as hot as the sun!'] => 'Mein Kummer lodert so heiß wie die Sonne!',
    ['Chxxo', 'MAGMA1', 'loseSpeech', 'I burned out!'] => 'Ich bin ausgebrannt!',
    ['Juliana', 'LADY', 'introSpeech', 'Aren\'t these shoes adorable?'] => 'Sind diese Schuhe nicht süß?',
    ['Juliana', 'LADY', 'winSpeech', 'Eeee! I\'ve got to buy a matching bag to celebrate my victory!'] => 'Juhuuu! Ich muss mir zur Feier meines Siegs noch eine passende Tasche kaufen!',
    ['Juliana', 'LADY', 'loseSpeech', 'I guess I\'ll go shopping some more to cheer myself up after that loss!'] => 'Ich geh wohl noch ein bisschen shoppen, um mich von der Niederlage aufzumuntern!',
    ['Rylie', 'LADY', 'introSpeech', 'This establishment has no class!'] => 'Dieses Etablissement hat keinen Stil!',
    ['Rylie', 'LADY', 'winSpeech', 'Perhaps I can lend some class to this place.'] => 'Vielleicht kann ich diesem Ort etwas Stil verleihen.',
    ['Rylie', 'LADY', 'loseSpeech', 'You no-good Rattata!'] => 'Du nichtsnutziges Rattfratz!',
    ['Chelsea', 'LADY', 'introSpeech', 'Show me your passion for this role!'] => 'Zeig mir, wie viel Leidenschaft du für diese Rolle hast!',
    ['Chelsea', 'LADY', 'winSpeech', 'I owned the stage, as always!'] => 'Wie immer gehörte die Bühne mir!',
    ['Chelsea', 'LADY', 'loseSpeech', 'You were dazzling, darling!'] => 'Du warst umwerfend, Liebling!',
    ['Danela', 'BEAUTY', 'introSpeech', 'Haven\'t I seen you somewhere before? '] => 'Sind wir uns nicht schon mal irgendwo begegnet? ',
    ['Danela', 'BEAUTY', 'winSpeech', 'I must\'ve been mistaken.'] => 'Ich muss mich wohl geirrt haben.',
    ['Danela', 'BEAUTY', 'loseSpeech', 'Your battling style is familiar, too!'] => 'Dein Kampfstil kommt mir auch bekannt vor!',
    ['Lizbeth', 'BEAUTY', 'introSpeech', 'Would you like to hear a secret?'] => 'Möchtest du ein Geheimnis hören?',
    ['Lizbeth', 'BEAUTY', 'winSpeech', 'Well, now you\'ll never know!'] => 'Na ja, jetzt wirst du es nie erfahren!',
    ['Lizbeth', 'BEAUTY', 'loseSpeech', 'The secret is: I\'m really just an amateur battler.'] => 'Das Geheimnis ist: Ich bin eigentlich nur eine Hobbykämpferin.',
    ['Amelia', 'BEAUTY', 'introSpeech', 'I\'m a Coordinator in my spare time. Show me your Pokemon\'s appeal!'] => 'In meiner Freizeit bin ich Koordinatorin. Zeig mir die Ausstrahlung deiner Pokémon!',
    ['Amelia', 'BEAUTY', 'winSpeech', 'Hmm, it looks like your style needs work.'] => 'Hm, an deinem Stil musst du wohl noch arbeiten.',
    ['Amelia', 'BEAUTY', 'loseSpeech', 'So impressive! You\'ve got my support for sure!'] => 'So beeindruckend! Du hast auf jeden Fall meine Unterstützung!',
    ['Jillian', 'NatureGirl', 'introSpeech', 'My brother couldn\'t beat me- can you?'] => 'Mein Bruder konnte mich nicht besiegen—schaffst du\'s?',
    ['Jillian', 'NatureGirl', 'winSpeech', 'Nope, I\'m still the strongest!'] => 'Nö, ich bin immer noch die Stärkste!',
    ['Jillian', 'NatureGirl', 'loseSpeech', 'Well, I hope you beat him, too.'] => 'Na ja, ich hoffe, du besiegst ihn auch.',
    ['Abbie', 'NatureGirl', 'introSpeech', 'What is that strange smell?'] => 'Was ist das für ein seltsamer Geruch?',
    ['Abbie', 'NatureGirl', 'winSpeech', 'That smell- it\'s you! It must be!'] => 'Der Geruch—du bist es! Das muss es sein!',
    ['Abbie', 'NatureGirl', 'loseSpeech', 'Oh. Maybe it\'s me.'] => 'Oh. Vielleicht bin ich es.',
    ['Natalia', 'NatureGirl', 'introSpeech', 'Sometimes I wish I were a princess...'] => 'Manchmal wünschte ich, ich wäre eine Prinzessin...',
    ['Natalia', 'NatureGirl', 'winSpeech', 'Perhaps I\'m no princess, but I\'m still plenty strong!'] => 'Vielleicht bin ich keine Prinzessin, aber stark bin ich trotzdem!',
    ['Natalia', 'NatureGirl', 'loseSpeech', 'I\'d be a very strange, enchanted girl!'] => 'Ich wäre ein ziemlich seltsames, verzaubertes Mädchen!',
    ['Antonio', 'GUITARIST', 'introSpeech', 'Let me play you this song I wrote!'] => 'Lass mich dir das Lied vorspielen, das ich geschrieben habe!',
    ['Antonio', 'GUITARIST', 'winSpeech', 'Wasn\'t it pretty?'] => 'War es nicht hübsch?',
    ['Antonio', 'GUITARIST', 'loseSpeech', 'I hope you\'ll remember me!'] => 'Ich hoffe, du wirst dich an mich erinnern!',
    ['Jaden', 'GUITARIST', 'introSpeech', 'Hello, I love you!'] => 'Hallo, ich liebe dich!',
    ['Jaden', 'GUITARIST', 'winSpeech', 'You hold your head so high!'] => 'Du trägst deinen Kopf ganz schön hoch!',
    ['Jaden', 'GUITARIST', 'loseSpeech', 'Won\'t you tell me your name?'] => 'Verrätst du mir deinen Namen?',
    ['Dakota', 'GUITARIST', 'introSpeech', 'Hey, have you heard Hardy play? I\'m a big fan!'] => 'Hey, hast du Hardy schon spielen hören? Ich bin ein Riesenfan!',
    ['Dakota', 'GUITARIST', 'winSpeech', 'You battled him? Do you think you could get me an autograph?'] => 'Du hast gegen ihn gekämpft? Kannst du mir ein Autogramm besorgen?',
    ['Dakota', 'GUITARIST', 'loseSpeech', 'He\'s just so cool!'] => 'Er ist einfach so cool!',
    ['Brayden', 'Casanova', 'introSpeech', 'It\'s such a fine day, don\'t you think?'] => 'Was für ein schöner Tag, findest du nicht?',
    ['Brayden', 'Casanova', 'winSpeech', 'The sun is positively radiant!'] => 'Die Sonne strahlt geradezu prächtig!',
    ['Brayden', 'Casanova', 'loseSpeech', 'Even a loss can\'t sour this weather!'] => 'Nicht mal eine Niederlage kann mir dieses Wetter vermiesen!',
    ['Corson', 'Casanova', 'introSpeech', 'Heh heh. This is gonna be fun.'] => 'Hehe. Das wird lustig.',
    ['Corson', 'Casanova', 'winSpeech', 'Too easy!'] => 'Zu einfach!',
    ['Corson', 'Casanova', 'loseSpeech', 'That wasn\'t fun at all!'] => 'Das hat überhaupt keinen Spaß gemacht!',
    ['TJ', 'Casanova', 'introSpeech', 'Well, hello there, gorgeous!'] => 'Na, hallo, du hübsches Ding!',
    ['TJ', 'Casanova', 'winSpeech', 'Ah, I love my pocket mirror!'] => 'Ah, ich liebe meinen Taschenspiegel!',
    ['TJ', 'Casanova', 'loseSpeech', 'My mirror! You scuffed it!'] => 'Mein Spiegel! Du hast ihn zerkratzt!',
    ['Rossi', 'AQUA1', 'introSpeech', 'Water you looking at?'] => 'Wasserst du mich denn so an?',
    ['Rossi', 'AQUA1', 'winSpeech', 'I hope someone\'s streaming this win!'] => 'Hoffentlich streamt jemand diesen Sieg!',
    ['Rossi', 'AQUA1', 'loseSpeech', 'C\'mon, you could have at least laughed!'] => 'Komm schon, du hättest wenigstens lachen können!',
    ['Kaden', 'AQUA1', 'introSpeech', 'Don\'t think ya can fool me!'] => 'Denk bloß nicht, du kannst mich reinlegen!',
    ['Kaden', 'AQUA1', 'winSpeech', 'I know what yer up to!'] => 'Ich weiß genau, was du vorhast!',
    ['Kaden', 'AQUA1', 'loseSpeech', 'I still don\'t trust ya!'] => 'Ich trau dir immer noch nicht!',
    ['Maxwell', 'AQUA1', 'introSpeech', 'Do I look intimidating? Be honest.'] => 'Seh ich einschüchternd aus? Ehrlich jetzt.',
    ['Maxwell', 'AQUA1', 'winSpeech', 'There\'s no way that other Maxwell is stronger than me.'] => 'Der andere Maxwell ist unmöglich stärker als ich.',
    ['Maxwell', 'AQUA1', 'loseSpeech', 'I wish people would stop mistaking me for that jerk in the Magma Gang!'] => 'Ich wünschte, die Leute würden mich nicht ständig mit diesem Idioten von der Magma-Bande verwechseln!',
    ['Daryl', 'HIKER', 'introSpeech', 'My intuition\'s telling me you\'re pretty strong!'] => 'Mein Bauchgefühl sagt, dass du ziemlich stark bist!',
    ['Daryl', 'HIKER', 'winSpeech', 'I\'m really smokin\'!'] => 'Ich bin richtig heiß unterwegs!',
    ['Daryl', 'HIKER', 'loseSpeech', 'You\'ve gone too far!'] => 'Jetzt gehst du zu weit!',
    ['Kenneth', 'HIKER', 'introSpeech', 'Battling\'s just another kind of mountain to climb!'] => 'Kämpfen ist auch nur ein weiterer Berg, den man erklimmen muss!',
    ['Kenneth', 'HIKER', 'winSpeech', 'I\'m still a long way from the peak, but I\'ll make it!'] => 'Bis zum Gipfel ist es noch weit, aber ich schaff das!',
    ['Kenneth', 'HIKER', 'loseSpeech', 'The view from here\'s pretty good, though.'] => 'Die Aussicht von hier ist aber ziemlich gut.',
    ['Skrubb', 'HIKER', 'introSpeech', 'Hey- are you okay?'] => 'Hey—alles okay bei dir?',
    ['Skrubb', 'HIKER', 'winSpeech', 'Seriously though, are you okay?'] => 'Mal im Ernst, geht\'s dir gut?',
    ['Skrubb', 'HIKER', 'loseSpeech', 'Now I\'m not okay...'] => 'Jetzt geht\'s mir nicht gut...',
    ['Caden', 'TechNerd', 'introSpeech', 'Are you expecting an effortless victory? '] => 'Erwartest du einen mühelosen Sieg? ',
    ['Caden', 'TechNerd', 'winSpeech', 'Overconfidence is never advised. '] => 'Selbstüberschätzung ist nie ratsam. ',
    ['Caden', 'TechNerd', 'loseSpeech', 'I suppose your expectation was well-founded...'] => 'Deine Erwartung war wohl begründet...',
    ['Veno', 'TechNerd', 'introSpeech', 'Statistically speaking, battling here is safer than 82.6% of places.'] => 'Statistisch gesehen ist ein Kampf hier sicherer als an 82,6 % aller Orte.',
    ['Veno', 'TechNerd', 'winSpeech', 'Safer and more fun!'] => 'Sicherer und macht mehr Spaß!',
    ['Veno', 'TechNerd', 'loseSpeech', 'Make sure you stay out of the mines!'] => 'Bleib den Minen unbedingt fern!',
    ['Nash', 'TechNerd', 'introSpeech', 'Hey, check out my new Pokenav! It\'s the latest model!'] => 'Hey, schau dir meinen neuen PokéNav an! Das neueste Modell!',
    ['Nash', 'TechNerd', 'winSpeech', 'Superior tech and superior skills!'] => 'Überlegene Technik und überlegene Fähigkeiten!',
    ['Nash', 'TechNerd', 'loseSpeech', 'M-my hard drive! It crashed!'] => 'M-meine Festplatte! Sie ist abgestürzt!',
    ['Ulysses', 'POACHERM', 'introSpeech', 'No excuses! Prepare for battle!'] => 'Keine Ausreden! Mach dich bereit zum Kampf!',
    ['Ulysses', 'POACHERM', 'winSpeech', 'Cake.'] => 'Kinderleicht.',
    ['Ulysses', 'POACHERM', 'loseSpeech', 'I\'ve still got a lot to learn.'] => 'Ich muss noch eine Menge lernen.',
    ['Nik', 'AceTrainerM', 'introSpeech', 'I\'m faster than you\'d believe!'] => 'Ich bin schneller, als du glaubst!',
    ['Nik', 'AceTrainerM', 'winSpeech', 'Told you I was fast!'] => 'Hab ich doch gesagt, dass ich schnell bin!',
    ['Nik', 'AceTrainerM', 'loseSpeech', 'You\'re still faster? How can that be...?'] => 'Du bist immer noch schneller? Wie kann das sein...?',
    ['Lua', 'Punk', 'introSpeech', 'What\'s that look for?'] => 'Was glotzt du so?',
    ['Lua', 'Punk', 'winSpeech', 'You\'re not lookin\' so hot now!'] => 'Jetzt siehst du nicht mehr ganz so flott aus!',
    ['Lua', 'Punk', 'loseSpeech', 'Gloating\'s not cool, y\'know!'] => 'Angeben ist uncool, weißt du!',
    ['Ellen', 'AceTrainerF', 'introSpeech', 'Now, watch carefully.'] => 'Jetzt pass gut auf.',
    ['Ellen', 'AceTrainerF', 'winSpeech', 'Now, did you learn anything?'] => 'Na, hast du was gelernt?',
    ['Ellen', 'AceTrainerF', 'loseSpeech', 'W-what? That was fast!'] => 'W-was? Das ging schnell!',
    ['Ramon', 'POACHERM', 'introSpeech', 'Oh, hey! Long time no see!'] => 'Oh, hey! Lange nicht gesehen!',
    ['Ramon', 'POACHERM', 'winSpeech', 'I stole that victory!'] => 'Den Sieg hab ich mir geschnappt!',
    ['Ramon', 'POACHERM', 'loseSpeech', 'Strong as ever, I see...'] => 'Immer noch so stark, wie ich sehe...',
    ['Aaron', 'AceTrainerM', 'introSpeech', 'Here it is, my one big shot!'] => 'Jetzt ist meine große Chance!',
    ['Aaron', 'AceTrainerM', 'winSpeech', 'They\'re not gonna laugh anymore!'] => 'Jetzt lachen sie nicht mehr über mich!',
    ['Aaron', 'AceTrainerM', 'loseSpeech', 'You saw right through me...'] => 'Du hast mich durchschaut...',
    ['Alondra', 'POACHERF', 'introSpeech', 'My sister bet me I couldn\'t win ten battles here... I\'ve already won nine!'] => 'Meine Schwester hat gewettet, dass ich hier keine zehn Kämpfe gewinne... Neun hab ich schon geschafft!',
    ['Alondra', 'POACHERF', 'winSpeech', 'Ha! Now she owes me bigtime!'] => 'Ha! Jetzt schuldet sie mir ganz schön was!',
    ['Alondra', 'POACHERF', 'loseSpeech', 'My sister\'s such a jerk...'] => 'Meine Schwester ist so ein Miststück...',
    ['Adriana', 'POACHERF', 'introSpeech', 'Give it your all!'] => 'Gib alles!',
    ['Adriana', 'POACHERF', 'winSpeech', 'You\'ve got to try harder next time!'] => 'Nächstes Mal musst du dich mehr anstrengen!',
    ['Adriana', 'POACHERF', 'loseSpeech', 'I bet my sister she\'d lose here, so beat her too, okay?'] => 'Ich hab gewettet, dass meine Schwester hier verliert. Besieg sie auch, ja?',
    ['Malik', 'POACHERM', 'introSpeech', 'You\'re not with Interpol, are you?'] => 'Du bist doch nicht von Interpol, oder?',
    ['Malik', 'POACHERM', 'winSpeech', 'Gotta keep on top of my game...'] => 'Ich muss weiter am Ball bleiben...',
    ['Malik', 'POACHERM', 'loseSpeech', 'Don\'t ask me why.'] => 'Frag mich nicht, warum.',
    ['Jill', 'POACHERF', 'introSpeech', 'Oh, I love your hair!'] => 'Oh, ich liebe deine Frisur!',
    ['Jill', 'POACHERF', 'winSpeech', 'Can you tell me where you had it done?'] => 'Verrätst du mir, wo du sie machen lässt?',
    ['Jill', 'POACHERF', 'loseSpeech', 'You battle well, too!'] => 'Kämpfen kannst du auch gut!',
    ['Erik', 'AceTrainerM', 'introSpeech', 'I prefer battling at night...'] => 'Ich kämpfe lieber nachts...',
    ['Erik', 'AceTrainerM', 'winSpeech', 'The darkness calms me. '] => 'Die Dunkelheit beruhigt mich. ',
    ['Erik', 'AceTrainerM', 'loseSpeech', 'The light of day throws off my focus!'] => 'Das Tageslicht bringt mich aus der Konzentration!',
    ['Yazmin', 'AceTrainerF', 'introSpeech', 'There\'s not much I like more than a good battle!'] => 'Es gibt kaum etwas, das ich lieber mag als einen guten Kampf!',
    ['Yazmin', 'AceTrainerF', 'winSpeech', 'If there\'s anything I like more, it\'s a good victory!'] => 'Wenn ich etwas noch lieber mag, dann einen schönen Sieg!',
    ['Yazmin', 'AceTrainerF', 'loseSpeech', 'Battling\'s fun, but I\'d rather have cake.'] => 'Kämpfen macht Spaß, aber Kuchen wär mir lieber.',
    ['Jamal', 'SWIMMERBOI', 'introSpeech', 'I\'m training to be a lifeguard. Can I practice while we battle?'] => 'Ich trainiere als Rettungsschwimmerin. Kann ich während unseres Kampfes üben?',
    ['Jamal', 'SWIMMERBOI', 'winSpeech', 'My test\'s tomorrow!'] => 'Morgen ist meine Prüfung!',
    ['Jamal', 'SWIMMERBOI', 'loseSpeech', 'No running!'] => 'Nicht rennen!',
    ['Leslie', 'SWIMMERGRIL', 'introSpeech', 'Hmm. Do you think this would be a good place for a field trip?'] => 'Hm. Meinst du, das hier wäre ein guter Ort für einen Schulausflug?',
    ['Leslie', 'SWIMMERGRIL', 'winSpeech', 'I\'m looking for a good place to bring my students!'] => 'Ich suche einen guten Ort, an den ich meine Schüler bringen kann!',
    ['Leslie', 'SWIMMERGRIL', 'loseSpeech', 'Maybe the trainers are a bit too strong...'] => 'Vielleicht sind die Trainer ein bisschen zu stark...',
    ['Dave', 'MAGMA2', 'introSpeech', 'Say... you don\'t recognize me, right?'] => 'Sag mal... du erkennst mich doch nicht, oder?',
    ['Dave', 'MAGMA2', 'winSpeech', 'No idea who I am? Good.'] => 'Keine Ahnung, wer ich bin? Gut.',
    ['Dave', 'MAGMA2', 'loseSpeech', 'The truth is, I\'m undercover. Don\'t tell anyone! '] => 'Die Wahrheit ist: Ich bin undercover. Verrat\'s niemandem! ',
    ['Carlo', 'MAGMA2', 'introSpeech', 'I\'m so mad! I got fired this morning!'] => 'Ich bin so wütend! Heute Morgen wurde ich gefeuert!',
    ['Carlo', 'MAGMA2', 'winSpeech', 'Maybe I can make a new career as a battler...'] => 'Vielleicht kann ich mir als Kämpfer eine neue Karriere aufbauen...',
    ['Carlo', 'MAGMA2', 'loseSpeech', 'Fired, then defeated... Ugh!'] => 'Erst gefeuert, dann besiegt... Ugh!',
    ['Emilia', 'BATTLEGIRL', 'introSpeech', 'I\'m bored. Entertain me!'] => 'Mir ist langweilig. Unterhalt mich!',
    ['Emilia', 'BATTLEGIRL', 'winSpeech', 'You put up a good fight! '] => 'Du hast dich gut geschlagen! ',
    ['Emilia', 'BATTLEGIRL', 'loseSpeech', 'That was entertaining!'] => 'Das war unterhaltsam!',
    ['Dalia', 'BATTLEGIRL', 'introSpeech', 'Just be careful with my Pokemon. They\'re very precious!'] => 'Sei bitte vorsichtig mit meinen Pokémon. Sie sind mir sehr wichtig!',
    ['Dalia', 'BATTLEGIRL', 'winSpeech', 'They\'re both precious and strong!'] => 'Sie sind kostbar und stark zugleich!',
    ['Dalia', 'BATTLEGIRL', 'loseSpeech', 'Precious and fragile!'] => 'Kostbar und zerbrechlich!',
    ['Nate', 'BLACKBELT', 'introSpeech', 'I hope you will not be hurt when I crush you!'] => 'Ich hoffe, du nimmst es mir nicht übel, wenn ich dich fertig mache!',
    ['Nate', 'BLACKBELT', 'winSpeech', 'Deep breaths, now. '] => 'Tief durchatmen, ja. ',
    ['Nate', 'BLACKBELT', 'loseSpeech', 'Perhaps I spoke too soon.'] => 'Vielleicht war ich etwas voreilig.',
    ['Ricardo', 'BLACKBELT', 'introSpeech', 'Have you seen my wife? Her name\'s Lucy!'] => 'Hast du meine Frau gesehen? Sie heißt Lucy!',
    ['Ricardo', 'BLACKBELT', 'winSpeech', 'If you see her, tell her I\'m looking for her!'] => 'Wenn du sie siehst, sag ihr, dass ich sie suche!',
    ['Ricardo', 'BLACKBELT', 'loseSpeech', 'I\'ll just go find her, then...'] => 'Dann geh ich sie eben suchen...',
    ['Shizuka', 'BLACKBELT', 'introSpeech', 'There\'s something about you...'] => 'Da ist etwas an dir...',
    ['Shizuka', 'BLACKBELT', 'winSpeech', 'I will never forget you!'] => 'Ich werde dich nie vergessen!',
    ['Shizuka', 'BLACKBELT', 'loseSpeech', 'You\'re just so fascinating!'] => 'Du bist einfach so faszinierend!',
    ['Lucy', 'BATTLEGIRL', 'introSpeech', 'A quick victory, then I\'ll go home. '] => 'Ein schneller Sieg, dann geh ich nach Hause. ',
    ['Lucy', 'BATTLEGIRL', 'winSpeech', 'That was fun! '] => 'Das hat Spaß gemacht! ',
    ['Lucy', 'BATTLEGIRL', 'loseSpeech', 'Well, time to go find my husband...'] => 'Na gut, dann such ich mal meinen Mann...',
    ['Kelly', 'BATTLEGIRL', 'introSpeech', 'Ugh, so much homework...'] => 'Ugh, so viele Hausaufgaben...',
    ['Kelly', 'BATTLEGIRL', 'winSpeech', 'Back to studying!'] => 'Zurück ans Lernen!',
    ['Kelly', 'BATTLEGIRL', 'loseSpeech', 'I shouldn\'t have taken time out to battle.'] => 'Ich hätte mir keine Zeit fürs Kämpfen nehmen sollen.',
    ['Rayna', 'BATTLEGIRL', 'introSpeech', 'I\'m Victoria\'s biggest fan!'] => 'Ich bin Victorias größter Fan!',
    ['Rayna', 'BATTLEGIRL', 'winSpeech', 'Through trying to be like her, I have become strong!'] => 'Indem ich versucht habe, wie sie zu sein, bin ich selbst stark geworden!',
    ['Rayna', 'BATTLEGIRL', 'loseSpeech', 'I wonder if she\'d sign my uniform...'] => 'Ob sie wohl mein Outfit unterschreiben würde...',
    ['Pyrros', 'Orderly', 'introSpeech', 'Something smells around here.'] => 'Hier riecht\'s irgendwie komisch.',
    ['Pyrros', 'Orderly', 'winSpeech', 'I guess it was you! '] => 'Ich schätze, du warst es! ',
    ['Pyrros', 'Orderly', 'loseSpeech', 'I guess it was me...'] => 'Ich schätze, ich war\'s...',
    ['Kale', 'Orderly', 'introSpeech', 'Battling\'s good for your health!'] => 'Kämpfen ist gut für die Gesundheit!',
    ['Kale', 'Orderly', 'winSpeech', 'Victory\'s even better!'] => 'Ein Sieg ist noch besser!',
    ['Kale', 'Orderly', 'loseSpeech', 'Even losing helps you grow!'] => 'Auch eine Niederlage lässt dich wachsen!',
    ['Geoff', 'Orderly', 'introSpeech', 'Excuse me, which way to the men\'s room? This hotel is a bit confusing!'] => 'Entschuldigung, wo geht\'s hier zur Herrentoilette? Dieses Hotel ist etwas verwirrend!',
    ['Geoff', 'Orderly', 'winSpeech', 'What do you mean this isn\'t a hotel!?'] => 'Wie meinst du, das hier ist gar kein Hotel!?',
    ['Geoff', 'Orderly', 'loseSpeech', 'I\'ll just check down this hallway then!'] => 'Dann schau ich eben den Gang hier entlang!',
    ['Kristen', 'OrderlyF', 'introSpeech', 'I\'ll wipe the floor with you!'] => 'Ich wisch mit dir den Boden auf!',
    ['Kristen', 'OrderlyF', 'winSpeech', 'I always clean up here! Haha!'] => 'Hier räum ich immer ab! Haha!',
    ['Kristen', 'OrderlyF', 'loseSpeech', 'I guess I\'m a scrub...'] => 'Ich bin wohl echt ein Anfänger...',
    ['Selphy', 'OrderlyF', 'introSpeech', 'Can we battle quietly? I\'m waiting for a phone call.'] => 'Können wir leise kämpfen? Ich warte auf einen Anruf.',
    ['Selphy', 'OrderlyF', 'winSpeech', 'Hello? Oh, hi, thanks for calling...'] => 'Hallo? Oh, hi, danke für deinen Anruf...',
    ['Selphy', 'OrderlyF', 'loseSpeech', 'That wasn\'t very quiet! I hope I didn\'t miss it.'] => 'Das war nicht gerade leise! Hoffentlich hab ich den Anruf nicht verpasst.',
    ['Chloe', 'OrderlyF', 'introSpeech', 'Battle mode: engaged.'] => 'Kampfmodus: aktiviert.',
    ['Chloe', 'OrderlyF', 'winSpeech', 'Victory: registered. Noting strategies.'] => 'Sieg: registriert. Strategien werden notiert.',
    ['Chloe', 'OrderlyF', 'loseSpeech', 'Defeat: registered. '] => 'Niederlage: registriert. ',
    ['Norton', 'PSYCHIC_Male', 'introSpeech', 'I know you from somewhere...'] => 'Ich kenn dich doch irgendwoher...',
    ['Norton', 'PSYCHIC_Male', 'winSpeech', 'I saw this victory in a dream! '] => 'Diesen Sieg hab ich im Traum gesehen! ',
    ['Norton', 'PSYCHIC_Male', 'loseSpeech', 'Where have I seen you before?'] => 'Wo hab ich dich schon mal gesehen?',
    ['Haze', 'PSYCHIC_Male', 'introSpeech', 'My battling is remarkable.'] => 'Meine Kampfkunst ist bemerkenswert.',
    ['Haze', 'PSYCHIC_Male', 'winSpeech', 'Yours, however... no.'] => 'Deine allerdings... nein.',
    ['Haze', 'PSYCHIC_Male', 'loseSpeech', 'Your battling is more remarkable, however!'] => 'Deine Kampfkunst ist allerdings noch bemerkenswerter!',
    ['Zach', 'PSYCHIC_Male', 'introSpeech', 'I can mimic any Pokemon!'] => 'Ich kann jedes Pokémon nachmachen!',
    ['Zach', 'PSYCHIC_Male', 'winSpeech', 'See? I\'m as happy as a Blissey!'] => 'Siehst du? Ich bin so glücklich wie ein Heiteira!',
    ['Zach', 'PSYCHIC_Male', 'loseSpeech', 'See! I\'m as furious as a Primeape!'] => 'Sieh nur! Ich bin so wütend wie ein Rasaff!',
    ['Kaitlyn', 'PSYCHIC_Female', 'introSpeech', 'Have you ever met a real telekinetic before?'] => 'Hast du schon mal einen echten Telekinetiker getroffen?',
    ['Kaitlyn', 'PSYCHIC_Female', 'winSpeech', 'See what a real Psychic looks like!'] => 'So sieht jemand mit echten Psycho-Kräften aus!',
    ['Kaitlyn', 'PSYCHIC_Female', 'loseSpeech', 'I didn\'t get a chance to show my true power!'] => 'Ich konnte meine wahre Kraft gar nicht zeigen!',
    ['Cyri', 'PSYCHIC_Female', 'introSpeech', 'My teacher has assured me I will win today.'] => 'Mein Lehrer hat mir versichert, dass ich heute gewinne.',
    ['Cyri', 'PSYCHIC_Female', 'winSpeech', 'I\'ll never doubt my teacher again!'] => 'An meinem Lehrer werde ich nie wieder zweifeln!',
    ['Cyri', 'PSYCHIC_Female', 'loseSpeech', 'My teacher was... wrong?'] => 'Mein Lehrer lag... falsch?',
    ['Kendra', 'PSYCHIC_Female', 'introSpeech', 'This is a dangerous place. Leave at once.'] => 'Das hier ist gefährlich. Verschwinde sofort.',
    ['Kendra', 'PSYCHIC_Female', 'winSpeech', 'You were warned!'] => 'Du wurdest gewarnt!',
    ['Kendra', 'PSYCHIC_Female', 'loseSpeech', 'Intimidating you didn\'t work, huh?'] => 'Dich einzuschüchtern hat wohl nicht geklappt, was?',
    ['Molly', 'CultistF', 'introSpeech', 'You won\'t find a cuter Trainer anywhere in Reborn!'] => 'In ganz Reborn findest du keine süßere Trainerin als mich!',
    ['Molly', 'CultistF', 'winSpeech', 'I\'m the number one adorable Trainer!'] => 'Ich bin die süßeste Trainerin überhaupt!',
    ['Molly', 'CultistF', 'loseSpeech', 'Was my cuteness not distracting enough? '] => 'War ich nicht süß genug, um dich abzulenken? ',
    ['Jazmin', 'CultistF', 'introSpeech', 'My wit is stronger than even my Pokemon!'] => 'Mein Verstand ist sogar stärker als meine Pokémon!',
    ['Jazmin', 'CultistF', 'winSpeech', 'My Pokemon are plenty strong, too!'] => 'Meine Pokémon sind auch ziemlich stark!',
    ['Jazmin', 'CultistF', 'loseSpeech', 'How dare you silence me!?'] => 'Wie kannst du es wagen, mich zum Schweigen zu bringen!?',
    ['Kelsey', 'CultistF', 'introSpeech', 'You don\'t know our true purpose, here...'] => 'Du weißt nicht, was unser wahres Ziel ist...',
    ['Kelsey', 'CultistF', 'winSpeech', 'Our true purpose... wouldn\'t you like to know?'] => 'Unser wahres Ziel... willst du das nicht gern wissen?',
    ['Kelsey', 'CultistF', 'loseSpeech', 'Very well. Our true purpose is simply to make money. Anticlimactic, I know.'] => 'Na schön. Unser wahres Ziel ist schlicht, Geld zu verdienen. Ziemlich ernüchternd, ich weiß.',
    ['Jalen', 'Cultist', 'introSpeech', 'My Pokemon are all perfectly disciplined. '] => 'Meine Pokémon sind alle perfekt diszipliniert. ',
    ['Jalen', 'Cultist', 'winSpeech', 'We\'re a perfect combination!'] => 'Wir sind ein perfektes Team!',
    ['Jalen', 'Cultist', 'loseSpeech', 'We fought perfectly and still lost?'] => 'Wir haben perfekt gekämpft und trotzdem verloren?',
    ['Griffen', 'Cultist', 'introSpeech', 'Our battle shall be legendary!'] => 'Unser Kampf wird legendär!',
    ['Griffen', 'Cultist', 'winSpeech', 'My triumph will be told for years to come!'] => 'Von meinem Triumph wird man noch jahrelang erzählen!',
    ['Griffen', 'Cultist', 'loseSpeech', 'They will sing of your victory for years to come!'] => 'Von deinem Sieg wird man noch jahrelang singen!',
    ['Xander', 'Cultist', 'introSpeech', 'I\'ve borrowed my boyfriend\'s Pokemon for this!'] => 'Für diesen Kampf hab ich mir die Pokémon meines Freundes geliehen!',
    ['Xander', 'Cultist', 'winSpeech', 'He\'ll be so proud of them for this!'] => 'Er wird so stolz auf sie sein!',
    ['Xander', 'Cultist', 'loseSpeech', 'I guess they\'re not quite used to me...'] => 'Sie sind wohl noch nicht ganz an mich gewöhnt...',
    ['Marvin', 'GENTLEMAN', 'introSpeech', 'You\'re bound to be entertaining to battle.'] => 'Mit dir zu kämpfen wird bestimmt unterhaltsam.',
    ['Marvin', 'GENTLEMAN', 'winSpeech', 'Isn\'t that lovely?'] => 'Ist das nicht schön?',
    ['Marvin', 'GENTLEMAN', 'loseSpeech', 'This makes me very angry indeed!'] => 'Das macht mich wirklich sehr wütend!',
    ['Brennan', 'GENTLEMAN', 'introSpeech', 'I wish to see how youngsters battle these days.'] => 'Ich möchte sehen, wie die Jugend heutzutage kämpft.',
    ['Brennan', 'GENTLEMAN', 'winSpeech', 'How quaint.'] => 'Wie reizend.',
    ['Brennan', 'GENTLEMAN', 'loseSpeech', 'How interesting.'] => 'Wie interessant.',
    ['Baley', 'StreetRat', 'introSpeech', 'Can you dig my sound?'] => 'Kannst du meinen Sound fühlen?',
    ['Baley', 'StreetRat', 'winSpeech', 'Yeah! Dig my sonic boom!'] => 'Yeah! Spür die Überschallknall-Welle!',
    ['Baley', 'StreetRat', 'loseSpeech', 'It\'s like you\'re soundproof!'] => 'Du bist ja wie schalldicht!',
    ['Zackary', 'KNIGHT', 'introSpeech', 'We need to talk. Your behaviour here has not been chivalrous at all!'] => 'Wir müssen reden. Dein Verhalten hier war überhaupt nicht ritterlich!',
    ['Zackary', 'KNIGHT', 'winSpeech', 'Thank you. I see you understand. '] => 'Danke. Ich sehe, du hast verstanden. ',
    ['Zackary', 'KNIGHT', 'loseSpeech', 'Haven\'t you won enough? '] => 'Hast du nicht langsam genug gewonnen? ',
    ['Gabriel', 'AQUA2', 'introSpeech', 'I\'m thinking of quitting to become a musician.'] => 'Ich überlege, ob ich kündige und Musiker werde.',
    ['Gabriel', 'AQUA2', 'winSpeech', 'But then again... couldn\'t I do both?'] => 'Aber andererseits... kann ich nicht beides machen?',
    ['Gabriel', 'AQUA2', 'loseSpeech', 'It\'s like I thought. From now on, I\'m focusing on my first album.'] => 'Wie ich dachte. Ab jetzt konzentriere ich mich auf mein erstes Album.',
    ['Emily', 'LADY', 'introSpeech', 'You\'re quite striking!'] => 'Du bist ganz schön umwerfend!',
    ['Emily', 'LADY', 'winSpeech', 'You struck out!'] => 'Du hast daneben gehauen!',
    ['Emily', 'LADY', 'loseSpeech', 'You struck my Pokemon with all you had!'] => 'Du hast meine Pokémon mit voller Wucht getroffen!',
    ['Jordyn', 'BEAUTY', 'introSpeech', 'You don\'t know my secret...'] => 'Du kennst mein Geheimnis nicht...',
    ['Jordyn', 'BEAUTY', 'winSpeech', 'I am not as I appear...'] => 'Ich bin nicht, was ich zu sein scheine...',
    ['Jordyn', 'BEAUTY', 'loseSpeech', 'Could you... possibly know the truth?'] => 'Könntest du... etwa die Wahrheit kennen?',
    ['Sofia', 'NatureGirl', 'introSpeech', 'This place makes me nervous.'] => 'Dieser Ort macht mich nervös.',
    ['Sofia', 'NatureGirl', 'winSpeech', 'I miss the forest.'] => 'Ich vermisse den Wald.',
    ['Sofia', 'NatureGirl', 'loseSpeech', 'Where are the trees? The water?'] => 'Wo sind die Bäume? Das Wasser?',
    ['Braden', 'POACHERM', 'introSpeech', 'Can we hurry? I\'m missing my favourite show.'] => 'Können wir uns beeilen? Ich verpasse meine Lieblingsserie.',
    ['Braden', 'POACHERM', 'winSpeech', 'Hey, this was even more fun than my show!'] => 'Hey, das hat sogar mehr Spaß gemacht als meine Sendung!',
    ['Braden', 'POACHERM', 'loseSpeech', 'At least I can get back to the TV now!'] => 'Wenigstens kann ich jetzt wieder fernsehen!',
    ['Kayden', 'POACHERM', 'introSpeech', 'Hey, what\'s the food like here?'] => 'Hey, wie ist das Essen hier?',
    ['Kayden', 'POACHERM', 'winSpeech', 'Maybe now I\'ll go get a snack...'] => 'Vielleicht hol ich mir jetzt einen Snack...',
    ['Kayden', 'POACHERM', 'loseSpeech', 'I thought something smelled good earlier.'] => 'Vorhin hat doch irgendwas gut gerochen.',
    ['Sassacus', 'AceTrainerM', 'introSpeech', 'Have you ever been to Hoenn?'] => 'Warst du schon mal in Hoenn?',
    ['Sassacus', 'AceTrainerM', 'winSpeech', 'Never mind. The trainers there would destroy you.'] => 'Ach, egal. Die Trainer dort würden dich fertigmachen.',
    ['Sassacus', 'AceTrainerM', 'loseSpeech', 'I won a free trip there once. Great place. '] => 'Ich hab mal eine Reise dorthin gewonnen. Toller Ort. ',
    ['Julianna', 'POACHERF', 'introSpeech', 'You look pretty tired.'] => 'Du siehst ziemlich müde aus.',
    ['Julianna', 'POACHERF', 'winSpeech', 'I hit you with a Wake-Up Slap!'] => 'Ich hab dich mit Weckruf wachgerüttelt!',
    ['Julianna', 'POACHERF', 'loseSpeech', 'Did you use Yawn on me?'] => 'Hast du Gähner gegen mich eingesetzt?',
    ['Amara', 'Punk', 'introSpeech', 'You really think you can beat me? Plumeria\'s my cousin, you know!'] => 'Du glaubst wirklich, du kannst mich schlagen? Plumeria ist meine Cousine, weißt du!',
    ['Amara', 'Punk', 'winSpeech', 'Alolan pride!'] => 'Alola-Stolz!',
    ['Amara', 'Punk', 'loseSpeech', 'She better never find out about this...'] => 'Das darf sie bloß nie erfahren...',
    ['Lynn', 'AceTrainerF', 'introSpeech', 'Your secret can\'t be hidden forever...'] => 'Dein Geheimnis bleibt nicht ewig verborgen...',
    ['Lynn', 'AceTrainerF', 'winSpeech', 'I know your secret now!'] => 'Jetzt kenn ich dein Geheimnis!',
    ['Lynn', 'AceTrainerF', 'loseSpeech', 'You can\'t safeguard your own secret...'] => 'Du kannst nicht mal dein eigenes Geheimnis schützen...',
    ['Alucs', 'Orderly', 'introSpeech', 'Don\'t mind me, just here to clean...'] => 'Keine Sorge, ich bin nur zum Putzen hier...',
    ['Alucs', 'Orderly', 'winSpeech', 'Clearly you\'ve forgotten the first rule of battle: do not act incautiously around little smiling orderlies!'] => 'Du hast wohl die erste Kampfregel vergessen: Leg dich nicht leichtsinnig mit lächelnden kleinen Pflegern an!',
    ['Alucs', 'Orderly', 'loseSpeech', 'Impressive, hmm.'] => 'Beeindruckend, hm.',
    ['Dominic', 'Orderly', 'introSpeech', 'Hold still! I need to get a picture of this moment!'] => 'Halt still! Ich muss diesen Moment fotografieren!',
    ['Dominic', 'Orderly', 'winSpeech', 'Make sure you get my good side for my scrapbook!'] => 'Sorg dafür, dass meine Schokoladenseite im Sammelalbum landet!',
    ['Dominic', 'Orderly', 'loseSpeech', 'I don\'t really want a picture of this...'] => 'Davon möchte ich eigentlich kein Foto...',
    ['Arcin', 'Orderly', 'introSpeech', 'Wh- a battle? Why do you want to battle me? I\'m just an orderly!'] => 'W- ein Kampf? Warum willst du gegen mich kämpfen? Ich bin doch nur Pfleger!',
    ['Arcin', 'Orderly', 'winSpeech', 'I guess this is one way to make some cash!'] => 'Na ja, so kann man auch Geld verdienen!',
    ['Arcin', 'Orderly', 'loseSpeech', 'Sneak in to steal somethin\' and get trounced in battle... this is not my day!'] => 'Einbrechen, was klauen und dann im Kampf vermöbelt werden... heute läuft\'s echt nicht!',
    ['Valeria', 'OrderlyF', 'introSpeech', 'I\'m done holding back!'] => 'Ich halte mich nicht länger zurück!',
    ['Valeria', 'OrderlyF', 'winSpeech', 'My power ascends!'] => 'Meine Macht steigt!',
    ['Valeria', 'OrderlyF', 'loseSpeech', 'You crossed a line!'] => 'Du bist zu weit gegangen!',
    ['Delaney', 'OrderlyF', 'introSpeech', 'I\'m not sure this was the right part-time job for me...'] => 'Ich bin mir nicht sicher, ob das der richtige Nebenjob für mich ist...',
    ['Delaney', 'OrderlyF', 'winSpeech', 'The bonus pay\'s great though!'] => 'Der Bonus ist allerdings klasse!',
    ['Delaney', 'OrderlyF', 'loseSpeech', 'Nope. Definitely should\'ve applied at Sweet Kiss Candy Shop.'] => 'Nein. Ich hätte mich doch beim Sweet Kiss Candy Shop bewerben sollen.',
    ['Meghan', 'OrderlyF', 'introSpeech', 'Hey, have you read the latest issue of \'Blaziken Mask\'?'] => 'Hey, hast du schon die neueste Ausgabe von „Lohgock-Maske“ gelesen?',
    ['Meghan', 'OrderlyF', 'winSpeech', 'I can\'t wait until next week\'s issue!'] => 'Ich kann die nächste Ausgabe kaum erwarten!',
    ['Meghan', 'OrderlyF', 'loseSpeech', 'It\'s mind-blowing! '] => 'Das haut mich um! ',
    ['Roberto', 'MAGMA1', 'introSpeech', 'You want to know why I joined the Magma Gang?'] => 'Willst du wissen, warum ich der Magma-Gang beigetreten bin?',
    ['Roberto', 'MAGMA1', 'winSpeech', 'It\'s because we\'re the strongest in Reborn City!'] => 'Weil wir die Stärksten in Reborn City sind!',
    ['Roberto', 'MAGMA1', 'loseSpeech', 'It\'s because I just can\'t stand the cold. '] => 'Weil ich die Kälte einfach nicht ausstehen kann. ',
    ['Damian', 'MAGMA1', 'introSpeech', 'Brace yourself for a Heat Wave!'] => 'Mach dich auf eine Hitzewelle gefasst!',
    ['Damian', 'MAGMA1', 'winSpeech', 'You Overheated!'] => 'Du bist völlig überhitzt!',
    ['Damian', 'MAGMA1', 'loseSpeech', 'I\'m Fire Blasting off again...'] => 'Ich mach mich aus dem Staub...',
    ['Fiwam', 'MAGMA1', 'introSpeech', 'I keep telling the boss we need new uniforms...'] => 'Ich sag dem Boss ständig, dass wir neue Uniformen brauchen...',
    ['Fiwam', 'MAGMA1', 'winSpeech', 'Maybe he\'ll listen now!'] => 'Vielleicht hört er jetzt auf mich!',
    ['Fiwam', 'MAGMA1', 'loseSpeech', 'Honestly, why can\'t we look more stylish?'] => 'Ehrlich, warum können wir nicht stylischer aussehen?',
    ['Graham', 'MAGMA1', 'introSpeech', 'Don\'t take this personally.'] => 'Nimm\'s nicht persönlich.',
    ['Graham', 'MAGMA1', 'winSpeech', 'It was just business.'] => 'War nur Geschäft.',
    ['Graham', 'MAGMA1', 'loseSpeech', 'Okay, I get it!'] => 'Okay, ich hab\'s kapiert!',
    ['Tylor', 'Cultist', 'introSpeech', 'Normally, I wouldn\'t do this, but...'] => 'Normalerweise würde ich das nicht tun, aber...',
    ['Tylor', 'Cultist', 'winSpeech', 'I\'m fairy certain I just beat you!'] => 'Ich bin mir feenomenal sicher, dass ich dich gerade besiegt habe!',
    ['Tylor', 'Cultist', 'loseSpeech', 'Stop \'dragon my heart around!'] => 'Hör auf, mein Herz durch den Drachen zu ziehen!',
    ['Jaren', 'BATTLEGIRL', 'introSpeech', 'I\'ll show you my fighting spirit!'] => 'Ich zeig dir meinen Kampfgeist!',
    ['Jaren', 'BATTLEGIRL', 'winSpeech', 'Was that enough spirit for you?'] => 'War das genug Kampfgeist für dich?',
    ['Jaren', 'BATTLEGIRL', 'loseSpeech', 'Your Pokemon were distracting, okay? They\'re too cute!'] => 'Deine Pokémon haben mich abgelenkt, okay? Die sind zu süß!',
    ['Cordell', 'TechNerd', 'introSpeech', 'This is my 17th match this week. '] => 'Das ist mein 17. Match diese Woche. ',
    ['Cordell', 'TechNerd', 'winSpeech', 'Hey! My first win this week!'] => 'Hey! Mein erster Sieg diese Woche!',
    ['Cordell', 'TechNerd', 'loseSpeech', 'Match 17: loss. '] => 'Match 17: verloren. ',
    ['Ro', 'Doxy', 'introSpeech', 'Check out my new shoes!'] => 'Schau dir meine neuen Schuhe an!',
    ['Ro', 'Doxy', 'winSpeech', 'Ha! Distracted you!'] => 'Ha! Abgelenkt!',
    ['Ro', 'Doxy', 'loseSpeech', 'I\'m just too excited about these shoes!'] => 'Ich freu mich einfach zu sehr über diese Schuhe!',
    ['Marshall', 'YOUNGSTER', 'introSpeech', 'I have my own place now! Yay!'] => 'Ich hab jetzt mein eigenes Zuhause! Yay!',
    ['Marshall', 'YOUNGSTER', 'winSpeech', 'I accept this win in the name of Fort Marshall!'] => 'Diesen Sieg widme ich Fort Marshall!',
    ['Marshall', 'YOUNGSTER', 'loseSpeech', 'It\'s really a tree fort...'] => 'Ist eigentlich nur ein Baumhaus...',
    ['Johan', 'YOUNGSTER', 'introSpeech', 'Do you like Fossil Pokemon?'] => 'Magst du Fossil-Pokémon?',
    ['Johan', 'YOUNGSTER', 'winSpeech', 'Next time, you should battle with Fossil Pokemon!'] => 'Nächstes Mal solltest du mit Fossil-Pokémon kämpfen!',
    ['Johan', 'YOUNGSTER', 'loseSpeech', 'Fossil Pokemon are the best! My favorite\'s Carracosta!'] => 'Fossil-Pokémon sind die Besten! Mein Liebling ist Karippas!',
    ['Shea', 'COOLTRAINER_Female', 'introSpeech', 'I am beauty! I am grace!'] => 'Ich bin Schönheit! Ich bin Anmut!',
    ['Shea', 'COOLTRAINER_Female', 'winSpeech', 'I stole victory in this place!'] => 'Hier hab ich den Sieg geklaut!',
    ['Shea', 'COOLTRAINER_Female', 'loseSpeech', 'Even in defeat, I\'m elegant!'] => 'Selbst in der Niederlage bin ich elegant!',
    ['Deneb', 'COOLTRAINER_Female', 'introSpeech', 'Ready? Okay!'] => 'Bereit? Okay!',
    ['Deneb', 'COOLTRAINER_Female', 'winSpeech', 'Here we go, no need to fear it! I\'m filled up with battling spirit!'] => 'Los geht\'s, keine Angst! Mein Kampfgeist ist voll entflammt!',
    ['Deneb', 'COOLTRAINER_Female', 'loseSpeech', 'That\'s all right, that\'s okay, I\'ll try again another day...'] => 'Schon okay, halb so wild, ich versuch\'s an einem anderen Tag...',
    ['Isiah', 'SWIMMERBOI', 'introSpeech', 'Hey, if you see my mom, don\'t tell her I was here, okay?'] => 'Hey, wenn du meine Mom siehst, sag ihr nicht, dass ich hier war, okay?',
    ['Isiah', 'SWIMMERBOI', 'winSpeech', 'Mom thinks I study all the time, but that\'s boring!'] => 'Mom denkt, ich lerne ständig, aber das ist langweilig!',
    ['Isiah', 'SWIMMERBOI', 'loseSpeech', 'I\'m supposed to be studying right now...'] => 'Ich sollte gerade lernen...',
    ['Garrett', 'SWIMMERBOI', 'introSpeech', 'Not much to say, huh?'] => 'Nicht viel zu sagen, was?',
    ['Garrett', 'SWIMMERBOI', 'winSpeech', 'You should try speaking up a bit more!'] => 'Du solltest ruhig etwas lauter sprechen!',
    ['Garrett', 'SWIMMERBOI', 'loseSpeech', 'It\'s okay. I don\'t always feel like talking either.'] => 'Schon gut. Manchmal hab ich auch keine Lust zu reden.',
    ['Haylie', 'Punk', 'introSpeech', 'I haven\'t slept in a week...'] => 'Ich hab seit einer Woche nicht geschlafen...',
    ['Haylie', 'Punk', 'winSpeech', 'Finally, I can sleep...'] => 'Endlich kann ich schlafen...',
    ['Haylie', 'Punk', 'loseSpeech', 'Is there a Ghost Pokemon following me? Maybe that\'s keeping me awake...'] => 'Verfolgt mich ein Geist-Pokémon? Vielleicht hält mich das wach...',
    ['Megan', 'SWIMMERGRIL', 'introSpeech', 'There\'s no telling where this battle will go!'] => 'Wer weiß, wie dieser Kampf ausgeht!',
    ['Megan', 'SWIMMERGRIL', 'winSpeech', 'I\'m no ordinary girl!'] => 'Ich bin kein gewöhnliches Mädchen!',
    ['Megan', 'SWIMMERGRIL', 'loseSpeech', 'I must get better...'] => 'Ich muss besser werden...',
    ['Issac', 'YOUNGSTER', 'introSpeech', 'My battle skills are no laughing matter!'] => 'Meine Kampffähigkeiten sind kein Grund zum Lachen!',
    ['Issac', 'YOUNGSTER', 'winSpeech', 'I guess I got the last laugh!'] => 'Tja, zuletzt hab ich gelacht!',
    ['Issac', 'YOUNGSTER', 'loseSpeech', 'Please don\'t laugh at me!'] => 'Bitte lach mich nicht aus!',
    ['Quinton', 'YOUNGSTER', 'introSpeech', 'Want to play ball after this?'] => 'Wollen wir danach Ball spielen?',
    ['Quinton', 'YOUNGSTER', 'winSpeech', 'I\'m a whiz with both basketballs and Pokeballs!'] => 'Mit Basket- und Pokébällen kenn ich mich bestens aus!',
    ['Quinton', 'YOUNGSTER', 'loseSpeech', 'If you ever want to play basketball, just let me know!'] => 'Wenn du mal Basketball spielen willst, sag einfach Bescheid!',
    ['Salma', 'LADY', 'introSpeech', 'Let\'s see... I like long walks on Azurine Island, dancing... oh, a battle? Sure, I like battling too!'] => 'Mal sehen... Ich mag lange Spaziergänge auf der Azurine-Insel, Tanzen... oh, ein Kampf? Klar, Kämpfen mag ich auch!',
    ['Salma', 'LADY', 'winSpeech', 'Sorry, but you\'re just not my type!'] => 'Tut mir leid, du bist einfach nicht mein Typ!',
    ['Salma', 'LADY', 'loseSpeech', 'Huh? This wasn\'t the OKCufant meetup? Oh dear...'] => 'Hä? Das war gar nicht das OKCufant-Treffen? Oje...',
    ['Ansley', 'LADY', 'introSpeech', 'This is the best day of my life!'] => 'Das ist der beste Tag meines Lebens!',
    ['Ansley', 'LADY', 'winSpeech', 'First I get engaged, then I win against you- this day couldn\'t get any better!'] => 'Erst verlobe ich mich, dann gewinne ich gegen dich – besser kann der Tag nicht werden!',
    ['Ansley', 'LADY', 'loseSpeech', 'Even this can\'t dampen my spirits!'] => 'Nicht mal das kann mir die Laune verderben!',
    ['Holden', 'StreetRat', 'introSpeech', 'Heh heh...'] => 'Hehehe...',
    ['Holden', 'StreetRat', 'winSpeech', 'This place is sad, if even a kid like me can win!'] => 'Dieser Ort ist traurig, wenn sogar ein Kind wie ich gewinnen kann!',
    ['Holden', 'StreetRat', 'loseSpeech', 'I didn\'t know the trainers here were this strong!'] => 'Ich wusste gar nicht, dass die Trainer hier so stark sind!',
    ['Luca', 'StreetRat', 'introSpeech', 'What kind of riffraff did they let in here?'] => 'Was für ein Gesindel lassen die hier rein?',
    ['Luca', 'StreetRat', 'winSpeech', 'Take a closer look!'] => 'Sieh mal genauer hin!',
    ['Luca', 'StreetRat', 'loseSpeech', 'You beat me? I don\'t buy that!'] => 'Du hast mich besiegt? Das glaub ich nicht!',
    ['Jamison', 'HARDHAT', 'introSpeech', 'It\'s been a long shift. Time to cool down with a battle!'] => 'Die Schicht war lang. Zeit, mich mit einem Kampf abzukühlen!',
    ['Jamison', 'HARDHAT', 'winSpeech', 'Just what I needed!'] => 'Genau das hab ich gebraucht!',
    ['Jamison', 'HARDHAT', 'loseSpeech', 'Now I\'m even more stressed!'] => 'Jetzt bin ich noch gestresster!',
    ['Gunnar', 'HARDHAT', 'introSpeech', 'Behold the Great Gunnar, Reborn\'s most gorgeous gamer!'] => 'Bestaunt den großen Gunnar, Reborns schönsten Gamer!',
    ['Gunnar', 'HARDHAT', 'winSpeech', 'Gorgeous and godly in battle!'] => 'Schön und göttlich im Kampf!',
    ['Gunnar', 'HARDHAT', 'loseSpeech', 'Grumble grumble...'] => 'Grummel, grummel...',
    ['Pierce', 'SWIMMERBOI', 'introSpeech', 'This battle... Will it finally be enough for me?'] => 'Dieser Kampf... Reicht es diesmal endlich?',
    ['Pierce', 'SWIMMERBOI', 'winSpeech', 'Look at me now!'] => 'Sieh mich jetzt an!',
    ['Pierce', 'SWIMMERBOI', 'loseSpeech', 'I really tried to make it out!'] => 'Ich hab wirklich versucht, es hier rauszuschaffen!',
    ['Regina', 'SWIMMERGRIL', 'introSpeech', 'I came here with my friends! It\'s been a blast so far!'] => 'Ich bin mit meinen Freunden hier! Bis jetzt macht\'s riesigen Spaß!',
    ['Regina', 'SWIMMERGRIL', 'winSpeech', 'This battle was totally fun, too!'] => 'Der Kampf hat auch total Spaß gemacht!',
    ['Regina', 'SWIMMERGRIL', 'loseSpeech', 'You\'re so mean!!'] => 'Du bist so gemein!!',
    ['Cat', 'SWIMMERGRIL', 'introSpeech', 'It\'s so cold! Does someone have the air conditioner cranked up?'] => 'Es ist so kalt! Hat jemand die Klimaanlage voll aufgedreht?',
    ['Cat', 'SWIMMERGRIL', 'winSpeech', 'Aah, that\'s better. The battle warmed me up!'] => 'Aah, schon besser. Der Kampf hat mich aufgewärmt!',
    ['Cat', 'SWIMMERGRIL', 'loseSpeech', 'Seriously, why\'s it so icy in here?'] => 'Echt jetzt, warum ist es hier so eisig?',
    ['Sol', 'StreetRat', 'introSpeech', 'Man, it\'s nice out today.'] => 'Mann, heute ist\'s schön draußen.',
    ['Sol', 'StreetRat', 'winSpeech', 'This kind of weather is downright inspiring.'] => 'Bei so einem Wetter kommen einem die besten Ideen.',
    ['Sol', 'StreetRat', 'loseSpeech', 'Hey, you\'re good. We should go fishing sometime!'] => 'Hey, du bist gut. Wir sollten mal zusammen angeln gehen!',
    ['Earl', 'StreetRat', 'introSpeech', 'Hehe, check this out.'] => 'Hehe, sieh dir das an.',
    ['Earl', 'StreetRat', 'winSpeech', 'Well, did I bug you?'] => 'Na, hab ich dich genervt?',
    ['Earl', 'StreetRat', 'loseSpeech', 'You\'re really bugging me!'] => 'Du gehst mir echt auf die Nerven!',
    ['Ari', 'FISHERMAN', 'introSpeech', 'You\'re lookin\' at this year\'s valedictorian!'] => 'Du siehst den diesjährigen Jahrgangsbesten vor dir!',
    ['Ari', 'FISHERMAN', 'winSpeech', 'They\'re going to put up a trophy with my name on it and everything!'] => 'Die stellen sogar eine Trophäe mit meinem Namen drauf auf!',
    ['Ari', 'FISHERMAN', 'loseSpeech', 'OTS? No, no. I meant Canalave Fishing Institute!'] => 'OTS? Nein, ich meine das Angelinstitut von Fleetburg!',
    ['Hunter', 'FISHERMAN', 'introSpeech', 'Quiet, quiet... wait for the bite.'] => 'Ruhig, ruhig... warte auf den Biss.',
    ['Hunter', 'FISHERMAN', 'winSpeech', 'Looks like I hooked a big one there!'] => 'Sieht aus, als hätte ich einen ganz schönen Brocken an der Angel!',
    ['Hunter', 'FISHERMAN', 'loseSpeech', 'That wasn\'t quiet, kid!'] => 'Das war nicht ruhig, Kleiner!',
    ['Aiden', 'KNIGHT', 'introSpeech', 'I\'m normally a Gym Trainer, but today\'s my day off. '] => 'Normalerweise bin ich Arenatrainer, aber heute hab ich frei. ',
    ['Aiden', 'KNIGHT', 'winSpeech', 'If I win enough here, maybe I\'ll get a promotion!'] => 'Wenn ich hier genug siege, werde ich vielleicht befördert!',
    ['Aiden', 'KNIGHT', 'loseSpeech', 'Between you and me? I hate these costumes. We deserve a raise for wearing them!'] => 'Unter uns? Ich hasse diese Kostüme. Für die sollten wir mehr Geld kriegen!',
    ['Xavier', 'KNIGHT', 'introSpeech', 'En garde!'] => 'En garde!',
    ['Xavier', 'KNIGHT', 'winSpeech', 'I reign victorious! No blackguard such as yourself could ever defeat me!'] => 'Ich triumphiere! So ein Schurke wie du könnte mich niemals besiegen!',
    ['Xavier', 'KNIGHT', 'loseSpeech', 'A fine battle. You fight with skill!'] => 'Ein feiner Kampf. Du kämpfst geschickt!',
    ['Clinton', 'PoliceOfficer', 'introSpeech', '\'Scuse me, but I couldn\'t help noticing-- your outfit.'] => 'Verzeihung, aber dein Outfit ist mir aufgefallen.',
    ['Clinton', 'PoliceOfficer', 'winSpeech', 'It needs a little something extra. Maybe a new hat? '] => 'Irgendwas fehlt noch. Vielleicht ein neuer Hut? ',
    ['Clinton', 'PoliceOfficer', 'loseSpeech', 'It looks amazing! '] => 'Es sieht toll aus! ',
    ['Jesse', 'PoliceOfficer', 'introSpeech', 'Um-- Prepare for battle!'] => 'Ähm-- Machen wir uns kampfbereit!',
    ['Jesse', 'PoliceOfficer', 'winSpeech', 'Thank you, Trainer!'] => 'Danke, Trainer!',
    ['Jesse', 'PoliceOfficer', 'loseSpeech', 'This is the weirdest training requirement for a job I\'ve ever heard of.'] => 'Das ist die seltsamste Trainingsanforderung für einen Job, von der ich je gehört habe.',
    ['Eduardo', 'GUITARIST', 'introSpeech', 'Stop me if you\'ve heard this one.'] => 'Halt mich auf, wenn du den schon kennst.',
    ['Eduardo', 'GUITARIST', 'winSpeech', 'My music will never die!'] => 'Meine Musik wird niemals sterben!',
    ['Eduardo', 'GUITARIST', 'loseSpeech', 'Sure, sure, it\'s not the most unique riff. But it still rocks!'] => 'Klar, klar, das Riff ist nicht besonders originell. Aber es rockt trotzdem!',
    ['Hal', 'GUITARIST', 'introSpeech', 'Hey, kids! Welcome to a special episode of Hal\'s Preschool Hour!'] => 'Hey, Kinder! Willkommen zu einer Sonderfolge von Hals Vorschulstunde!',
    ['Hal', 'GUITARIST', 'winSpeech', 'This week\'s episode is brought to you by Obsidia Department Store!'] => 'Diese Folge wird präsentiert vom Kaufhaus Obsidia!',
    ['Hal', 'GUITARIST', 'loseSpeech', 'Shit! Wait, cut! Cut! '] => 'Scheiße! Wartet, Schnitt! Schnitt! ',
    ['Gage', 'Casanova', 'introSpeech', 'Fly on the wings of love, my dear.'] => 'Flieg auf den Flügeln der Liebe, mein Schatz.',
    ['Gage', 'Casanova', 'winSpeech', 'Am I not making your heart soar?'] => 'Lass ich dein Herz nicht höherschlagen?',
    ['Gage', 'Casanova', 'loseSpeech', 'You\'re making my heart soar!'] => 'Du lässt mein Herz höherschlagen!',
    ['Ksldr', 'Casanova', 'introSpeech', 'I had a strange dream last night...'] => 'Letzte Nacht hatte ich einen seltsamen Traum...',
    ['Ksldr', 'Casanova', 'winSpeech', 'Y-you! Your scary face was in my dream!'] => 'D-du! Dein gruseliges Gesicht kam in meinem Traum vor!',
    ['Ksldr', 'Casanova', 'loseSpeech', 'A bittersweet dream, much like this battle.'] => 'Ein bittersüßer Traum, genau wie dieser Kampf.',
    ['Jarrett', 'AQUA1', 'introSpeech', 'This music- I just have to dance!'] => 'Diese Musik- ich muss einfach tanzen!',
    ['Jarrett', 'AQUA1', 'winSpeech', 'Heck yeah! My moves are awesome!'] => 'Oh ja! Meine Moves sind der Hammer!',
    ['Jarrett', 'AQUA1', 'loseSpeech', 'Okay, maybe I did get a little distracted.'] => 'Okay, vielleicht war ich doch ein bisschen abgelenkt.',
    ['Garett', 'AQUA1', 'introSpeech', 'Hey, kid. You taking care of this place?'] => 'Hey, Kleiner. Passt du hier auf?',
    ['Garett', 'AQUA1', 'winSpeech', 'Keep training. From what I hear, this place needs it.'] => 'Trainier weiter. Wie ich höre, kann dieser Ort das gebrauchen.',
    ['Garett', 'AQUA1', 'loseSpeech', 'Good, good.'] => 'Gut, gut.',
    ['Emanuel', 'HIKER', 'introSpeech', 'Sometimes you need a hard head to win!'] => 'Manchmal braucht man einen Dickschädel, um zu gewinnen!',
    ['Emanuel', 'HIKER', 'winSpeech', 'Strong and immovable as stone!'] => 'Stark und unbeweglich wie Stein!',
    ['Emanuel', 'HIKER', 'loseSpeech', 'I flinched!'] => 'Ich bin zurückgeschreckt!',
    ['Gustavo', 'HIKER', 'introSpeech', 'Charge! Charge!'] => 'Angriff! Angriff!',
    ['Gustavo', 'HIKER', 'winSpeech', 'Now that I win, can I get a Pokenav with a better battery?'] => 'Jetzt, wo ich gewonnen hab, krieg ich einen PokéNav mit besserem Akku?',
    ['Gustavo', 'HIKER', 'loseSpeech', 'Come on, you stupid PokeNav! Charge already!'] => 'Komm schon, du blöder PokéNav! Lad endlich!',
    ['Kameron', 'TechNerd', 'introSpeech', 'I\'ve been working on my latest invention!'] => 'Ich arbeite gerade an meiner neuesten Erfindung!',
    ['Kameron', 'TechNerd', 'winSpeech', 'It\'s an ultra-high-speed charger for any battery!'] => 'Ein ultraschnelles Ladegerät für jeden Akku!',
    ['Kameron', 'TechNerd', 'loseSpeech', 'But you didn\'t get to hear about it!'] => 'Aber du hast gar nicht mehr davon erfahren!',
    ['Alfredo', 'TechNerd', 'introSpeech', 'I\'m a bit stuck. Let\'s see if this battle gives me any ideas!'] => 'Ich stecke ein bisschen fest. Mal sehen, ob mir dieser Kampf Ideen bringt!',
    ['Alfredo', 'TechNerd', 'winSpeech', 'No new ideas, but that was fascinating.'] => 'Keine neuen Ideen, aber das war faszinierend.',
    ['Alfredo', 'TechNerd', 'loseSpeech', 'I think I figured it out! Thanks!'] => 'Ich glaub, ich hab\'s raus! Danke!',
    ['Ruben', 'GENTLEMAN', 'introSpeech', 'I\'ve always been a traveler at heart.'] => 'Im Herzen war ich schon immer ein Reisender.',
    ['Ruben', 'GENTLEMAN', 'winSpeech', 'Be on your way, then. '] => 'Dann zieh weiter. ',
    ['Ruben', 'GENTLEMAN', 'loseSpeech', 'And it looks like you\'ve sent me on my way once again!'] => 'Und anscheinend hast du mich wieder auf den Weg geschickt!',
    ['Lamar', 'GENTLEMAN', 'introSpeech', 'I\'ll show you the best Pokemon money can buy!'] => 'Ich zeig dir die besten Pokémon, die man für Geld kaufen kann!',
    ['Lamar', 'GENTLEMAN', 'winSpeech', 'They\'re nowhere near mine, of course, but your Pokemon performed admirably as well!'] => 'An meine kommen sie natürlich nicht ran, aber deine Pokémon haben sich auch beachtlich geschlagen!',
    ['Lamar', 'GENTLEMAN', 'loseSpeech', 'My dears, you\'re still the best! '] => 'Meine Lieblinge, ihr seid immer noch die Besten! ',
    ['Jaxon', 'YOUNGSTER', 'introSpeech', 'Fall\'s my favourite season. '] => 'Der Herbst ist meine liebste Jahreszeit. ',
    ['Jaxon', 'YOUNGSTER', 'winSpeech', 'Fall\'s my favourite, but I\'m awesome all year round!'] => 'Der Herbst ist mein Favorit, aber ich bin das ganze Jahr über großartig!',
    ['Jaxon', 'YOUNGSTER', 'loseSpeech', 'Sawsbuck look their best in the fall, after all!'] => 'Kronjuwild sehen im Herbst schließlich am besten aus!',
    ['Logan', 'YOUNGSTER', 'introSpeech', 'Hmm... should I study, or take a nap?'] => 'Hm... soll ich lernen oder ein Nickerchen machen?',
    ['Logan', 'YOUNGSTER', 'winSpeech', 'Okay, fiiiine, I\'ll study.'] => 'Na gut, na guuut, ich lern ja schon.',
    ['Logan', 'YOUNGSTER', 'loseSpeech', 'Naptime it is!'] => 'Dann ist jetzt Schlafenszeit!',
    ['Emilee', 'COOLTRAINER_Female', 'introSpeech', 'Ohmigosh, are you for real?'] => 'Oh mein Gott, echt jetzt?',
    ['Emilee', 'COOLTRAINER_Female', 'winSpeech', 'Why do you look so much like the Champion but fight so badly?'] => 'Wieso siehst du dem Champ so ähnlich, kämpfst aber so schlecht?',
    ['Emilee', 'COOLTRAINER_Female', 'loseSpeech', 'I met a celebrity!'] => 'Ich hab einen Promi getroffen!',
    ['Josie', 'COOLTRAINER_Female', 'introSpeech', 'Which color scarf do you think I should buy my Pokemon?'] => 'In welcher Farbe soll ich meinem Pokémon einen Schal kaufen?',
    ['Josie', 'COOLTRAINER_Female', 'winSpeech', 'This is a sign! I\'ll buy them both!'] => 'Das ist ein Zeichen! Ich kauf beide!',
    ['Josie', 'COOLTRAINER_Female', 'loseSpeech', 'I saw a green one in the Department Store, but I also saw a red one online...'] => 'Im Kaufhaus hab ich einen grünen gesehen, aber online auch einen roten...',
    ['Torre', 'COOLTRAINER_Male', 'introSpeech', 'How much do you know about Grass-type Pokemon?'] => 'Wie viel weißt du über Pflanzen-Pokémon?',
    ['Torre', 'COOLTRAINER_Male', 'winSpeech', 'I\'m trying to raise a Flabebe, but- Wait, what do you mean that\'s not a Grass-type?'] => 'Ich ziehe gerade ein Flabébé auf, aber—Moment, wie meinst du, das ist kein Pflanzen-Pokémon?',
    ['Torre', 'COOLTRAINER_Male', 'loseSpeech', 'More than me, I bet...'] => 'Bestimmt mehr als ich...',
    ['Skyler', 'COOLTRAINER_Male', 'introSpeech', 'Let me ingrain my battle style into your memory.'] => 'Ich präge dir meinen Kampfstil ins Gedächtnis ein.',
    ['Skyler', 'COOLTRAINER_Male', 'winSpeech', 'I\'m unforgettable now!'] => 'Jetzt bin ich unvergesslich!',
    ['Skyler', 'COOLTRAINER_Male', 'loseSpeech', 'That was pretty rude!'] => 'Das war ziemlich unhöflich!',
    ['Ruth', 'RANGERF', 'introSpeech', 'Life is a carnival!'] => 'Das Leben ist ein Jahrmarkt!',
    ['Ruth', 'RANGERF', 'winSpeech', 'Life is a carnival, and I just won the top prize!'] => 'Das Leben ist ein Jahrmarkt, und ich hab gerade den Hauptpreis gewonnen!',
    ['Ruth', 'RANGERF', 'loseSpeech', 'Let me off the ride!'] => 'Lasst mich aussteigen!',
    ['Melody', 'RANGERF', 'introSpeech', 'So this is what a real battle\'s like!'] => 'Also so fühlt sich ein echter Kampf an!',
    ['Melody', 'RANGERF', 'winSpeech', 'If I win enough, maybe Mom won\'t worry so much...'] => 'Wenn ich genug gewinne, macht Mom sich vielleicht nicht mehr so viele Sorgen...',
    ['Melody', 'RANGERF', 'loseSpeech', 'I think I\'ll go for a swim now...'] => 'Ich glaub, ich geh jetzt schwimmen...',
    ['Pedro', 'SWIMMERBOI', 'introSpeech', 'Hey! You ever been white-water swimming before?'] => 'Hey! Warst du schon mal Wildwasser-Schwimmen?',
    ['Pedro', 'SWIMMERBOI', 'winSpeech', 'It\'s pretty extreme. I doubt your Pokemon are strong enough to handle it.'] => 'Das ist ganz schön extrem. Ich bezweifle, dass deine Pokémon das schaffen.',
    ['Pedro', 'SWIMMERBOI', 'loseSpeech', 'It\'s pretty extreme, but my Pokemon protect me!'] => 'Ganz schön extrem, aber meine Pokémon beschützen mich!',
    ['Erick', 'SWIMMERBOI', 'introSpeech', 'I\'m more of a techie, but sometimes I like to take a break.'] => 'Ich bin eher ein Technikfreak, aber manchmal mach ich gern Pause.',
    ['Erick', 'SWIMMERBOI', 'winSpeech', 'I guess I\'m awesome whichever Pokemon I battle with!'] => 'Wohl egal, mit welchen Pokémon ich kämpfe – ich bin einfach klasse!',
    ['Erick', 'SWIMMERBOI', 'loseSpeech', 'I guess I should\'ve practiced more with these Pokemon!'] => 'Ich hätte mit diesen Pokémon wohl mehr üben sollen!',
    ['Elaine', 'SWIMMERGRIL', 'introSpeech', 'Can you come back later? I just want to relax right now.'] => 'Kannst du später wiederkommen? Ich will mich gerade nur entspannen.',
    ['Elaine', 'SWIMMERGRIL', 'winSpeech', 'Thanks. Just a few more minutes of rest...'] => 'Danke. Nur noch ein paar Minuten ausruhen...',
    ['Elaine', 'SWIMMERGRIL', 'loseSpeech', 'Well, I\'m all riled up now!'] => 'Na toll, jetzt bin ich hellwach!',
    ['Joyce', 'SWIMMERGRIL', 'introSpeech', 'I want to be a Primarina when I grow up!'] => 'Wenn ich groß bin, will ich eine Primarene sein!',
    ['Joyce', 'SWIMMERGRIL', 'winSpeech', 'You la-la-la looooooost!'] => 'Du hast la-la-la verlooooren!',
    ['Joyce', 'SWIMMERGRIL', 'loseSpeech', 'Tra la la.... I looooooost!'] => 'Tra-la-la... ich ha-ha-be verlooooren!',
    ['Todd', 'PoliceOfficer', 'introSpeech', 'Why can\'t I find any good cafes?'] => 'Warum finde ich keine guten Cafés?',
    ['Todd', 'PoliceOfficer', 'winSpeech', 'Maybe I\'ll treat myself to Spyce tonight.'] => 'Vielleicht gönn ich mir heute Abend was bei Spyce.',
    ['Todd', 'PoliceOfficer', 'loseSpeech', 'Hey, kid, do you know if Mika\'s Coffee has a branch here?'] => 'Hey, Kleiner, weißt du, ob Mika\'s Coffee hier eine Filiale hat?',
    ['Gavin', 'PoliceOfficer', 'introSpeech', 'This is nice. Just some good music and a few battles.'] => 'Schön hier. Gute Musik und ein paar Kämpfe.',
    ['Gavin', 'PoliceOfficer', 'winSpeech', 'So much better than when I was stationed in Beryl!'] => 'Viel besser als damals, als ich in Beryl stationiert war!',
    ['Gavin', 'PoliceOfficer', 'loseSpeech', 'Losing doesn\'t get any easier, though!'] => 'Verlieren wird trotzdem nicht leichter!',
    ['Malory', 'COOLTRAINER_Female', 'introSpeech', 'Hey guuuys, we\'re live from the Reborn region! Just about to have a battle in the famous Reborn Nightclub! Wish me luck!'] => 'Hey, Leuteee, wir sind live aus der Reborn-Region! Gleich kämpfe ich im berühmten Nachtclub von Reborn! Drückt mir die Daumen!',
    ['Malory', 'COOLTRAINER_Female', 'winSpeech', 'Another win for MaloryMoo92! Thanks to all my watchers for supporting me~!'] => 'Noch ein Sieg für MaloryMoo92! Danke an alle Zuschauer für eure Unterstützung~!',
    ['Malory', 'COOLTRAINER_Female', 'loseSpeech', 'Hey, you were awesome! Can I get a quote for all my watchers?'] => 'Hey, du warst echt klasse! Hast du einen Spruch für meine Zuschauer?',
    ['Esther', 'COOLTRAINER_Female', 'introSpeech', 'It\'s my birthday today!'] => 'Heute hab ich Geburtstag!',
    ['Esther', 'COOLTRAINER_Female', 'winSpeech', 'A win is a nice enough present!'] => 'Ein Sieg ist doch ein nettes Geschenk!',
    ['Esther', 'COOLTRAINER_Female', 'loseSpeech', 'It\'s my birthday but I have to give you money...'] => 'Ich hab Geburtstag und muss dir trotzdem Geld geben...',
    ['Oscar', 'AQUA2', 'introSpeech', 'Ugh... Do we have to do this?'] => 'Ugh... Müssen wir das echt machen?',
    ['Oscar', 'AQUA2', 'winSpeech', 'Haha! Is that all you got?'] => 'Haha! War das schon alles?',
    ['Oscar', 'AQUA2', 'loseSpeech', 'Another loss... Figures'] => 'Schon wieder verloren... War ja klar.',
    ['Wilson', 'AQUA2', 'introSpeech', 'Get ready. I ain\'t here to play ball.'] => 'Mach dich bereit. Ich bin nicht hier, um Ball zu spielen.',
    ['Wilson', 'AQUA2', 'winSpeech', 'Told you.'] => 'Hab ich doch gesagt.',
    ['Wilson', 'AQUA2', 'loseSpeech', '\'Pparently I was the one who wasn\'t ready! '] => 'Offenbar war ich derjenige, der nicht bereit war! ',
    ['Clare', 'Doxy', 'introSpeech', 'Oooh, you look tough!'] => 'Oooh, du siehst stark aus!',
    ['Clare', 'Doxy', 'winSpeech', 'I hate when I\'m wrong...'] => 'Ich hasse es, wenn ich mich irre...',
    ['Clare', 'Doxy', 'loseSpeech', 'You were super tough! Can I get your autograph?'] => 'Du warst super stark! Krieg ich ein Autogramm?',
    ['Tess', 'Doxy', 'introSpeech', 'I make Pokemon keychains. If you win, I\'ll give you a free customized keychain!'] => 'Ich mache Pokémon-Schlüsselanhänger. Wenn du gewinnst, schenke ich dir einen nach Wunsch!',
    ['Tess', 'Doxy', 'winSpeech', 'Better luck next time! You should still check out my shop when I open it, though!'] => 'Vielleicht klappt\'s nächstes Mal! Schau trotzdem in meinem Laden vorbei, wenn er öffnet!',
    ['Tess', 'Doxy', 'loseSpeech', 'That was great! Okay, so let\'s get your contact info for that commission...'] => 'Das war toll! Also, gib mir mal deine Kontaktdaten für den Auftrag...',
    ['Leon', 'POACHERM', 'introSpeech', 'I don\'t care what those numbskulls say, I\'m the best trainer here.'] => 'Mir egal, was diese Hohlköpfe sagen, ich bin hier der beste Trainer.',
    ['Leon', 'POACHERM', 'winSpeech', 'Nothing can hold me down!'] => 'Nichts kann mich unterkriegen!',
    ['Leon', 'POACHERM', 'loseSpeech', 'Maybe they had a point. Hey, Mom, Dad, I\'m sorry for callin\' you numbskulls!'] => 'Vielleicht hatten sie recht. Hey, Mom, Dad, tut mir leid, dass ich euch Hohlköpfe genannt hab!',
    ['Melih', 'POACHERM', 'introSpeech', 'Man, this is the life!'] => 'Mann, das ist das Leben!',
    ['Melih', 'POACHERM', 'winSpeech', 'Haha, that sad face looks good on you!'] => 'Haha, dein trauriges Gesicht steht dir gut!',
    ['Melih', 'POACHERM', 'loseSpeech', 'Even losin\'s not so bad here!'] => 'Selbst Verlieren ist hier gar nicht so schlimm!',
    ['Vince', 'AceTrainerM', 'introSpeech', 'Let\'s crash this party!'] => 'Lass uns die Party crashen!',
    ['Vince', 'AceTrainerM', 'winSpeech', 'Let\'s keep the party going!'] => 'Feiern wir weiter!',
    ['Vince', 'AceTrainerM', 'loseSpeech', 'Man, why d\'you have to be such a party pooper?'] => 'Mann, warum musst du so ein Spielverderber sein?',
    ['Bryon', 'AceTrainerM', 'introSpeech', 'So if Swift has 60 base power, and I factor in- wait, I\'m not ready yet!'] => 'Wenn Sternschauer eine Stärke von 60 hat und ich noch einberechne—Moment, ich bin noch nicht bereit!',
    ['Bryon', 'AceTrainerM', 'winSpeech', 'I\'m learning!'] => 'Ich lerne dazu!',
    ['Bryon', 'AceTrainerM', 'loseSpeech', 'My calculations were wrong...'] => 'Meine Berechnungen waren falsch...',
    ['Ava', 'POACHERF', 'introSpeech', 'I am a treasure of this world!'] => 'Ich bin ein Schatz dieser Welt!',
    ['Ava', 'POACHERF', 'winSpeech', 'I am positively peerless!'] => 'Ich bin einfach unübertroffen!',
    ['Ava', 'POACHERF', 'loseSpeech', 'How could you treat me this way!? '] => 'Wie kannst du mich nur so behandeln!? ',
    ['Miriam', 'POACHERF', 'introSpeech', 'Why are you looking at me that way?'] => 'Warum schaust du mich so an?',
    ['Miriam', 'POACHERF', 'winSpeech', 'Quit with that look!'] => 'Hör auf, so zu gucken!',
    ['Miriam', 'POACHERF', 'loseSpeech', 'Your gaze is unnerving...'] => 'Dein Blick ist unheimlich...',
    ['Carrie', 'AceTrainerF', 'introSpeech', 'Please don\'t shout at me...'] => 'Bitte schrei mich nicht an...',
    ['Carrie', 'AceTrainerF', 'winSpeech', 'Thank you for a nice battle...'] => 'Danke für den netten Kampf...',
    ['Carrie', 'AceTrainerF', 'loseSpeech', 'YOU JERK-- oops, I shouted...'] => 'DU IDIOT—ups, ich hab geschrien...',
    ['Lilly', 'AceTrainerF', 'introSpeech', 'The trainers here have been boring me. Are you more interesting?'] => 'Die Trainer hier langweilen mich. Bist du interessanter?',
    ['Lilly', 'AceTrainerF', 'winSpeech', 'Yawn. Still bored!'] => 'Gähn. Immer noch langweilig!',
    ['Lilly', 'AceTrainerF', 'loseSpeech', 'Definitely not boring! Maybe a little too much!'] => 'Definitiv nicht langweilig! Vielleicht sogar ein bisschen zu sehr!',
    ['Joey', 'Orderly', 'introSpeech', 'Don\'t let your wins make you comfortable. '] => 'Lass dich von deinen Siegen nicht in Sicherheit wiegen. ',
    ['Joey', 'Orderly', 'winSpeech', 'Battles here are easy to win!'] => 'Kämpfe gewinnt man hier leicht!',
    ['Joey', 'Orderly', 'loseSpeech', 'Clearly, there\'s no shortage of skill here!'] => 'An Können mangelt\'s hier offenbar nicht!',
    ['Chaz', 'Orderly', 'introSpeech', 'I hate cleaning, but the battling\'s not so bad. '] => 'Putzen hasse ich, aber Kämpfen ist ganz okay. ',
    ['Chaz', 'Orderly', 'winSpeech', 'Heck yeah! '] => 'Oh ja! ',
    ['Chaz', 'Orderly', 'loseSpeech', 'Did you have to win so fast? Now I have to go back to cleaning...'] => 'Musste dein Sieg so schnell kommen? Jetzt muss ich wieder putzen...',
    ['Nelson', 'Orderly', 'introSpeech', 'All right, let\'s keep it going!'] => 'Na los, weiter geht\'s!',
    ['Nelson', 'Orderly', 'winSpeech', 'Oh hey, I did it. Good battle, kid. '] => 'Oh, hey, ich hab\'s geschafft. Guter Kampf, Kleiner. ',
    ['Nelson', 'Orderly', 'loseSpeech', 'Eh. I\'d better go check on that lazy Chaz...'] => 'Hm. Ich sollte mal nach dem faulen Chaz sehen...',
    ['Shania', 'OrderlyF', 'introSpeech', 'You think you\'re special?'] => 'Du glaubst, du bist was Besonderes?',
    ['Shania', 'OrderlyF', 'winSpeech', 'That didn\'t impress me much.'] => 'Das hat mich nicht sonderlich beeindruckt.',
    ['Shania', 'OrderlyF', 'loseSpeech', 'You\'re something else!'] => 'Du bist echt nicht ohne!',
    ['Stella', 'OrderlyF', 'introSpeech', 'Have you ever been to Unova?'] => 'Warst du schon mal in Einall?',
    ['Stella', 'OrderlyF', 'winSpeech', 'You should go! '] => 'Da solltest du mal hin! ',
    ['Stella', 'OrderlyF', 'loseSpeech', 'You\'re sure stronger than the trainers there...'] => 'Du bist bestimmt stärker als die Trainer dort...',
    ['Dorine', 'OrderlyF', 'introSpeech', 'Let\'s all sing a happy battling song!'] => 'Singen wir alle ein fröhliches Kampflied!',
    ['Dorine', 'OrderlyF', 'winSpeech', 'We\'re finishing our happy battling song!'] => 'Wir singen unser fröhliches Kampflied zu Ende!',
    ['Dorine', 'OrderlyF', 'loseSpeech', 'B-but you were singing off key! '] => 'A-aber du hast schief gesungen! ',
    ['Maddox', 'MAGMA1', 'introSpeech', 'By the time I\'m finished with you, you\'ll never want to battle again!'] => 'Wenn ich mit dir fertig bin, willst du nie wieder kämpfen!',
    ['Maddox', 'MAGMA1', 'winSpeech', 'I will reign supreme!'] => 'Ich werde herrschen!',
    ['Maddox', 'MAGMA1', 'loseSpeech', 'Didn\'t buy it, huh? Ah well.'] => 'Du hast es mir nicht abgekauft, was? Na ja.',
    ['Davin', 'MAGMA1', 'introSpeech', 'Even now that the city\'s doin\' better, it\'s hard to find strong Pokemon here.'] => 'Selbst jetzt, wo es der Stadt besser geht, ist es schwer, hier starke Pokémon zu finden.',
    ['Davin', 'MAGMA1', 'winSpeech', 'Like, why aren\'t there any Salamence or Hydreigon in the city?'] => 'Also echt, warum gibt\'s in der Stadt keine Brutalanda oder Trikephalo?',
    ['Davin', 'MAGMA1', 'loseSpeech', 'Where\'d you get that team!?'] => 'Wo hast du bitte dieses Team her!?',
    ['Trevon', 'MAGMA1', 'introSpeech', 'Hey! Have you heard about our Lord and Savior Groudon today?'] => 'Hey! Hast du heute schon von unserem Herrn und Erlöser Groudon gehört?',
    ['Trevon', 'MAGMA1', 'winSpeech', 'It made the land! It made me strong!'] => 'Es hat das Land erschaffen! Es hat mich stark gemacht!',
    ['Trevon', 'MAGMA1', 'loseSpeech', 'Okay, okay, I\'m leaving!'] => 'Schon gut, schon gut, ich geh ja!',
    ['Mateo', 'BLACKBELT', 'introSpeech', 'This won\'t take long...'] => 'Das dauert nicht lang ...',
    ['Mateo', 'BLACKBELT', 'winSpeech', 'Easy. '] => 'Ein Kinderspiel.',
    ['Mateo', 'BLACKBELT', 'loseSpeech', '...Well, I wasn\'t wrong!'] => '... Na ja, ich lag nicht falsch!',
    ['Bret', 'BLACKBELT', 'introSpeech', 'Y\'know what bothers me about being a Blackbelt?'] => 'Weißt du, was mich daran stört, Schwarzgurt zu sein?',
    ['Bret', 'BLACKBELT', 'winSpeech', 'I just don\'t get why the strongest rank has the dullest belt!'] => 'Ich versteh einfach nicht, warum der höchste Rang den langweiligsten Gürtel hat!',
    ['Bret', 'BLACKBELT', 'loseSpeech', 'Well, losing, for one thing...'] => 'Na ja, zum Beispiel zu verlieren ...',
    ['Raul', 'BLACKBELT', 'introSpeech', 'You\'re safe... Nothing can harm you...'] => 'Du bist in Sicherheit ... Nichts kann dir etwas anhaben ...',
    ['Raul', 'BLACKBELT', 'winSpeech', 'Get stronger! That\'s all I ask before you challenge me again.'] => 'Werd stärker! Mehr verlange ich nicht, bevor du mich wieder herausforderst.',
    ['Raul', 'BLACKBELT', 'loseSpeech', 'I guess I should forget these wide-eyed dreams of winning...'] => 'Ich sollte wohl diese naiven Träume vom Sieg vergessen ...',
    ['Kay', 'BATTLEGIRL', 'introSpeech', 'Man, this is a lot of battles...'] => 'Mann, das sind ganz schön viele Kämpfe ...',
    ['Kay', 'BATTLEGIRL', 'winSpeech', 'I\'m tired, but it feels good!'] => 'Ich bin müde, aber es fühlt sich gut an!',
    ['Kay', 'BATTLEGIRL', 'loseSpeech', 'Victoria sending us here was brutal!'] => 'Dass Victoria uns hierhergeschickt hat, war echt brutal!',
    ['Mimi', 'BATTLEGIRL', 'introSpeech', 'Get out of the way, please.'] => 'Geh bitte aus dem Weg.',
    ['Mimi', 'BATTLEGIRL', 'winSpeech', 'Merci for letting me through.'] => 'Merci, dass du mich durchgelassen hast.',
    ['Mimi', 'BATTLEGIRL', 'loseSpeech', 'You defeat Mimi? You toss her Pokemon away!? Jail for Trainer!'] => 'Du besiegst Mimi? Du wirfst ihre Pokémon weg!? Ab ins Gefängnis mit Trainer!',
    ['Alana', 'BATTLEGIRL', 'introSpeech', 'I am the Striking Pyroar...'] => 'Ich bin das schlagkräftige Pyroleo ...',
    ['Alana', 'BATTLEGIRL', 'winSpeech', 'Feel my blazing conviction!'] => 'Spür meine lodernde Entschlossenheit!',
    ['Alana', 'BATTLEGIRL', 'loseSpeech', 'You must be the Charging Lapras...'] => 'Du musst das stürmische Lapras sein ...',
    ['Alexas', 'PoliceOfficer', 'introSpeech', 'Ah, a youngster! Good to meet you, young Trainer!'] => 'Ah, ein Jungspund! Freut mich, dich kennenzulernen, junger Trainer!',
    ['Alexas', 'PoliceOfficer', 'winSpeech', 'That was a fine showing!'] => 'Das war eine starke Vorstellung!',
    ['Alexas', 'PoliceOfficer', 'loseSpeech', 'Have you considered a job in law enforcement? '] => 'Schon mal über einen Job bei der Polizei nachgedacht?',
    ['Weston', 'PoliceOfficer', 'introSpeech', 'Hey, buddy... You seen my Growlithe?'] => 'Hey, Kumpel ... Hast du mein Fukano gesehen?',
    ['Weston', 'PoliceOfficer', 'winSpeech', ' No? Okay, thanks anyway. '] => 'Nein? Na gut, trotzdem danke.',
    ['Weston', 'PoliceOfficer', 'loseSpeech', 'He hates when I don\'t let him battle... Kerry, here boy!'] => 'Er hasst es, wenn ich ihn nicht kämpfen lasse ... Kerry, hierher, Junge!',
    ['Monroe', 'PoliceOfficer', 'introSpeech', 'Don\'t you look at me like that! I know you think I\'m an old man! Well, I\'ve got news for you!'] => 'Sieh mich nicht so an! Ich weiß, du hältst mich für einen alten Mann! Aber ich hab Neuigkeiten für dich!',
    ['Monroe', 'PoliceOfficer', 'winSpeech', 'I\'m not old! I\'m a seasoned veteran!'] => 'Ich bin nicht alt! Ich bin ein erfahrener Veteran!',
    ['Monroe', 'PoliceOfficer', 'loseSpeech', '...Maybe I am too old for this. '] => '... Vielleicht bin ich wirklich zu alt für sowas.',
    ['Nadia', 'NatureGirl', 'introSpeech', 'You know Adrienn, right? Do you think you could get a message to xem?'] => 'Du kennst Adrienn, oder? Könntest du xem eine Nachricht ausrichten?',
    ['Nadia', 'NatureGirl', 'winSpeech', 'Let xem know I really appreciate xyr work. This place finally feels like home again. '] => 'Sag xem, wie sehr ich xyr Arbeit schätze. Hier fühlt es sich endlich wieder wie ein Zuhause an.',
    ['Nadia', 'NatureGirl', 'loseSpeech', 'I wanted to send a thank you note for all xe\'s done to restore the city!'] => 'Ich wollte Adrienn eine Dankeskarte schicken, für all die Arbeit am Wiederaufbau der Stadt!',
    ['Miranda', 'NatureGirl', 'introSpeech', 'Let me find happiness through this battle!'] => 'Lass mich in diesem Kampf mein Glück finden!',
    ['Miranda', 'NatureGirl', 'winSpeech', 'You\'ll be okay. In time you\'ll learn how to lose with grace. '] => 'Schon gut. Mit der Zeit lernst du, mit Würde zu verlieren.',
    ['Miranda', 'NatureGirl', 'loseSpeech', 'There\'s just no telling how far you\'ll go to win!'] => 'Wer weiß schon, wie weit du gehen würdest, um zu gewinnen!',
    ['Emma', 'NatureGirl', 'introSpeech', 'Hey, what\'s with the long face?'] => 'Hey, warum ziehst du so ein langes Gesicht?',
    ['Emma', 'NatureGirl', 'winSpeech', 'Try not to worry about it too much, okay?'] => 'Mach dir nicht zu viele Sorgen, okay?',
    ['Emma', 'NatureGirl', 'loseSpeech', 'I want to sing a song of sorrow now...'] => 'Jetzt möchte ich ein trauriges Lied singen ...',
    ['Rolando', 'PSYCHIC_Male', 'introSpeech', 'It is I, Roserade Mask!'] => 'Ich bin\'s, die Roserade-Maske!',
    ['Rolando', 'PSYCHIC_Male', 'winSpeech', 'My work here is finished!'] => 'Meine Arbeit hier ist getan!',
    ['Rolando', 'PSYCHIC_Male', 'loseSpeech', 'But I didn\'t even get to do anything!'] => 'Aber ich bin ja gar nicht dazu gekommen, etwas zu tun!',
    ['Stanly', 'PSYCHIC_Male', 'introSpeech', 'Let me read your aura...'] => 'Lass mich deine Aura lesen ...',
    ['Stanly', 'PSYCHIC_Male', 'winSpeech', 'Your aura is as green as you are!'] => 'Deine Aura ist so grün wie du!',
    ['Stanly', 'PSYCHIC_Male', 'loseSpeech', 'I\'ve never seen such an aura before!'] => 'So eine Aura habe ich noch nie gesehen!',
    ['Dario', 'PSYCHIC_Male', 'introSpeech', 'There is no such thing as luck! I win with pure skill! '] => 'Glück gibt\'s nicht! Ich siege allein mit Können!',
    ['Dario', 'PSYCHIC_Male', 'winSpeech', 'And now we see who\'s the more skilled!'] => 'Jetzt sehen wir, wer von uns mehr draufhat!',
    ['Dario', 'PSYCHIC_Male', 'loseSpeech', 'Psh. You got lucky. '] => 'Pff. Du hattest einfach Glück.',
    ['Karlee', 'PSYCHIC_Female', 'introSpeech', 'I have a feeling I\'m about to win!'] => 'Ich hab so ein Gefühl, dass ich gleich gewinne!',
    ['Karlee', 'PSYCHIC_Female', 'winSpeech', 'Don\'t take it too hard. I\'ve never been wrong before!'] => 'Nimm\'s nicht so schwer. Ich lag noch nie falsch!',
    ['Karlee', 'PSYCHIC_Female', 'loseSpeech', 'W-what? But my intuition...'] => 'W-was? Aber meine Intuition ...',
    ['Jaylin', 'PSYCHIC_Female', 'introSpeech', 'Please impress me. '] => 'Beeindruck mich bitte.',
    ['Jaylin', 'PSYCHIC_Female', 'winSpeech', 'Another one too weak...'] => 'Schon wieder einer zu schwach ...',
    ['Jaylin', 'PSYCHIC_Female', 'loseSpeech', 'You\'ve certainly got what it takes...'] => 'Du hast definitiv das Zeug dazu ...',
    ['Ingrid', 'PSYCHIC_Female', 'introSpeech', 'Are you ready to lose?'] => 'Bist du bereit zu verlieren?',
    ['Ingrid', 'PSYCHIC_Female', 'winSpeech', 'You\'ll see me in your dreams!'] => 'Du wirst mir in deinen Träumen begegnen!',
    ['Ingrid', 'PSYCHIC_Female', 'loseSpeech', 'You went overboard...'] => 'Du hast es übertrieben ...',
    ['Delilah', 'CultistF', 'introSpeech', 'Hey there!'] => 'Na, hallo!',
    ['Delilah', 'CultistF', 'winSpeech', 'Definitely not the one.'] => 'Ganz sicher nicht die gesuchte Person.',
    ['Delilah', 'CultistF', 'loseSpeech', 'No, you\'re not the one...'] => 'Nein, du bist es nicht ...',
    ['Carly', 'CultistF', 'introSpeech', 'Hey, you know where a gal can get a Soda Pop around here?'] => 'Hey, weißt du, wo man hier \'nen Sprudel kriegt?',
    ['Carly', 'CultistF', 'winSpeech', 'Never mind, never mind.'] => 'Schon gut, schon gut.',
    ['Carly', 'CultistF', 'loseSpeech', 'I\'m really thirsty!'] => 'Ich hab echt Durst!',
    ['Lexie', 'CultistF', 'introSpeech', 'Take a look at my cute Pokemon!'] => 'Sieh dir mal meine süßen Pokémon an!',
    ['Lexie', 'CultistF', 'winSpeech', 'Weren\'t they adorable?'] => 'Waren sie nicht zum Knuddeln?',
    ['Lexie', 'CultistF', 'loseSpeech', 'What do you mean they\'re not cute!? Shows how much you know!'] => 'Was heißt hier, sie sind nicht süß!? Du hast ja keine Ahnung!',
    ['Miller', 'Cultist', 'introSpeech', 'Just act like everything\'s normal, okay? Now, have you run into a cultist named Marv?'] => 'Tu einfach so, als wäre alles normal, okay? Sag mal, ist dir ein Kultist namens Marv begegnet?',
    ['Miller', 'Cultist', 'winSpeech', 'He\'s wanted for stealing large quantities of Pecha Berries...'] => 'Er wird gesucht, weil er große Mengen Pirsifbeeren gestohlen hat ...',
    ['Miller', 'Cultist', 'loseSpeech', 'It\'s fine. Don\'t worry about it. '] => 'Schon okay. Mach dir keinen Kopf.',
    ['Marv', 'Cultist', 'introSpeech', 'Y-you haven\'t seen any coppers around here, have you?'] => 'D-du hast hier doch keine Bullen gesehen, oder?',
    ['Marv', 'Cultist', 'winSpeech', 'Phew. '] => 'Puh.',
    ['Marv', 'Cultist', 'loseSpeech', 'No reason!!'] => 'Kein Grund!!',
    ['Layton', 'Cultist', 'introSpeech', 'I\'ve always loved battling...'] => 'Kämpfe haben mir schon immer gefallen ...',
    ['Layton', 'Cultist', 'winSpeech', 'Well done, really!'] => 'Wirklich gut gemacht!',
    ['Layton', 'Cultist', 'loseSpeech', 'A battle is an exquisite puzzle, is it not?'] => 'Ein Kampf ist ein kunstvolles Rätsel, nicht wahr?',
    ['Payson', 'GENTLEMAN', 'introSpeech', 'Battles are best when you go in without expectation.'] => 'Kämpfe sind am besten, wenn man ohne Erwartungen hineingeht.',
    ['Payson', 'GENTLEMAN', 'winSpeech', 'You must expect the unexpected, my friend. '] => 'Du musst mit dem Unerwarteten rechnen, mein Freund.',
    ['Payson', 'GENTLEMAN', 'loseSpeech', 'If you do not expect to win, a loss won\'t set you back much.'] => 'Wenn du nicht mit einem Sieg rechnest, wirft dich eine Niederlage nicht so sehr zurück.',
    ['Gregory', 'GENTLEMAN', 'introSpeech', 'I may appear frail... '] => 'Ich wirke vielleicht gebrechlich ...',
    ['Gregory', 'GENTLEMAN', 'winSpeech', 'Never underestimate Gregory!'] => 'Unterschätz Gregory niemals!',
    ['Gregory', 'GENTLEMAN', 'loseSpeech', 'All I need is a bit more time...'] => 'Ich brauch nur noch ein bisschen Zeit ...',
    ['Reese', 'GENTLEMAN', 'introSpeech', 'Now watch how a sweet ol\' fella like me battles!'] => 'Jetzt sieh dir mal an, wie so ein alter Charmeur wie ich kämpft!',
    ['Reese', 'GENTLEMAN', 'winSpeech', 'That battle was a treat!'] => 'Der Kampf war ein Genuss!',
    ['Reese', 'GENTLEMAN', 'loseSpeech', 'I\'m falling to pieces...'] => 'Ich zerfalle in Einzelteile ...',
    ['Mason', 'MAGMA2', 'introSpeech', 'I\'m up for a promotion. Would you mind sparring with me as practice?'] => 'Ich soll befördert werden. Würdest du zum Üben mit mir kämpfen?',
    ['Mason', 'MAGMA2', 'winSpeech', 'Thanks! I\'ll get that promotion for sure!'] => 'Danke! Die Beförderung ist mir sicher!',
    ['Mason', 'MAGMA2', 'loseSpeech', 'That was jarring...'] => 'Das war ganz schön erschütternd ...',
    ['Toby', 'MAGMA2', 'introSpeech', 'I\'m tall, right? D\'you think I can pass for an adult?'] => 'Ich bin groß, oder? Könnte ich als Erwachsener durchgehen?',
    ['Toby', 'MAGMA2', 'winSpeech', 'Hah! You got beaten by a kid!'] => 'Ha! Du wurdest von einem Kind besiegt!',
    ['Toby', 'MAGMA2', 'loseSpeech', 'This is so unfair! I\'m telling...'] => 'Das ist so unfair! Ich sag\'s ...',
    ['Dorothy', 'BEAUTY', 'introSpeech', 'I don\'t think I\'m in Pastoria anymore...'] => 'Ich glaube, ich bin nicht mehr in Weideburg ...',
    ['Dorothy', 'BEAUTY', 'winSpeech', 'The way to win was with me all along! It was you, my darling Pokemon!'] => 'Der Schlüssel zum Sieg war die ganze Zeit bei mir! Ihr wart es, meine lieben Pokémon!',
    ['Dorothy', 'BEAUTY', 'loseSpeech', 'The Trainers here are so strong! You must have a rainbow of badges!'] => 'Die Trainer hier sind so stark! Du musst einen ganzen Regenbogen an Orden haben!',
    ['Piper', 'LADY', 'introSpeech', 'Have you any interest in stargazing?'] => 'Hast du Interesse daran, Sterne zu beobachten?',
    ['Piper', 'LADY', 'winSpeech', 'The finest place I\'ve found is Teknite Ridge!'] => 'Der beste Ort, den ich gefunden habe, ist Teknite Ridge!',
    ['Piper', 'LADY', 'loseSpeech', 'Clearly, I\'m gazing at a star right now!'] => 'Offensichtlich schaue ich gerade einen Stern an!',
    ['Finn', 'EXPERT_Male', 'introSpeech', 'Let\'s just make this quick. I have a train to catch.'] => 'Machen wir\'s schnell. Ich muss meinen Zug erwischen.',
    ['Finn', 'EXPERT_Male', 'winSpeech', 'Good, thank you.'] => 'Gut, danke.',
    ['Finn', 'EXPERT_Male', 'loseSpeech', 'Perhaps I could stick around a while after all.'] => 'Vielleicht bleib ich doch noch eine Weile.',
    ['Sameer', 'SWIMMERBOI', 'introSpeech', 'I\'m at the top of my class in swimming and battles!'] => 'Ich bin in Schwimmen und Kämpfen Klassenbester!',
    ['Sameer', 'SWIMMERBOI', 'winSpeech', 'You\'re pretty good, though! Nice form!'] => 'Du bist aber ziemlich gut! Tolle Technik!',
    ['Sameer', 'SWIMMERBOI', 'loseSpeech', 'Man, I\'m glad you\'re not in my class...'] => 'Mann, bin ich froh, dass du nicht in meiner Klasse bist ...',
    ['Fiona', 'SWIMMERGRIL', 'introSpeech', 'So you\'re the one they think can defeat me? All right, give me your best. '] => 'Also, du bist die Person, von der alle glauben, dass sie mich besiegen kann? Na gut, zeig, was du draufhast.',
    ['Fiona', 'SWIMMERGRIL', 'winSpeech', 'Another weakling... No offense.'] => 'Schon wieder ein Schwächling ... Nicht böse gemeint.',
    ['Fiona', 'SWIMMERGRIL', 'loseSpeech', 'What kind of Trainer are you?!'] => 'Was bist du denn für ein Trainer?!',
    ['Gloria', 'SWIMMERGRIL', 'introSpeech', 'Ohmigosh! I\'m your number one fan! '] => 'Oh mein Gott! Ich bin dein allergrößter Fan!',
    ['Gloria', 'SWIMMERGRIL', 'winSpeech', 'I- did I really win?'] => 'I-ich hab wirklich gewonnen?',
    ['Gloria', 'SWIMMERGRIL', 'loseSpeech', 'I got defeated by the Champion themself... this is the best day of my life...'] => 'Ich wurde vom Champ höchstpersönlich besiegt ... Das ist der beste Tag meines Lebens ...',
    ['Nico', 'CUEBALL', 'introSpeech', 'Well, well, well. What d\'you think my odds are of beating you?'] => 'Na, na, na. Wie stehen wohl meine Chancen, dich zu schlagen?',
    ['Nico', 'CUEBALL', 'winSpeech', 'Every now and then, someone beats the odds. '] => 'Ab und zu schlägt jemand allen Chancen ein Schnippchen.',
    ['Nico', 'CUEBALL', 'loseSpeech', 'Nyeh. The odds were stacked against me anyway.'] => 'Nyeh. Die Chancen standen sowieso gegen mich.',
    ['Jeremy', 'CUEBALL', 'introSpeech', 'I keep perfect time, each day!'] => 'Ich halte jeden Tag die Zeit perfekt ein!',
    ['Jeremy', 'CUEBALL', 'winSpeech', 'There\'s exactly twelve minutes until my next battle...'] => 'Bis zu meinem nächsten Kampf sind es genau zwölf Minuten ...',
    ['Jeremy', 'CUEBALL', 'loseSpeech', 'My defeat took forty-seven seconds less than I predicted...'] => 'Meine Niederlage dauerte siebenundvierzig Sekunden weniger als vorhergesagt ...',
    ['Caitlin', 'COOLTRAINER_Female', 'introSpeech', 'I\'m writing a book! Try and give me some good inspiration.'] => 'Ich schreibe ein Buch! Gib mir etwas Inspiration.',
    ['Caitlin', 'COOLTRAINER_Female', 'winSpeech', 'Hmm... A sudden fateful meeting for the hero, maybe?'] => 'Hm ... Vielleicht eine schicksalhafte Begegnung für den Helden?',
    ['Caitlin', 'COOLTRAINER_Female', 'loseSpeech', 'Yes, that\'s perfect! I know just what to write next!'] => 'Ja, perfekt! Ich weiß genau, was ich als Nächstes schreibe!',
    ['Reena', 'COOLTRAINER_Female', 'introSpeech', 'I\'m training in Pokemon first aid. Let me take a look at your Pokemon for you.'] => 'Ich lerne Pokémon-Erste-Hilfe. Lass mich deine Pokémon mal ansehen.',
    ['Reena', 'COOLTRAINER_Female', 'winSpeech', 'Well, they were fine before my Pokemon beat them all up...'] => 'Na ja, ihnen ging\'s gut, bevor meine Pokémon sie vermöbelt haben ...',
    ['Reena', 'COOLTRAINER_Female', 'loseSpeech', 'They\'re definitely all in top battling shape!'] => 'Sie sind definitiv alle in bester Kampfform!',
    ['Avery', 'StreetRat', 'introSpeech', 'Personally, I don\'t think Flying-types should even be allowed in here!'] => 'Ich finde, Flug-Pokémon sollten hier gar nicht erst erlaubt sein!',
    ['Avery', 'StreetRat', 'winSpeech', 'My Bugs can defeat even the most vicious of them!'] => 'Meine Käfer können selbst die wildesten von ihnen besiegen!',
    ['Avery', 'StreetRat', 'loseSpeech', 'They moult, they screech, and they frighten my precious Bugs!'] => 'Sie mausern sich, kreischen und erschrecken meine geliebten Käfer!',
    ['Liam', 'StreetRat', 'introSpeech', 'Say... You\'re not looking so hot.'] => 'Sag mal ... Du siehst nicht gerade gut aus.',
    ['Liam', 'StreetRat', 'winSpeech', 'You might want to take a break, hey?'] => 'Vielleicht solltest du eine Pause machen, hm?',
    ['Liam', 'StreetRat', 'loseSpeech', 'Appearances aren\'t everything, I guess...'] => 'Aufs Aussehen kommt\'s wohl nicht immer an ...',
    ['Theo', 'FISHERMAN', 'introSpeech', 'Care to cast your line?'] => 'Willst du deine Angel auswerfen?',
    ['Theo', 'FISHERMAN', 'winSpeech', 'I lured that victory to me, easy!'] => 'Den Sieg hab ich ganz leicht an Land gezogen!',
    ['Theo', 'FISHERMAN', 'loseSpeech', 'I won\'t be so easily baited next time!'] => 'Nächstes Mal geh ich nicht so leicht an den Haken!',
    ['Bailey', 'FISHERMAN', 'introSpeech', 'You ever been to Hoppy Town?'] => 'Warst du schon mal in Hoppy Town?',
    ['Bailey', 'FISHERMAN', 'winSpeech', 'You\'d be surprised what a lifetime of Jump tourneys can prepare ya for!'] => 'Du wärst überrascht, worauf dich ein Leben voller Sprungturniere vorbereiten kann!',
    ['Bailey', 'FISHERMAN', 'loseSpeech', 'We\'re not much for battle, but you\'ve never seen prettier Pokemon!'] => 'Kämpfen ist nicht so unser Ding, aber schönere Pokémon hast du noch nie gesehen!',
    ['Hugo', 'KNIGHT', 'introSpeech', 'Before we battle, let us set the stage!'] => 'Bevor wir kämpfen, lass uns die Bühne bereiten!',
    ['Hugo', 'KNIGHT', 'winSpeech', 'This unassuming bard takes home the prize!'] => 'Dieser unscheinbare Barde nimmt den Preis mit nach Hause!',
    ['Hugo', 'KNIGHT', 'loseSpeech', 'A well-intended loss is not a shame.'] => 'Mit guter Absicht zu verlieren, ist keine Schande.',
    ['Knight', 'KNIGHT', 'introSpeech', 'I hereby declare this day open.'] => 'Hiermit erkläre ich diesen Tag für eröffnet.',
    ['Knight', 'KNIGHT', 'winSpeech', 'I hereby declare you closed.'] => 'Hiermit erkläre ich dich für erledigt.',
    ['Knight', 'KNIGHT', 'loseSpeech', 'I hereby declare this day closed.'] => 'Hiermit erkläre ich diesen Tag für beendet.',
    ['Bryce', 'KNIGHT', 'introSpeech', 'Do you know where a man can find a Pokemon spa?'] => 'Weißt du, wo man ein Pokémon-Wellnessbad findet?',
    ['Bryce', 'KNIGHT', 'winSpeech', 'I must find a place for my dear partner to relax!'] => 'Ich muss einen Ort finden, an dem sich mein lieber Partner entspannen kann!',
    ['Bryce', 'KNIGHT', 'loseSpeech', 'There are two, and close to here? Many thanks!'] => 'Gleich zwei, und ganz in der Nähe? Vielen Dank!',
    ['Gideon', 'PoliceOfficer', 'introSpeech', 'How do you do, fellow youth?'] => 'Wie geht\'s, werte Jugend?',
    ['Gideon', 'PoliceOfficer', 'winSpeech', 'I am the hopscotch and battle MASTER!'] => 'Ich bin der Himmel-und-Hölle-und-Kampf-MEISTER!',
    ['Gideon', 'PoliceOfficer', 'loseSpeech', 'Keep away from the \'Rare Candy\'!'] => 'Finger weg von den Sonderbonbons!',
    ['Triston', 'PoliceOfficer', 'introSpeech', 'Have you ever noticed this place looks like a fire hazard? Pretty sure I smell smoke...'] => 'Ist dir aufgefallen, dass dieser Ort ein einziger Brandherd ist? Ich rieche Rauch ...',
    ['Triston', 'PoliceOfficer', 'winSpeech', 'See? It\'s \'cause I\'m on fire today!'] => 'Siehst du? Ich bin heute einfach on fire!',
    ['Triston', 'PoliceOfficer', 'loseSpeech', 'See? It\'s \'cause you\'re on fire today!'] => 'Siehst du? Du bist heute einfach on fire!',
    ['Charles', 'GUITARIST', 'introSpeech', 'Hey, d\'you want to be in my band?'] => 'Hey, willst du in meiner Band sein?',
    ['Charles', 'GUITARIST', 'winSpeech', 'Never mind. I don\'t think you\'re ready. '] => 'Schon gut. Ich glaube, du bist noch nicht so weit.',
    ['Charles', 'GUITARIST', 'loseSpeech', 'On second thought, you might drown the others out...'] => 'Andererseits übertönst du vielleicht noch die anderen ...',
    ['Raymond', 'GUITARIST', 'introSpeech', 'Prepare to be wowed.'] => 'Mach dich auf was gefasst.',
    ['Raymond', 'GUITARIST', 'winSpeech', 'Devastatingly musical and a showstopping battler? I really am the whole package!'] => 'Ein mitreißender Musiker und ein umwerfender Kämpfer? Ich bin echt das Gesamtpaket!',
    ['Raymond', 'GUITARIST', 'loseSpeech', 'I guess a cat can\'t be dazzlingly talented in everything...'] => 'Ich schätze, eine Katze kann nicht in allem glänzen ...',
    ['Dirk', 'Casanova', 'introSpeech', 'Say... How about we go watch the sunset together after this?'] => 'Sag mal ... Wie wär\'s, wenn wir nachher zusammen den Sonnenuntergang anschauen?',
    ['Dirk', 'Casanova', 'winSpeech', 'Come on, my feathered beauties!'] => 'Kommt schon, meine gefiederten Schönheiten!',
    ['Dirk', 'Casanova', 'loseSpeech', 'You? No, no! I was talking to my Pokemon!'] => 'Du? Nein, nein! Ich meinte meine Pokémon!',
    ['Harold', 'Casanova', 'introSpeech', 'Okay, it\'s settled. If I win here, I\'ll ask Amaria out!'] => 'Na gut, steht fest. Wenn ich hier gewinne, frag ich Amaria nach einem Date!',
    ['Harold', 'Casanova', 'winSpeech', 'All right, I\'ll do it!'] => 'Alles klar, ich mach\'s!',
    ['Harold', 'Casanova', 'loseSpeech', 'I-I don\'t have the nerve!'] => 'I-ich trau mich nicht!',
    ['Marck-Marie', 'AQUA1', 'introSpeech', 'Hey, d\'you mind testing these cookies? I think I messed up the recipe...'] => 'Hey, würdest du diese Kekse probieren? Ich glaub, ich hab das Rezept vermasselt ...',
    ['Marck-Marie', 'AQUA1', 'winSpeech', 'The cookies are salty like you! Haha!'] => 'Die Kekse sind salzig, genau wie du! Haha!',
    ['Marck-Marie', 'AQUA1', 'loseSpeech', 'The cookies stink... and so do my battle skills!'] => 'Die Kekse sind eklig ... und meine Kampfkünste auch!',
    ['Peter', 'AQUA1', 'introSpeech', 'Hey, have you got the time? To listen to my little rhyme?'] => 'Hey, hast du ein bisschen Zeit? Für meinen kleinen Reim bereit?',
    ['Peter', 'AQUA1', 'winSpeech', 'You can\'t deny my skills are great! Now bring on the next fight! I don\'t want to wait!'] => 'Du kannst nicht leugnen, dass ich\'s draufhab! Her mit dem nächsten Kampf, ich will nicht warten!',
    ['Peter', 'AQUA1', 'loseSpeech', 'I guess the rumors must be true-- all the things they say about you!'] => 'Die Gerüchte müssen wohl stimmen – all das, was man über dich sagt!',
    ['Dev', 'HIKER', 'introSpeech', 'I love hiking, but I can\'t stand all the bugs...'] => 'Ich liebe Wanderungen, aber diese ganzen Käfer kann ich nicht ausstehen ...',
    ['Dev', 'HIKER', 'winSpeech', 'I\'ll conquer them eventually...'] => 'Irgendwann bezwinge ich sie ...',
    ['Dev', 'HIKER', 'loseSpeech', 'The bugs! They\'re overwhelming!'] => 'Die Käfer! Sie sind überall!',
    ['Corey', 'HIKER', 'introSpeech', 'I\'ve been searching for the best trail in Reborn. You\'ve been all over, right? Any suggestions?'] => 'Ich suche den besten Wanderweg in Reborn. Du warst doch überall, oder? Hast du einen Tipp?',
    ['Corey', 'HIKER', 'winSpeech', 'Maybe I should try climbing Victory Road next...'] => 'Vielleicht sollte ich als Nächstes den Siegespfad erklimmen ...',
    ['Corey', 'HIKER', 'loseSpeech', 'Hey, hey! I said I wanted a trail, not a fail!'] => 'Hey, hey! Ich wollte einen Wanderweg, keinen Reinfall!',
    ['Andre', 'HARDHAT', 'introSpeech', 'Last battle before break!'] => 'Letzter Kampf vor der Pause!',
    ['Andre', 'HARDHAT', 'winSpeech', 'Nice! The guys owe me a burger now!'] => 'Klasse! Die Jungs schulden mir jetzt einen Burger!',
    ['Andre', 'HARDHAT', 'loseSpeech', 'All right, back to building...'] => 'Na gut, zurück an die Arbeit ...',
    ['Ferris', 'HARDHAT', 'introSpeech', 'I may be just a builder, but I just know I can beat ya!'] => 'Ich bin vielleicht nur Bauarbeiter, aber ich weiß einfach, dass ich dich schlagen kann!',
    ['Ferris', 'HARDHAT', 'winSpeech', 'What\'d I say?'] => 'Was hab ich gesagt?',
    ['Ferris', 'HARDHAT', 'loseSpeech', 'All right, got a bit too confident there...'] => 'Na gut, da war ich wohl etwas zu selbstsicher ...',
    ['Alivia', 'LADY', 'introSpeech', 'Tee hee, Paige just told me the most droll joke!'] => 'Hihi, Paige hat mir gerade den drolligsten Witz erzählt!',
    ['Alivia', 'LADY', 'winSpeech', 'You were an even more droll joke!'] => 'Du warst ein noch drolligerer Witz!',
    ['Alivia', 'LADY', 'loseSpeech', 'Hee hee... I was distracted, but it really was so funny, darling!'] => 'Hee hee ... Ich war abgelenkt, aber der war wirklich so lustig, Liebling!',
    ['Paige', 'LADY', 'introSpeech', 'We\'ve only a short battle together, so let\'s make the most of it!'] => 'Wir haben nur kurz Zeit für diesen Kampf, also machen wir das Beste draus!',
    ['Paige', 'LADY', 'winSpeech', 'Someone\'s got to lose, but I do hope you enjoyed yourself!'] => 'Einer muss verlieren, aber ich hoffe, du hattest Spaß!',
    ['Paige', 'LADY', 'loseSpeech', 'That was lovely! Oh, I must tell Livi about this!'] => 'Das war wundervoll! Oh, das muss ich Livi erzählen!',
    ['Anya', 'BEAUTY', 'introSpeech', 'Watch me as I battle, please. I\'m trying to become more graceful.'] => 'Sieh mir bitte beim Kämpfen zu. Ich möchte anmutiger werden.',
    ['Anya', 'BEAUTY', 'winSpeech', 'That was my best battle yet! Thank you, stranger!'] => 'Das war mein bester Kampf bisher! Danke, Fremder!',
    ['Anya', 'BEAUTY', 'loseSpeech', 'I guess I gotta learn to lose with grace, as well...'] => 'Ich muss wohl auch lernen, mit Anmut zu verlieren ...',
    ['Dawn', 'BEAUTY', 'introSpeech', 'Yawn... The lighting here makes me sleepy!'] => 'Gähn ... Die Beleuchtung hier macht mich schläfrig!',
    ['Dawn', 'BEAUTY', 'winSpeech', 'You did your best!'] => 'Du hast dein Bestes gegeben!',
    ['Dawn', 'BEAUTY', 'loseSpeech', 'Time for a nap...'] => 'Zeit für ein Nickerchen ...',
    ['Abby', 'NatureGirl', 'introSpeech', 'I\'m a bit hungry... You have any Water Stones? '] => 'Ich hab ein bisschen Hunger ... Hast du irgendwelche Wassersteine?',
    ['Abby', 'NatureGirl', 'winSpeech', 'Maybe I can buy one here...'] => 'Vielleicht kann ich hier einen kaufen ...',
    ['Abby', 'NatureGirl', 'loseSpeech', 'No? All right, I\'ll just get a sandwich instead...'] => 'Nein? Na gut, dann hol ich mir eben ein Sandwich ...',
    ['Gretel', 'NatureGirl', 'introSpeech', 'I\'m warnin\' ya, people hate to battle me!'] => 'Ich warn dich, keiner kämpft gern gegen mich!',
    ['Gretel', 'NatureGirl', 'winSpeech', 'Haha! Nothin\' like a loss to Gretel to make yer day! '] => 'Haha! Nichts versüßt den Tag so wie eine Niederlage gegen Gretel!',
    ['Gretel', 'NatureGirl', 'loseSpeech', 'What? How could I lose? Ya must\'ve cheated, I\'m sure of it!'] => 'Was? Wie konnte ich verlieren? Du musst geschummelt haben, ganz sicher!',
    ['Thomas', 'HIKER', 'introSpeech', 'Let me show you what the wilds have taught me.'] => 'Ich zeig dir, was ich in der Wildnis gelernt habe.',
    ['Thomas', 'HIKER', 'winSpeech', 'You should learn from the wilds!'] => 'Von der Wildnis kannst du noch was lernen!',
    ['Thomas', 'HIKER', 'loseSpeech', 'It seems I wasn\'t ready.'] => 'Sieht so aus, als wäre ich noch nicht bereit gewesen.',
    ['Zaki', 'HIKER', 'introSpeech', 'Just try me! I\'ve been hardened by nature!'] => 'Nur zu! Die Natur hat mich abgehärtet!',
    ['Zaki', 'HIKER', 'winSpeech', 'Smell ya later'] => 'Man riecht sich später!',
    ['Zaki', 'HIKER', 'loseSpeech', 'You\'re stronger than you look...'] => 'Du bist stärker, als du aussiehst ...',
    ['Naria', 'PSYCHIC_Female', 'introSpeech', 'You cannot fathom my superior intellect!'] => 'Du kannst dir meine überragende Intelligenz nicht mal vorstellen!',
    ['Naria', 'PSYCHIC_Female', 'winSpeech', 'Superiority reigns supreme! Wait, is that redundant?'] => 'Überlegenheit siegt immer! Moment, ist das nicht doppelt gemoppelt?',
    ['Naria', 'PSYCHIC_Female', 'loseSpeech', 'What could have been my downfall?'] => 'Was könnte mein Untergang gewesen sein?',
    ['Anabell', 'PSYCHIC_Female', 'introSpeech', 'Could this all be preordained?'] => 'War das alles vorherbestimmt?',
    ['Anabell', 'PSYCHIC_Female', 'winSpeech', 'Fate spoke, and you have listened well. '] => 'Das Schicksal sprach, und du hast gut zugehört.',
    ['Anabell', 'PSYCHIC_Female', 'loseSpeech', 'There is so much I don\'t know...'] => 'Es gibt so vieles, das ich nicht weiß ...',
    ['Andrew', 'Casanova', 'introSpeech', 'You\'ll be just another stepping stone on my path to victory!'] => 'Du bist nur ein weiterer Trittstein auf meinem Weg zum Sieg!',
    ['Andrew', 'Casanova', 'winSpeech', 'Stand down, stone.'] => 'Zurücktreten, Stein.',
    ['Andrew', 'Casanova', 'loseSpeech', 'I lost?! To you?'] => 'Ich hab verloren?! Gegen dich?',
    ['Liandra', 'BEAUTY', 'introSpeech', 'Try not to make this embarrassing... '] => 'Versuch, das nicht peinlich zu machen ...',
    ['Liandra', 'BEAUTY', 'winSpeech', 'What did I say before about being embarrassing?'] => 'Was hab ich vorhin über Peinlichkeit gesagt?',
    ['Liandra', 'BEAUTY', 'loseSpeech', 'Oh? This is quite unexpected...'] => 'Oh? Das ist ja ziemlich unerwartet ...',
    ['Eliah', 'GENTLEMAN', 'introSpeech', 'Let us have an entertaining battle.'] => 'Lass uns einen unterhaltsamen Kampf austragen.',
    ['Eliah', 'GENTLEMAN', 'winSpeech', 'Is that truly the best you can do? Balderdash!'] => 'War das wirklich alles, was du draufhast? Unsinn!',
    ['Eliah', 'GENTLEMAN', 'loseSpeech', 'Most excellent!'] => 'Ausgezeichnet!',
    ['Warner', 'GENTLEMAN', 'introSpeech', 'Show me what life has taught you, youngster.'] => 'Zeig mir, was dir das Leben beigebracht hat, junger Freund.',
    ['Warner', 'GENTLEMAN', 'winSpeech', 'If nothing else, age will school you yet.'] => 'Wenn sonst nichts hilft, wird dir das Alter schon noch etwas beibringen.',
    ['Warner', 'GENTLEMAN', 'loseSpeech', 'You\'re more than ready!'] => 'Du bist mehr als bereit!',
    ['Lux', 'COOLTRAINER_Female', 'introSpeech', 'You ready? Cause here I come!'] => 'Bereit? Dann komm ich!',
    ['Lux', 'COOLTRAINER_Female', 'winSpeech', 'You shoulda been more ready!'] => 'Du hättest besser vorbereitet sein sollen!',
    ['Lux', 'COOLTRAINER_Female', 'loseSpeech', 'What?! No!'] => 'Was?! Nein!',
    ['Aurora', 'COOLTRAINER_Female', 'introSpeech', 'No one is ending my streak!'] => 'Niemand beendet meine Siegesserie!',
    ['Aurora', 'COOLTRAINER_Female', 'winSpeech', 'I\'ll be at the top! You just wait!'] => 'Ich bin bald ganz oben! Wart\'s nur ab!',
    ['Aurora', 'COOLTRAINER_Female', 'loseSpeech', 'Another one down! Let\'s go, lucky No. 7!'] => 'Wieder einer erledigt! Auf geht\'s, Glückszahl sieben!',
    ['Raymond', 'COOLTRAINER_Male', 'introSpeech', 'Come get some! I\'ll run you over!'] => 'Komm schon! Ich walz dich platt!',
    ['Raymond', 'COOLTRAINER_Male', 'winSpeech', 'Ground into dirt! How do you like me now?!'] => 'In den Boden gestampft! Wie findest du mich jetzt?!',
    ['Raymond', 'COOLTRAINER_Male', 'loseSpeech', 'I\'ll get you next time!'] => 'Beim nächsten Mal erwisch ich dich!',
    ['Braxie', 'COOLTRAINER_Male', 'introSpeech', 'You think you can take me?'] => 'Du glaubst, du kannst\'s mit mir aufnehmen?',
    ['Braxie', 'COOLTRAINER_Male', 'winSpeech', 'Can\'t take me nowhere.'] => 'Mich kann man einfach nirgendwohin mitnehmen.',
    ['Braxie', 'COOLTRAINER_Male', 'loseSpeech', 'You got lucky punk!'] => 'Du hattest Glück, du Penner!',
    ['Carl', 'BLACKBELT', 'introSpeech', 'Always ready for a challenge!'] => 'Immer bereit für eine Herausforderung!',
    ['Carl', 'BLACKBELT', 'winSpeech', 'Done! Next!'] => 'Fertig! Der Nächste!',
    ['Carl', 'BLACKBELT', 'loseSpeech', 'This, I couldn\'t overcome...'] => 'Das konnte ich nicht überwinden ...',
    ['Gabriel', 'BLACKBELT', 'introSpeech', 'How long will you last I wonder?'] => 'Wie lange hältst du wohl durch?',
    ['Gabriel', 'BLACKBELT', 'winSpeech', 'Not long enough!'] => 'Nicht lange genug!',
    ['Gabriel', 'BLACKBELT', 'loseSpeech', 'It seems I underestimated you!'] => 'Sieht so aus, als hätte ich dich unterschätzt!',
    ['Ana', 'NatureGirl', 'introSpeech', 'You cannot break the bonds between me and my Pokémon...'] => 'Du kannst das Band zwischen mir und meinen Pokémon nicht brechen ...',
    ['Ana', 'NatureGirl', 'winSpeech', 'Friends, you\'ve done it!'] => 'Freunde, ihr habt\'s geschafft!',
    ['Ana', 'NatureGirl', 'loseSpeech', 'How can this be...?'] => 'Wie kann das sein ...?',
    ['Frank', 'BLACKBELT', 'introSpeech', 'Face me! Hold nothing back! '] => 'Stell dich mir! Gib alles!',
    ['Frank', 'BLACKBELT', 'winSpeech', 'You must continue your training yet!'] => 'Du musst unbedingt weitertrainieren!',
    ['Frank', 'BLACKBELT', 'loseSpeech', 'I will keep training! I will keep fighting!'] => 'Ich werde weiter trainieren! Ich werde weiterkämpfen!',
    ['Rexie', 'GUITARIST', 'introSpeech', 'Duuude! You can\'t take my riffs!'] => 'Duuude! Meine Riffs hältst du nicht aus!',
    ['Rexie', 'GUITARIST', 'winSpeech', 'My riffs, duuude!'] => 'Meine Riffs, Duuude!',
    ['Rexie', 'GUITARIST', 'loseSpeech', 'What? You\'ve got style!'] => 'Was? Du hast echt Stil!',
    ['Taranis', 'Punk', 'introSpeech', 'I won\'t go easy just \'cause you\'re the favourite to win!'] => 'Ich mach\'s dir nicht leicht, nur weil du als Favorit giltst!',
    ['Taranis', 'Punk', 'winSpeech', 'Nice showing!'] => 'Guter Kampf!',
    ['Taranis', 'Punk', 'loseSpeech', 'I guess you\'re the favourite for a reason...'] => 'Du bist wohl aus gutem Grund der Favorit ...',
    ['Nicki', 'PSYCHIC_Female', 'introSpeech', 'I love Meowth! I love every kind of Meowth!'] => 'Ich liebe Mauzi! Ich liebe jede Art von Mauzi!',
    ['Nicki', 'PSYCHIC_Female', 'winSpeech', 'Now I can buy my darlings new toys!'] => 'Jetzt kann ich meinen Lieblingen neues Spielzeug kaufen!',
    ['Nicki', 'PSYCHIC_Female', 'loseSpeech', 'I wish I could hug all of them...'] => 'Ich wünschte, ich könnte sie alle knuddeln ...',
    ['Gabe', 'TechNerd', 'introSpeech', 'Technology is my job! And nature is my passion!'] => 'Technik ist mein Beruf! Und die Natur meine Leidenschaft!',
    ['Gabe', 'TechNerd', 'winSpeech', 'Natural science is a natural victory!'] => 'Mit Naturwissenschaft ist der Sieg ganz natürlich!',
    ['Gabe', 'TechNerd', 'loseSpeech', 'I\'m not always that good at balancing them...'] => 'Ich kann die beiden nicht immer so gut unter einen Hut bringen ...',
    ['Kyu', 'CultistF', 'introSpeech', 'Like a bolt from the blue, it\'s time for a Pokémon battle between me and you.'] => 'Wie ein Blitz aus heiterem Himmel: Zeit für einen Pokémon-Kampf zwischen dir und mir!',
    ['Kyu', 'CultistF', 'winSpeech', 'You\'ve gotta enjoy the moment with everything you\'ve got.'] => 'Du musst den Moment mit allem genießen, was du hast.',
    ['Kyu', 'CultistF', 'loseSpeech', 'Ah, beans.'] => 'Ach, verdammt.',
    ['Leo', 'COOLTRAINER_Male', 'introSpeech', 'Beautifly has demanded you soul!'] => 'Papinella verlangt deine Seele!',
    ['Leo', 'COOLTRAINER_Male', 'winSpeech', 'Enjoy the feast, Beautifly...'] => 'Lass es dir schmecken, Papinella ...',
    ['Leo', 'COOLTRAINER_Male', 'loseSpeech', 'What? Ya got lucky.'] => 'Was? Du hattest Glück.',
    ['Seyon', 'KNIGHT', 'introSpeech', 'Let the future be determined by this battle!'] => 'Lass diesen Kampf über die Zukunft entscheiden!',
    ['Seyon', 'KNIGHT', 'winSpeech', 'Victory has been served to me!'] => 'Der Sieg wurde mir serviert!',
    ['Seyon', 'KNIGHT', 'loseSpeech', 'Defeat has been served to me...'] => 'Die Niederlage wurde mir serviert ...',
    ['Victor', 'HIKER', 'introSpeech', 'Oi, mate!'] => 'Na, Kumpel!',
    ['Victor', 'HIKER', 'winSpeech', 'That\'s another one in the bag!'] => 'Wieder einer abgehakt!',
    ['Victor', 'HIKER', 'loseSpeech', 'God diddely damn, dog, you`re good!'] => 'Verdammt noch mal, Alter, du bist echt gut!',
    ['Kim', 'Cultist', 'introSpeech', 'For the almighty and powerful Bapabui!'] => 'Für den allmächtigen und mächtigen Bapabui!',
    ['Kim', 'Cultist', 'winSpeech', 'Nothing can stop the greatness of Bapabui!'] => 'Nichts kann Bapabuis Größe aufhalten!',
    ['Kim', 'Cultist', 'loseSpeech', 'Please have mercy on my soul, great Bapabui.'] => 'Bitte verschone meine Seele, großer Bapabui.',
    ['James', 'MAGMA2', 'introSpeech', 'How much have you dealt with the Aqua and Magma Gangs?'] => 'Wie viel hattest du schon mit der Aqua- und der Magma-Gang zu tun?',
    ['James', 'MAGMA2', 'winSpeech', 'I\'m tryin\' to write a book about their history...'] => 'Ich versuch, ein Buch über ihre Geschichte zu schreiben ...',
    ['James', 'MAGMA2', 'loseSpeech', 'I bet you beat them pretty handily, huh?'] => 'Ich wette, du hast sie ganz schön fertiggemacht, was?',
    ['Seal', 'HIKER', 'introSpeech', 'As far as I\'m concerned, the rounder the Pokemon, the better!'] => 'Meiner Meinung nach gilt: Je runder das Pokémon, desto besser!',
    ['Seal', 'HIKER', 'winSpeech', 'Spheal, Rowlet, Jigglypuff- I love \'em all!'] => 'Seemops, Bauz, Pummeluff – ich liebe sie alle!',
    ['Seal', 'HIKER', 'loseSpeech', 'You\'ve got too many sharp edges...'] => 'Du hast zu viele scharfe Kanten ...',
    ['Blue', 'AceTrainerM', 'introSpeech', 'If I can\'t win, at least I can improve my mind.'] => 'Wenn ich schon nicht gewinnen kann, kann ich wenigstens meinen Verstand schärfen.',
    ['Blue', 'AceTrainerM', 'winSpeech', 'I\'ve reached the peak! '] => 'Ich hab den Gipfel erreicht!',
    ['Blue', 'AceTrainerM', 'loseSpeech', 'I learned a lot from this battle; thank you for that.'] => 'Ich habe in diesem Kampf viel gelernt; danke dafür.',
    ['B', 'COOLTRAINER_Female', 'introSpeech', 'After I beat you, Fern will finally pay attention to me!'] => 'Nachdem ich dich besiegt habe, wird Fern mir endlich Aufmerksamkeit schenken!',
    ['B', 'COOLTRAINER_Female', 'winSpeech', 'Now if you\'ll excuse me, I have a certain someone to go ask on a date!'] => 'Wenn du mich entschuldigst, ich muss jetzt jemanden nach einem Date fragen!',
    ['B', 'COOLTRAINER_Female', 'loseSpeech', 'Now how is he going to notice me?!'] => 'Wie soll er mich jetzt bemerken?!',
    ['Amelia', 'LADY', 'introSpeech', 'If the faith between you and your Pokémon wavers even for a moment, you will not find victory against me.'] => 'Wenn das Vertrauen zwischen dir und deinen Pokémon auch nur einen Moment wankt, wirst du mich nicht besiegen.',
    ['Amelia', 'LADY', 'winSpeech', 'The faith you have in your Pokémon and they in you needs work'] => 'Dein Vertrauen in deine Pokémon und ihres in dich muss noch wachsen.',
    ['Amelia', 'LADY', 'loseSpeech', 'You and your Pokémon... Such an unbreakable faith...'] => 'Du und deine Pokémon ... so ein unerschütterliches Vertrauen ...',
    ['Lisa', 'AceTrainerF', 'introSpeech', 'Why hello there, cutie. Wanna have some fun?'] => 'Na, hallo, du süßes Ding. Lust auf ein bisschen Spaß?',
    ['Lisa', 'AceTrainerF', 'winSpeech', 'Don\'t feel bad; you still have one thing going for you.'] => 'Sei nicht traurig; immerhin hast du noch eine gute Seite.',
    ['Lisa', 'AceTrainerF', 'loseSpeech', 'Cute and strong... How about giving me a call later?'] => 'Süß und stark ... Wie wär\'s, wenn du mich später anrufst?',
    ['Dream', 'NatureGirl', 'introSpeech', 'Ame\'s done so much for me y\'know? I\'ll never forget her... But enough requiem. How about we run a little test, eh \'champion\'?'] => 'Ame hat so viel für mich getan, weißt du? Ich werde sie nie vergessen ... Aber genug vom Trauerlied. Wie wär\'s mit einem kleinen Test, hm, „Champ“?',
    ['Dream', 'NatureGirl', 'winSpeech', 'Teehee, not even the restrictions here could prevent you from losing to me? Keep dreaming, and next time I\'ll hold back even more.'] => 'Teehee, nicht mal die Einschränkungen hier konnten verhindern, dass du gegen mich verlierst? Träum weiter, und nächstes Mal halte ich mich noch mehr zurück.',
    ['Dream', 'NatureGirl', 'loseSpeech', 'That was a fun little distraction, thanks! Maybe one day you\'ll even be able to wake up to the real me...'] => 'Das war eine nette kleine Ablenkung, danke! Vielleicht schaffst du\'s eines Tages sogar, für mein wahres Ich aufzuwachen ...',
    ['Tim', 'AceTrainerM', 'introSpeech', 'Submit to the power of Unova!'] => 'Unterwirf dich der Macht von Einall!',
    ['Tim', 'AceTrainerM', 'winSpeech', 'See what I told you? You can\'t beat Gen 5!'] => 'Siehst du, was ich meinte? Gegen Generation 5 kommst du nicht an!',
    ['Tim', 'AceTrainerM', 'loseSpeech', 'It\'s not by rejecting different ideas, but by accepting different ideas that the world creates a chemical reaction. That is truly the formula for changing the world.'] => 'Die Welt löst nicht durch das Ablehnen anderer Ideen eine chemische Reaktion aus, sondern dadurch, dass sie sie annimmt. Das ist die wahre Formel, um die Welt zu verändern.',
    ['Paul', 'PkMnRANGER_Male', 'introSpeech', 'Let\'s see what treasures are in store for us!'] => 'Mal sehen, welche Schätze uns erwarten!',
    ['Paul', 'PkMnRANGER_Male', 'winSpeech', 'What a find! I\'ll keep this close to my chest.'] => 'Was für ein Fund! Den behalte ich lieber für mich.',
    ['Paul', 'PkMnRANGER_Male', 'loseSpeech', 'Ah, so that was all it was...'] => 'Ach, das war also schon alles ...',
    ['Lindi', 'MAGMA2', 'introSpeech', 'It\'s time to rock this house!'] => 'Zeit, die Bude zu rocken!',
    ['Lindi', 'MAGMA2', 'winSpeech', 'It\'s a long way to the top.'] => 'Der Weg nach ganz oben ist lang.',
    ['Lindi', 'MAGMA2', 'loseSpeech', 'You\'re a real rockstar!'] => 'Du bist ein echter Rockstar!',
    ['Blue', 'LADY', 'introSpeech', 'Did you know that a banana is an official unit of measurement?'] => 'Wusstest du, dass eine Banane eine offizielle Maßeinheit ist?',
    ['Blue', 'LADY', 'winSpeech', 'The way to the top is hard, but one day you\'ll make it!'] => 'Der Weg nach oben ist hart, aber eines Tages schaffst du\'s!',
    ['Blue', 'LADY', 'loseSpeech', 'I\'m Blue~ Da-ba-dee, da-ba-daa...'] => 'Ich bin blau~ dabadee, dabadaa ...',
    ['Mac', 'PSYCHIC_Female', 'introSpeech', 'Finally.'] => 'Endlich.',
    ['Mac', 'PSYCHIC_Female', 'winSpeech', 'Don\'t worry about it. '] => 'Mach dir nichts draus.',
    ['Mac', 'PSYCHIC_Female', 'loseSpeech', 'I\'m free!'] => 'Ich bin frei!',
    ['Trevor', 'AceTrainerM', 'introSpeech', 'When one chapter ends, another begins.  Show me the story you have written!'] => 'Wenn ein Kapitel endet, beginnt ein neues. Zeig mir die Geschichte, die du geschrieben hast!',
    ['Trevor', 'AceTrainerM', 'winSpeech', 'You certainly look like you have many chapters written in your story, but I\'m sure you have many more to go!'] => 'Du hast bestimmt schon viele Kapitel in deiner Geschichte erlebt, aber es kommen sicher noch viele dazu!',
    ['Trevor', 'AceTrainerM', 'loseSpeech', 'Interesting... how does one learn from loss?  Learn from this experience, for your story still lives on!'] => 'Interessant ... Wie lernt man aus einer Niederlage? Lern aus dieser Erfahrung, denn deine Geschichte geht weiter!',
    ['Nick', 'MAGMA2', 'introSpeech', 'Give it your best!'] => 'Gib dein Bestes!',
    ['Nick', 'MAGMA2', 'winSpeech', 'I bet Mario will never see this either!'] => 'Ich wette, Mario wird auch das nie zu sehen bekommen!',
    ['Nick', 'MAGMA2', 'loseSpeech', 'I bet Mario will never see this!'] => 'Ich wette, Mario wird das nie zu sehen bekommen!',
    ['Adam', 'AceTrainerM', 'introSpeech', 'It\'s me, the best Trainer and battler!'] => 'Ich bin\'s, der beste Trainer und Kämpfer!',
    ['Adam', 'AceTrainerM', 'winSpeech', 'I told you I was the best!'] => 'Ich hab doch gesagt, dass ich der Beste bin!',
    ['Adam', 'AceTrainerM', 'loseSpeech', 'Hah, so this is your power...'] => 'Ha, so viel Kraft hast du also ...',
    ['Ngoc', 'AceTrainerM', 'introSpeech', 'I used these Pokémon in my final teams in every adventure I\'ve taken!'] => 'Ich habe diese Pokémon bei jedem meiner Abenteuer in meinen finalen Teams eingesetzt!',
    ['Ngoc', 'AceTrainerM', 'winSpeech', 'That is why I used them!'] => 'Darum habe ich sie ja benutzt!',
    ['Ngoc', 'AceTrainerM', 'loseSpeech', 'I\'ll use a different combination next time!'] => 'Nächstes Mal nehme ich eine andere Kombination!',
    ['Holly', 'CultistF', 'introSpeech', 'The colors of the world are changing!'] => 'Die Farben der Welt verändern sich!',
    ['Holly', 'CultistF', 'winSpeech', 'Red, a world about to dawn.'] => 'Rot, eine Welt kurz vor dem Morgengrauen.',
    ['Holly', 'CultistF', 'loseSpeech', 'Black, the color of despair.'] => 'Schwarz, die Farbe der Verzweiflung.',
    ['Saya', 'AceTrainerF', 'introSpeech', 'Oooh, I\'m up against the Champion huh? Guess I better bring my A game.'] => 'Oooh, ich trete gegen den Champ an, hm? Dann sollte ich wohl mein Bestes geben.',
    ['Saya', 'AceTrainerF', 'winSpeech', 'Don\'t worry, there\'s no shame in losing to me.'] => 'Keine Sorge, gegen mich zu verlieren ist keine Schande.',
    ['Saya', 'AceTrainerF', 'loseSpeech', 'Well done!'] => 'Gut gemacht!',
    ['Brabo', 'TechNerd', 'introSpeech', 'So I\'m sitting there, barbeque sauce on my Skitty...'] => 'Also, ich sitz da, Barbecuesoße auf meinem Eneco ...',
    ['Brabo', 'TechNerd', 'winSpeech', 'You know I had to do it to \'em.'] => 'Du weißt doch, ich musste es einfach tun.',
    ['Brabo', 'TechNerd', 'loseSpeech', 'This is not the way...'] => 'Das ist nicht der richtige Weg ...',
    ['Xes', 'TechNerd', 'introSpeech', 'People are capable of creating a path towards their goal. Are you ready to fight in order to reach it?'] => 'Menschen können sich selbst einen Weg zu ihrem Ziel bahnen. Bist du bereit, dafür zu kämpfen?',
    ['Xes', 'TechNerd', 'winSpeech', 'When people have an overwhelming advantage, they sometimes take on a little risk to try and show off their superiority over the other.'] => 'Wenn Menschen klar überlegen sind, gehen sie manchmal ein kleines Risiko ein, um ihre Überlegenheit zur Schau zu stellen.',
    ['Xes', 'TechNerd', 'loseSpeech', 'Victory isn’t something you are given. It is something you take.'] => 'Der Sieg wird dir nicht geschenkt. Du musst ihn dir nehmen.',
    ['Colette', 'SWIMMERGRIL', 'introSpeech', 'Maybe this night club represents the futile and endless dance of those who vie for greatness?'] => 'Vielleicht steht dieser Nachtclub für den sinnlosen, endlosen Tanz all jener, die nach Größe streben?',
    ['Colette', 'SWIMMERGRIL', 'winSpeech', 'Or maybe I’m just high from all this catnip, nya? I’m a dancer here. I needed to lose quick and then get back to my job, dammit! Now I have to advance!'] => 'Oder bin ich einfach von all der Katzenminze high, nya? Ich tanze hier. Ich wollte schnell verlieren und zurück an die Arbeit, verdammt! Jetzt muss ich weiterkommen!',
    ['Colette', 'SWIMMERGRIL', 'loseSpeech', '*bites you* If you’d lost you wouldn’t have been bitten. There’s no lesson here to learn. The path forward only leads back into my jaws.'] => '*beißt dich* Wenn du verloren hättest, hätte ich dich nicht gebissen. Daraus gibt’s nichts zu lernen. Der Weg nach vorn führt dich nur zurück in mein Maul.',
    ['Yuri', 'HIKER', 'introSpeech', 'G\'day. I\'ve heard a lot about you. I\'d love to see the bond between you and your Pokémon.'] => 'Grüß dich! Ich hab viel von dir gehört. Ich würde gern die Verbindung zwischen dir und deinen Pokémon sehen.',
    ['Yuri', 'HIKER', 'winSpeech', 'What, you\'re the savior of the region? What a disappointing display.'] => 'Was, du bist der Retter der Region? Das war ja enttäuschend.',
    ['Yuri', 'HIKER', 'loseSpeech', 'From the bottom of my heart, thank you.'] => 'Von ganzem Herzen: Danke.',
    ['Maiko', 'COOLTRAINER_Female', 'introSpeech', 'Attack perfect, full combo!'] => 'Perfekter Angriff, volle Kombo!',
    ['Maiko', 'COOLTRAINER_Female', 'winSpeech', 'All right, a new high score!'] => 'Alles klar, ein neuer Highscore!',
    ['Maiko', 'COOLTRAINER_Female', 'loseSpeech', 'Awww, you couldn\'t make it.'] => 'Awww, du hast es nicht geschafft.',
    ['Stray', 'StreetRat', 'introSpeech', 'Someone stole my fucking porch. I opened my door an fell.'] => 'Irgendwer hat meine verdammte Veranda geklaut. Ich hab die Tür aufgemacht und bin hingefallen.',
    ['Stray', 'StreetRat', 'winSpeech', 'Winstreak? No shot, can’t have shit in Reborn.'] => 'Siegesserie? Keine Chance, in Reborn kann man echt gar nichts haben.',
    ['Stray', 'StreetRat', 'loseSpeech', 'You can’t have shit in Spinel Town.'] => 'In Spinel Town kann man echt gar nichts haben.',
    ['Raven', 'RANGERF', 'introSpeech', 'I\'m buzzing with excitement! The anticipation has me feeling antsy!'] => 'Ich bin ganz aufgeregt! Die Vorfreude macht mich schon ganz hibbelig!',
    ['Raven', 'RANGERF', 'winSpeech', 'I hope I didn\'t bug you too much! '] => 'Ich hoffe, ich bin dir nicht zu sehr auf die Nerven gegangen!',
    ['Raven', 'RANGERF', 'loseSpeech', 'Looks like I couldn\'t worm my way out of this one, and now my progress has stag-nated. '] => 'Sieht aus, als hätte ich mich da nicht rauswinden können – jetzt stagniert mein Fortschritt auch noch.',
    ['Damian', 'StreetRat', 'introSpeech', 'Yeah, I have lived without all the fancy things that people use to get somewhere in life, but I got here through sheer force of will. Now bring it!'] => 'Ja, ich hatte nie all den schicken Kram, mit dem andere im Leben vorankommen. Aber ich hab\'s durch pure Willenskraft bis hierher geschafft. Na los!',
    ['Damian', 'StreetRat', 'winSpeech', 'I told you, sheer force of will!'] => 'Ich hab\'s dir doch gesagt: pure Willenskraft!',
    ['Damian', 'StreetRat', 'loseSpeech', 'I see... I guess I can\'t... I can\'t rival someone who has a stronger will.'] => 'Verstehe ... Ich kann wohl ... ich kann wohl niemanden übertrumpfen, dessen Wille stärker ist.',
  }.freeze
# Runtime hooks for the reviewed tables prepended by build_mod.py.
# Display-only: no save, cache, source-table, or disk writes.
  def self.key(text)
    return nil unless text.is_a?(String)
    Messages.stringToKey(text)
  end

  def self.german?
    MessageTypes.class_variable_get(:@@messages).instance_variable_get(:@reviewed_german_enabled)
  end

  def self.repair(table, source, value)
    pair = table && table[key(source)]
    # Preserve newer upstream translations instead of blindly overwriting them.
    pair && key(value) == key(pair[0]) ? pair[1] : value
  end

  module Lookup
    def loadMessageFile(filename)
      @reviewed_german_enabled = false
      result = super
      @reviewed_german_enabled = !!result && File.basename(filename.to_s.tr('\\', '/')).downcase == 'german.dat'
      result
    end

    def getFromHash(type, text)
      value = super
      return value unless @reviewed_german_enabled
      value = ReviewedGermanText.repair(ReviewedGermanText::TEXTS[type], text, value)
      if type == MessageTypes::ScriptTexts && ReviewedGermanText.key(value) == ReviewedGermanText.key(text)
        ReviewedGermanText::BOSS_TEXTS[ReviewedGermanText.key(text)] || value
      else
        value
      end
    end

    def getFromMapHash(map, text)
      value = super
      return value unless @reviewed_german_enabled
      value = ReviewedGermanText.repair(ReviewedGermanText::MAPS[map], text, value)
      ReviewedGermanText.repair(ReviewedGermanText::MAPS[0], text, value)
    end
  end

  # Localize at access time so a language change never mutates cached trainer data.
  module FacilityTrainer
    [:introSpeech, :winSpeech, :loseSpeech].each do |field|
      define_method(field) do
        source = super()
        return source unless ReviewedGermanText.german?
        ReviewedGermanText::FACILITY_TEXTS[[name, tclass.to_s, field.to_s, source]] || source
      end
    end
  end

  module FacilityBoss
    def pbBattleChallengeBeginSpeech
      value = super
      value.is_a?(String) ? _INTL(value) : value
    end

    def pbMinibossDialogueOverwrite(battle)
      result = super
      battle.endspeech = _INTL(battle.endspeech) if battle.endspeech.is_a?(String)
      battle.endspeechwin = _INTL(battle.endspeechwin) if battle.endspeechwin.is_a?(String)
      result
    end
    private :pbBattleChallengeBeginSpeech, :pbMinibossDialogueOverwrite
  end
end

Messages.prepend(ReviewedGermanText::Lookup) unless Messages.ancestors.include?(ReviewedGermanText::Lookup)
if defined?(BTTrainerData)
  BTTrainerData.prepend(ReviewedGermanText::FacilityTrainer) unless BTTrainerData.ancestors.include?(ReviewedGermanText::FacilityTrainer)
end
if Object.private_method_defined?(:pbBattleChallengeBeginSpeech) && Object.private_method_defined?(:pbMinibossDialogueOverwrite)
  Object.prepend(ReviewedGermanText::FacilityBoss) unless Object.ancestors.include?(ReviewedGermanText::FacilityBoss)
end

