    [8, 'Erhöht Spezial-Angriff, senkt Spezial-Verteidigung.'] => ['Erhöht Spezial-Angriff, senkt Spezial-Verteidigung.', 'Ändert die Statuswertentwicklung: Der Spezial-Angriff wird begünstigt, die Spezial-Verteidigung geschwächt.'],
