    [8, 'Erhöht Spezial-Verteidigung, senkt Initiative.'] => ['Erhöht Spezial-Verteidigung, senkt Initiative.', 'Ändert die Statuswertentwicklung: Die Spezial-Verteidigung wird begünstigt, die Initiative geschwächt.'],
    [8, 'Erhöht Spezial-Verteidigung, senkt Spezial-Angriff.'] => ['Erhöht Spezial-Verteidigung, senkt Spezial-Angriff.', 'Ändert die Statuswertentwicklung: Die Spezial-Verteidigung wird begünstigt, der Spezial-Angriff geschwächt.'],
    [8, 'Erhöht Spezial-Verteidigung, senkt Verteidigung.'] => ['Erhöht Spezial-Verteidigung, senkt Verteidigung.', 'Ändert die Statuswertentwicklung: Die Spezial-Verteidigung wird begünstigt, die Verteidigung geschwächt.'],
    [8, 'Erhöht Verteidigung, senkt Angriff.'] => ['Erhöht Verteidigung, senkt Angriff.', 'Ändert die Statuswertentwicklung: Die Verteidigung wird begünstigt, der Angriff geschwächt.'],
    [8, 'Erhöht Verteidigung, senkt Spezial-Angriff.'] => ['Erhöht Verteidigung, senkt Spezial-Angriff.', 'Ändert die Statuswertentwicklung: Die Verteidigung wird begünstigt, der Spezial-Angriff geschwächt.'],
    [8, 'Erhöht Verteidigung, senkt Spezial-Verteidigung.'] => ['Erhöht Verteidigung, senkt Spezial-Verteidigung.', 'Ändert die Statuswertentwicklung: Die Verteidigung wird begünstigt, die Spezial-Verteidigung geschwächt.'],
    [8, 'Erhöht den Basis-Spezial-Angriff eines Pokémon.'] => ['Erhöht den Basis-Spezial-Angriff eines Pokémon.', 'Erhöht die Spezial-Angriffs-EVs eines Pokémon.'],
    [8, 'Erhöht den Basis-Verteidigungswert eines Pokémon.'] => ['Erhöht den Basis-Verteidigungswert eines Pokémon.', 'Erhöht die Verteidigungs-EVs eines Pokémon.'],
    [8, 'Erhöht die Basis-Spezial-Verteidigung eines Pokémon.'] => ['Erhöht die Basis-Spezial-Verteidigung eines Pokémon.', 'Erhöht die Spezial-Verteidigungs-EVs eines Pokémon.'],
    [8, 'Erhöht leicht den Basis-Verteidigungswert eines Pokémon.'] => ['Erhöht leicht den Basis-Verteidigungswert eines Pokémon.', 'Erhöht die Verteidigungs-EVs eines Pokémon leicht.'],
    [8, 'Erhöht leicht die Basis-Spezial-Verteidigung eines Pokémon.'] => ['Erhöht leicht die Basis-Spezial-Verteidigung eines Pokémon.', 'Erhöht die Spezial-Verteidigungs-EVs eines Pokémon leicht.'],
    [8, 'Ermöglicht Fernzugriff auf das Speichersystem. Verbraucht pro Nutzung eine Akku.'] => ['Ermöglicht Fernzugriff auf das Speichersystem. Verbraucht pro Nutzung eine Akku.', 'Ermöglicht den Fernzugriff auf das Speichersystem. Für jede Nutzung wird ein Akku verbraucht.'],
    [8, 'Ermöglicht Wulaosu die Mega-Entwicklung im Kampf.'] => ['Ermöglicht Wulaosu die Mega-Entwicklung im Kampf.', 'Ein Mega-Stein. Wenn Wulaosu ihn trägt, kann es im Kampf gigadynamaximieren.'],
    [8, 'Es erhöht den Spezial-Angriff, wenn es von einer Wasser-Attacke getroffen wird. Es kann nur einmal benutzt werden.'] => ['Es erhöht den Spezial-Angriff, wenn es von einer Wasser-Attacke getroffen wird. Es kann nur einmal benutzt werden.', 'Erhöht den Spezial-Angriff des Trägers, wenn ihn eine Wasser-Attacke trifft. Einmalig.'],
    [8, 'Es ist enorm schwer und lässt den Träger langsamer als sonst bewegen.'] => ['Es ist enorm schwer und lässt den Träger langsamer als sonst bewegen.', 'Der Träger führt seine Attacke meist zuletzt aus.'],
    [8, 'Es stellt eine gesenkte Statuswert im Kampf wieder her. Es kann nur einmal benutzt werden.'] => ['Es stellt eine gesenkte Statuswert im Kampf wieder her. Es kann nur einmal benutzt werden.', 'Stellt im Kampf gesenkte Statuswerte wieder her. Kann nur einmal benutzt werden.'],
    [8, 'Es stellt vergifteten Pokémon nach und nach KP wieder her. Bei anderen Typen fügt es Schaden zu.'] => ['Es stellt vergifteten Pokémon nach und nach KP wieder her. Bei anderen Typen fügt es Schaden zu.', 'Gift-Pokémon erhalten durch dieses Item nach und nach KP zurück. Allen anderen Pokémon fügt es Schaden zu.'],
    [8, 'Es verlängert die Dauer von Hagel, wenn der Träger es benutzt.'] => ['Es verlängert die Dauer von Hagel, wenn der Träger es benutzt.', 'Verlängert Hagel, wenn der Träger die Attacke einsetzt.'],
    [8, 'Es verlängert die Dauer von Regentanz, wenn der Träger es benutzt.'] => ['Es verlängert die Dauer von Regentanz, wenn der Träger es benutzt.', 'Verlängert Regentanz, wenn der Träger die Attacke einsetzt.'],
    [8, 'Es verlängert die Dauer von Sandsturm, wenn der Träger es benutzt.'] => ['Es verlängert die Dauer von Sandsturm, wenn der Träger es benutzt.', 'Verlängert Sandsturm, wenn der Träger die Attacke einsetzt.'],
    [8, 'Es verlängert die Dauer von Sonnentag, wenn der Träger es benutzt.'] => ['Es verlängert die Dauer von Sonnentag, wenn der Träger es benutzt.', 'Verlängert Sonnentag, wenn der Träger die Attacke einsetzt.'],
    [8, 'Es verwandelt Z-Kraft in Kristalle, die Eevos Letzter Ausweg zu einer exklusiven Z-Attacke aufwerten.'] => ['Es verwandelt Z-Kraft in Kristalle, die Eevos Letzter Ausweg zu einer exklusiven Z-Attacke aufwerten.', 'Es verwandelt Z-Kraft in Kristalle, die Evolis Letzter Ausweg zu einer exklusiven Z-Attacke aufwerten.'],
